(window.__LIB=window.__LIB||{}).kafi={"k":"kafi","chs":[["باب أن الأرض لا تخلو من حجة",13],["باب أنه لو لم يبق في الأرض إلا رجلان لكان أحدهما الحجة",5],["باب الإشارة والنصّ على صاحب الدار (ع)",6],["باب في تسمية من رآه (ع)",15],["باب النهي عن الاسم",4],["باب نادر في حال الغيبة",3],["باب في الغيبة",31],["باب ما يفصل به بين دعوى المحقّ والمبطل في أمر الإمامة",19],["باب كراهية التوقيت",7],["باب التمحيص",6],["باب أنه من عرف إمامه لم يضرّه تقدّم هذا الأمر أو تأخّر",7],["باب من ادّعى الإمامة وليس لها بأهل، ومن جحد الأئمة (ع) أو بعضهم",12],["باب ما جاء في الاثني عشر والنصّ عليهم (ع)",20],["من الروضة (الكافي ج8): أحاديث مختارة",8]],"items":[[1,0,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى عَنْ مُحَمَّدِ بْنِ أَبِي عُمَيْرٍ عَنِ الْحُسَيْنِ بْنِ أَبِي الْعَلاءِ قَالَ قُلْتُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) تَكُونُ الارْضُ لَيْسَ فِيهَا إِمَامٌ قَالَ لا قُلْتُ يَكُونُ إِمَامَانِ قَالَ لا إِلا وَأَحَدُهُمَا صَامِتٌ.","1/4/5/1","مرآة العقول: حسن · البهبودي: صحيح"],[2,0,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ مُحَمَّدِ بْنِ أَبِي عُمَيْرٍ عَنْ مَنْصُورِ بْنِ يُونُسَ وَسَعْدَانَ بْنِ مُسْلِمٍ عَنْ إِسْحَاقَ بْنِ عَمَّارٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ سَمِعْتُهُ يَقُولُ إِنَّ الارْضَ لا تَخْلُو إِلا وَفِيهَا إِمَامٌ كَيْمَا إِنْ زَادَ الْمُؤْمِنُونَ شَيْئاً رَدَّهُمْ وَإِنْ نَقَصُوا شَيْئاً أَتَمَّهُ لَهُمْ.","1/4/5/2","مرآة العقول: حسن موثق · البهبودي: صحيح"],[3,0,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ الْحَكَمِ عَنْ رَبِيعِ بْنِ مُحَمَّدٍ الْمُسْلِيِّ عَنْ عَبْدِ الله بْنِ سُلَيْمَانَ الْعَامِرِيِّ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ مَا زَالَتِ الارْضُ إِلا وَلله فِيهَا الْحُجَّةُ يُعَرِّفُ الْحَلالَ وَالْحَرَامَ وَيَدْعُو النَّاسَ إِلَى سَبِيلِ الله.","1/4/5/3","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[4,0,"أَحْمَدُ بْنُ مِهْرَانَ عَنْ مُحَمَّدِ بْنِ عَلِيٍّ عَنِ الْحُسَيْنِ بْنِ أَبِي الْعَلاءِ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ قُلْتُ لَهُ تَبْقَى الارْضُ بِغَيْرِ إِمَامٍ قَالَ لا.","1/4/5/4","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[5,0,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عِيسَى عَنْ يُونُسَ عَنِ ابْنِ مُسْكَانَ عَنْ أَبِي بَصِيرٍ عَنْ أَحَدِهِمَا (عَلَيْهما السَّلام) قَالَ قَالَ إِنَّ الله لَمْ يَدَعِ الارْضَ بِغَيْرِ عَالِمٍ وَلَوْ لا ذَلِكَ لَمْ يُعْرَفِ الْحَقُّ مِنَ الْبَاطِلِ.","1/4/5/5","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[6,0,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْحُسَيْنِ بْنِ سَعِيدٍ عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ أَبِي حَمْزَةَ عَنْ أَبِي بَصِيرٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ إِنَّ الله أَجَلُّ وَأَعْظَمُ مِنْ أَنْ يَتْرُكَ الارْضَ بِغَيْرِ إِمَامٍ عَادِلٍ.","1/4/5/6","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[7,0,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ عَنِ الْحَسَنِ بْنِ مَحْبُوبٍ عَنْ أَبِي أُسَامَةَ وَعَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنِ الْحَسَنِ بْنِ مَحْبُوبٍ عَنْ أَبِي أُسَامَةَ وَهِشَامِ بْنِ سَالِمٍ عَنْ أَبِي حَمْزَةَ عَنْ أَبِي إِسْحَاقَ عَمَّنْ يَثِقُ بِهِ مِنْ أَصْحَابِ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) أَنَّ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) قَالَ اللهمَّ إِنَّكَ لا تُخْلِي أَرْضَكَ مِنْ حُجَّةٍ لَكَ عَلَى خَلْقِكَ.","1/4/5/7","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[8,0,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عِيسَى عَنْ مُحَمَّدِ بْنِ الْفُضَيْلِ عَنْ أَبِي حَمْزَةَ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ قَالَ وَالله مَا تَرَكَ الله أَرْضاً مُنْذُ قَبَضَ آدَمَ (عَلَيْهِ السَّلام) إِلا وَفِيهَا إِمَامٌ يُهْتَدَى بِهِ إِلَى الله وَهُوَ حُجَّتُهُ عَلَى عِبَادِهِ وَلا تَبْقَى الارْضُ بِغَيْرِ إِمَامٍ حُجَّةٍ لله عَلَى عِبَادِهِ.","1/4/5/8","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[9,0,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ بَعْضِ أَصْحَابِنَا عَنْ أَبِي عَلِيِّ بْنِ رَاشِدٍ قَالَ قَالَ أَبُو الْحَسَنِ (عَلَيْهِ السَّلام) إِنَّ الارْضَ لا تَخْلُو مِنْ حُجَّةٍ وَأَنَا وَالله ذَلِكَ الْحُجَّةُ.","1/4/5/9","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[10,0,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عِيسَى عَنْ مُحَمَّدِ بْنِ الْفُضَيْلِ عَنْ أَبِي حَمْزَةَ قَالَ قُلْتُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) أَ تَبْقَى الارْضُ بِغَيْرِ إِمَامٍ قَالَ لَوْ بَقِيَتِ الارْضُ بِغَيْرِ إِمَامٍ لَسَاخَتْ.","1/4/5/10","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[11,0,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عِيسَى عَنْ مُحَمَّدِ بْنِ الْفُضَيْلِ عَنْ أَبِي الْحَسَنِ الرِّضَا (عَلَيْهِ السَّلام) قَالَ قُلْتُ لَهُ أَ تَبْقَى الارْضُ بِغَيْرِ إِمَامٍ قَالَ لا قُلْتُ فَإِنَّا نُرَوَّى عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) أَنَّهَا لا تَبْقَى بِغَيْرِ إِمَامٍ إِلا أَنْ يَسْخَطَ الله تَعَالَى عَلَى أَهْلِ الارْضِ أَوْ عَلَى الْعِبَادِ فَقَالَ لا لا تَبْقَى إِذاً لَسَاخَتْ.","1/4/5/11","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[12,0,"عَلِيٌّ عَنْ مُحَمَّدِ بْنِ عِيسَى عَنْ أَبِي عَبْدِ الله الْمُؤْمِنِ عَنْ أَبِي هَرَاسَةَ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ لَوْ أَنَّ الامَامَ رُفِعَ مِنَ الارْضِ سَاعَةً لَمَاجَتْ بِأَهْلِهَا كَمَا يَمُوجُ الْبَحْرُ بِأَهْلِهِ.","1/4/5/12","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[13,0,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنِ الْوَشَّاءِ قَالَ سَأَلْتُ أَبَا الْحَسَنِ الرِّضَا (عَلَيْهِ السَّلام) هَلْ تَبْقَى الارْضُ بِغَيْرِ إِمَامٍ قَالَ لا قُلْتُ إِنَّا نُرَوَّى أَنَّهَا لا تَبْقَى إِلا أَنْ يَسْخَطَ الله عَزَّ وَجَلَّ عَلَى الْعِبَادِ قَالَ لا تَبْقَى إِذاً لَسَاخَتْ.","1/4/5/13","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[1,1,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ سِنَانٍ عَنِ ابْنِ الطَّيَّارِ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ لَوْ لَمْ يَبْقَ فِي الارْضِ إِلا اثْنَانِ لَكَانَ أَحَدُهُمَا الْحُجَّةَ.","1/4/6/1","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[2,1,"أَحْمَدُ بْنُ إِدْرِيسَ وَمُحَمَّدُ بْنُ يَحْيَى جَمِيعاً عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ عِيسَى بْنِ عُبَيْدٍ عَنْ مُحَمَّدِ بْنِ سِنَانٍ عَنْ حَمْزَةَ بْنِ الطَّيَّارِ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ لَوْ بَقِيَ اثْنَانِ لَكَانَ أَحَدُهُمَا الْحُجَّةَ عَلَى صَاحِبِهِ. مُحَمَّدُ بْنُ الْحَسَنِ عَنْ سَهْلِ بْنِ زِيَادٍ عَنْ مُحَمَّدِ بْنِ عِيسَى مِثْلَهُ.","1/4/6/2","مرآة العقول: ضعيف بسنديه · البهبودي: لم يخرجه"],[3,1,"مُحَمَّدُ بْنُ يَحْيَى عَمَّنْ ذَكَرَهُ عَنِ الْحَسَنِ بْنِ مُوسَى الْخَشَّابِ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ كَرَّامٍ قَالَ قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) لَوْ كَانَ النَّاسُ رَجُلَيْنِ لَكَانَ أَحَدُهُمَا الامَامَ وَقَالَ إِنَّ آخِرَ مَنْ يَمُوتُ الامَامُ لِئَلا يَحْتَجَّ أَحَدٌ عَلَى الله عَزَّ وَجَلَّ أَنَّهُ تَرَكَهُ بِغَيْرِ حُجَّةٍ لله عَلَيْهِ.","1/4/6/3","مرآة العقول: مرسل · البهبودي: لم يخرجه"],[4,1,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ الْبَرْقِيِّ عَنْ عَلِيِّ بْنِ إِسْمَاعِيلَ عَنِ ابْنِ سِنَانٍ عَنْ حَمْزَةَ بْنِ الطَّيَّارِ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ لَوْ لَمْ يَبْقَ فِي الارْضِ إِلا اثْنَانِ لَكَانَ أَحَدُهُمَا الْحُجَّةَ أَوْ الثَّانِي الْحُجَّةَ. الشَّكُّ مِنْ أَحْمَدَ بْنِ مُحَمَّدٍ.","1/4/6/4","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[5,1,"أَحْمَدُ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ الْحَسَنِ عَنِ النَّهْدِيِّ عَنْ أَبِيهِ عَنْ يُونُسَ بْنِ يَعْقُوبَ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ سَمِعْتُهُ يَقُولُ لَوْ لَمْ يَكُنْ فِي الارْضِ إِلا اثْنَانِ لَكَانَ الامَامُ أَحَدَهُمَا.","1/4/6/5","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[1,2,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ بِلالٍ قَالَ خَرَجَ إِلَيَّ مِنْ أَبِي مُحَمَّدٍ قَبْلَ مُضِيِّهِ بِسَنَتَيْنِ يُخْبِرُنِي بِالْخَلَفِ مِنْ بَعْدِهِ ثُمَّ خَرَجَ إِلَيَّ مِنْ قَبْلِ مُضِيِّهِ بِثَلاثَةِ أَيَّامٍ يُخْبِرُنِي بِالْخَلَفِ مِنْ بَعْدِهِ.","1/4/76/1","مرآة العقول: مختلف فيه · البهبودي: لم يخرجه"],[2,2,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ إِسْحَاقَ عَنْ أَبِي هَاشِمٍ الْجَعْفَرِيِّ قَالَ قُلْتُ لابِي مُحَمَّدٍ (عَلَيْهِ السَّلام) جَلالَتُكَ تَمْنَعُنِي مِنْ مَسْأَلَتِكَ فَتَأْذَنُ لِي أَنْ أَسْأَلَكَ فَقَالَ سَلْ قُلْتُ يَا سَيِّدِي هَلْ لَكَ وَلَدٌ فَقَالَ نَعَمْ فَقُلْتُ فَإِنْ حَدَثَ بِكَ حَدَثٌ فَأَيْنَ أَسْأَلُ عَنْهُ قَالَ بِالْمَدِينَةِ.","1/4/76/2","مرآة العقول: صحيح · البهبودي: صحيح"],[3,2,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ الْكُوفِيِّ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ الْمَكْفُوفِ عَنْ عَمْرٍو الاهْوَازِيِّ قَالَ أَرَانِي أَبُو مُحَمَّدٍ ابْنَهُ وَقَالَ هَذَا صَاحِبُكُمْ مِنْ بَعْدِي.","1/4/76/3","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[4,2,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ حَمْدَانَ الْقَلانِسِيِّ قَالَ قُلْتُ لِلْعَمْرِيِّ قَدْ مَضَى أَبُو مُحَمَّدٍ فَقَالَ لِي قَدْ مَضَى وَلَكِنْ قَدْ خَلَّفَ فِيكُمْ مَنْ رَقَبَتُهُ مِثْلُ هَذِهِ وَأَشَارَ بِيَدِهِ.","1/4/76/4","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[5,2,"الْحُسَيْنُ بْنُ مُحَمَّدٍ الاشْعَرِيُّ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عَبْدِ الله قَالَ خَرَجَ عَنْ أَبِي مُحَمَّدٍ (عَلَيْهِ السَّلام) حِينَ قُتِلَ الزُّبَيْرِيُّ لَعَنَهُ الله هَذَا جَزَاءُ مَنِ اجْتَرَأَ عَلَى الله فِي أَوْلِيَائِهِ يَزْعُمُ أَنَّهُ يَقْتُلُنِي وَلَيْسَ لِي عَقِبٌ فَكَيْفَ رَأَى قُدْرَةَ الله فِيهِ وَوُلِدَ لَهُ وَلَدٌ سَمَّاهُ م‏ح‏م‏د فِي سَنَةِ سِتٍّ وَخَمْسِينَ وَمِائَتَيْنِ.","1/4/76/5","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[6,2,"عَلِيُّ بْنُ مُحَمَّدٍ عَنِ الْحُسَيْنِ وَمُحَمَّدٍ ابْنَيْ عَلِيِّ بْنِ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ عَبْدِ الرَّحْمَنِ الْعَبْدِيِّ مِنْ عَبْدِ قَيْسٍ عَنْ ضَوْءِ بْنِ عَلِيٍّ الْعِجْلِيِّ عَنْ رَجُلٍ مِنْ أَهْلِ فَارِسَ سَمَّاهُ قَالَ أَتَيْتُ سَامَرَّاءَ وَلَزِمْتُ بَابَ أَبِي مُحَمَّدٍ (عَلَيْهِ السَّلام) فَدَعَانِي فَدَخَلْتُ عَلَيْهِ وَسَلَّمْتُ فَقَالَ مَا الَّذِي أَقْدَمَكَ قَالَ قُلْتُ رَغْبَةٌ فِي خِدْمَتِكَ قَالَ فَقَالَ لِي فَالْزَمِ الْبَابَ قَالَ فَكُنْتُ فِي الدَّارِ مَعَ الْخَدَمِ ثُمَّ صِرْتُ أَشْتَرِي لَهُمُ الْحَوَائِجَ مِنَ السُّوقِ وَكُنْتُ أَدْخُلُ عَلَيْهِمْ مِنْ غَيْرِ إِذْنٍ إِذَا كَانَ فِي الدَّارِ رِجَالٌ قَالَ فَدَخَلْتُ عَلَيْهِ يَوْماً وَهُوَ فِي دَارِ الرِّجَالِ فَسَمِعْتُ حَرَكَةً فِي الْبَيْتِ فَنَادَانِي مَكَانَكَ لا تَبْرَحْ فَلَمْ أَجْسُرْ أَنْ أَدْخُلَ وَلا أَخْرُجَ فَخَرَجَتْ عَلَيَّ جَارِيَةٌ مَعَهَا شَيْ‏ءٌ مُغَطًّى ثُمَّ نَادَانِيَ ادْخُلْ فَدَخَلْتُ وَنَادَى الْجَارِيَةَ فَرَجَعَتْ إِلَيْهِ فَقَالَ لَهَا اكْشِفِي عَمَّا مَعَكِ فَكَشَفَتْ عَنْ غُلامٍ أَبْيَضَ حَسَنِ الْوَجْهِ وَكَشَفَ عَنْ بَطْنِهِ فَإِذَا شَعْرٌ نَابِتٌ مِنْ لَبَّتِهِ إِلَى سُرَّتِهِ أَخْضَرُ لَيْسَ بِأَسْوَدَ فَقَالَ هَذَا صَاحِبُكُمْ ثُمَّ أَمَرَهَا فَحَمَلَتْهُ فَمَا رَأَيْتُهُ بَعْدَ ذَلِكَ حَتَّى مَضَى أَبُو مُحَمَّدٍ (عَلَيْهِ السَّلام )","1/4/76/6","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[1,3,"مُحَمَّدُ بْنُ عَبْدِ الله وَمُحَمَّدُ بْنُ يَحْيَى جَمِيعاً عَنْ عَبْدِ الله بْنِ جَعْفَرٍ الْحِمْيَرِيِّ قَالَ اجْتَمَعْتُ أَنَا وَالشَّيْخُ أَبُو عَمْرٍو رَحِمَهُ الله عِنْدَ أَحْمَدَ بْنِ إِسْحَاقَ فَغَمَزَنِي أَحْمَدُ بْنُ إِسْحَاقَ أَنْ أَسْأَلَهُ عَنِ الْخَلَفِ فَقُلْتُ لَهُ يَا أَبَا عَمْرٍو إِنِّي أُرِيدُ أَنْ أَسْأَلَكَ عَنْ شَيْ‏ءٍ وَمَا أَنَا بِشَاكٍّ فِيمَا أُرِيدُ أَنْ أَسْأَلَكَ عَنْهُ فَإِنَّ اعْتِقَادِي وَدِينِي أَنَّ الارْضَ لا تَخْلُو مِنْ حُجَّةٍ إِلا إِذَا كَانَ قَبْلَ يَوْمِ الْقِيَامَةِ بِأَرْبَعِينَ يَوْماً فَإِذَا كَانَ ذَلِكَ رُفِعَتِ الْحُجَّةُ وَأُغْلِقَ بَابُ التَّوْبَةِ فَلَمْ يَكُ يَنْفَعُ نَفْساً إِيمَانُهَا لَمْ تَكُنْ آمَنَتْ مِنْ قَبْلُ أَوْ كَسَبَتْ فِي إِيمَانِهَا خَيْراً فَأُولَئِكَ أَشْرَارٌ مِنْ خَلْقِ الله عَزَّ وَجَلَّ وَهُمُ الَّذِينَ تَقُومُ عَلَيْهِمُ الْقِيَامَةُ وَلَكِنِّي أَحْبَبْتُ أَنْ أَزْدَادَ يَقِيناً وَإِنَّ إِبْرَاهِيمَ (عَلَيْهِ السَّلام) سَأَلَ رَبَّهُ عَزَّ وَجَلَّ أَنْ يُرِيَهُ كَيْفَ يُحْيِي الْمَوْتَى قَالَ أَ وَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي وَقَدْ أَخْبَرَنِي أَبُو عَلِيٍّ أَحْمَدُ بْنُ إِسْحَاقَ عَنْ أَبِي الْحَسَنِ (عَلَيْهِ السَّلام) قَالَ سَأَلْتُهُ وَقُلْتُ مَنْ أُعَامِلُ أَوْ عَمَّنْ آخُذُ وَقَوْلَ مَنْ أَقْبَلُ فَقَالَ لَهُ الْعَمْرِيُّ ثِقَتِي فَمَا أَدَّى إِلَيْكَ عَنِّي فَعَنِّي يُؤَدِّي وَمَا قَالَ لَكَ عَنِّي فَعَنِّي يَقُولُ فَاسْمَعْ لَهُ وَأَطِعْ فَإِنَّهُ الثِّقَةُ الْمَأْمُونُ وَأَخْبَرَنِي أَبُو عَلِيٍّ أَنَّهُ سَأَلَ أَبَا مُحَمَّدٍ (عَلَيْهِ السَّلام) عَنْ مِثْلِ ذَلِكَ فَقَالَ لَهُ الْعَمْرِيُّ وَابْنُهُ ثِقَتَانِ فَمَا أَدَّيَا إِلَيْكَ عَنِّي فَعَنِّي يُؤَدِّيَانِ وَمَا قَالا لَكَ فَعَنِّي يَقُولانِ فَاسْمَعْ لَهُمَا وَأَطِعْهُمَا فَإِنَّهُمَا الثِّقَتَانِ الْمَأْمُونَانِ فَهَذَا قَوْلُ إِمَامَيْنِ قَدْ مَضَيَا فِيكَ قَالَ فَخَرَّ أَبُو عَمْرٍو سَاجِداً وَبَكَى ثُمَّ قَالَ سَلْ حَاجَتَكَ فَقُلْتُ لَهُ أَنْتَ رَأَيْتَ الْخَلَفَ مِنْ بَعْدِ أَبِي مُحَمَّدٍ (عَلَيْهِ السَّلام) فَقَالَ إِي وَالله وَرَقَبَتُهُ مِثْلُ ذَا وَأَوْمَأَ بِيَدِهِ فَقُلْتُ لَهُ فَبَقِيَتْ وَاحِدَةٌ فَقَالَ لِي هَاتِ قُلْتُ فَالاسْمُ قَالَ مُحَرَّمٌ عَلَيْكُمْ أَنْ تَسْأَلُوا عَنْ ذَلِكَ وَلا أَقُولُ هَذَا مِنْ عِنْدِي فَلَيْسَ لِي أَنْ أُحَلِّلَ وَلا أُحَرِّمَ وَلَكِنْ عَنْهُ (عَلَيْهِ السَّلام) فَإِنَّ الامْرَ عِنْدَ السُّلْطَانِ أَنَّ أَبَا مُحَمَّدٍ مَضَى وَلَمْ يُخَلِّفْ وَلَداً وَقَسَّمَ مِيرَاثَهُ وَأَخَذَهُ مَنْ لا حَقَّ لَهُ فِيهِ وَهُوَ ذَا عِيَالُهُ يَجُولُونَ لَيْسَ أَحَدٌ يَجْسُرُ أَنْ يَتَعَرَّفَ إِلَيْهِمْ أَوْ يُنِيلَهُمْ شَيْئاً وَإِذَا وَقَعَ الاسْمُ وَقَعَ الطَّلَبُ فَاتَّقُوا الله وَأَمْسِكُوا عَنْ ذَلِكَ. قَالَ الْكُلَيْنِيُّ رَحِمَهُ الله وَحَدَّثَنِي شَيْخٌ مِنْ أَصْحَابِنَا ذَهَبَ عَنِّي اسْمُهُ أَنَّ أَبَا عَمْرٍو سَأَلَ عَنْ أَحْمَدَ بْنِ إِسْحَاقَ عَنْ مِثْلِ هَذَا فَأَجَابَ بِمِثْلِ هَذَا.","1/4/77/1","مرآة العقول: صحيح وسنده التي مرسل · البهبودي: صحيح"],[2,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ إِسْمَاعِيلَ بْنِ مُوسَى بْنِ جَعْفَرٍ وَكَانَ أَسَنَّ شَيْخٍ مِنْ وُلْدِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) بِالْعِرَاقِ فَقَالَ رَأَيْتُهُ بَيْنَ الْمَسْجِدَيْنِ وَهُوَ غُلامٌ (عَلَيْهِ السَّلام )","1/4/77/2","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[3,3,"مُحَمَّدُ بْنُ يَحْيَى عَنِ الْحُسَيْنِ بْنِ رِزْقِ الله أَبُو عَبْدِ الله قَالَ حَدَّثَنِي مُوسَى بْنُ مُحَمَّدِ بْنِ الْقَاسِمِ بْنِ حَمْزَةَ بْنِ مُوسَى بْنِ جَعْفَرٍ قَالَ حَدَّثَتْنِي حَكِيمَةُ ابْنَةُ مُحَمَّدِ بْنِ عَلِيٍّ وَهِيَ عَمَّةُ أَبِيهِ أَنَّهَا رَأَتْهُ لَيْلَةَ مَوْلِدِهِ وَبَعْدَ ذَلِكَ.","1/4/77/3","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[4,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ حَمْدَانَ الْقَلانِسِيِّ قَالَ قُلْتُ لِلْعَمْرِيِّ قَدْ مَضَى أَبُو مُحَمَّدٍ (عَلَيْهِ السَّلام) فَقَالَ قَدْ مَضَى وَلَكِنْ قَدْ خَلَّفَ فِيكُمْ مَنْ رَقَبَتُهُ مِثْلُ هَذَا وَأَشَارَ بِيَدِهِ.","1/4/77/4","مرآة العقول: مختلف فيه · البهبودي: لم يخرجه"],[5,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ فَتْحٍ مَوْلَى الزُّرَارِيِّ قَالَ سَمِعْتُ أَبَا عَلِيِّ بْنَ مُطَهَّرٍ يَذْكُرُ أَنَّهُ قَدْ رَآهُ وَوَصَفَ لَهُ قَدَّهُ.","1/4/77/5","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[6,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ شَاذَانَ بْنِ نُعَيْمٍ عَنْ خَادِمٍ لابْرَاهِيمَ بْنِ عَبْدَةَ النَّيْسَابُورِيِّ أَنَّهَا قَالَتْ كُنْتُ وَاقِفَةً مَعَ إِبْرَاهِيمَ عَلَى الصَّفَا فَجَاءَ (عَلَيْهِ السَّلام) حَتَّى وَقَفَ عَلَى إِبْرَاهِيمَ وَقَبَضَ عَلَى كِتَابِ مَنَاسِكِهِ وَحَدَّثَهُ بِأَشْيَاءَ.","1/4/77/6","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[7,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ إِبْرَاهِيمَ عَنْ أَبِي عَبْدِ الله بْنِ صَالِحٍ أَنَّهُ رَآهُ عِنْدَ الْحَجَرِ الاسْوَدِ وَالنَّاسُ يَتَجَاذَبُونَ عَلَيْهِ وَهُوَ يَقُولُ مَا بِهَذَا أُمِرُوا.","1/4/77/7","مرآة العقول: صحيح على الظاهر · البهبودي: لم يخرجه"],[8,3,"عَلِيٌّ عَنْ أَبِي عَلِيٍّ أَحْمَدَ بْنِ إِبْرَاهِيمَ بْنِ إِدْرِيسَ عَنْ أَبِيهِ أَنَّهُ قَالَ رَأَيْتُهُ (عَلَيْهِ السَّلام) بَعْدَ مُضِيِّ أَبِي مُحَمَّدٍ حِينَ أَيْفَعَ وَقَبَّلْتُ يَدَيْهِ وَرَأْسَهُ.","1/4/77/8","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[9,3,"عَلِيٌّ عَنْ أَبِي عَبْدِ الله بْنِ صَالِحٍ وَأَحْمَدَ بْنِ النَّضْرِ عَنِ الْقَنْبَرِيِّ رَجُلٌ مِنْ وُلْدِ قَنْبَرٍ الْكَبِيرِ مَوْلَى أَبِي الْحَسَنِ الرِّضَا (عَلَيْهِ السَّلام) قَالَ جَرَى حَدِيثُ جَعْفَرِ بْنِ عَلِيٍّ فَذَمَّهُ فَقُلْتُ لَهُ فَلَيْسَ غَيْرُهُ فَهَلْ رَأَيْتَهُ فَقَالَ لَمْ أَرَهُ وَلَكِنْ رَآهُ غَيْرِي قُلْتُ وَمَنْ رَآهُ قَالَ قَدْ رَآهُ جَعْفَرٌ مَرَّتَيْنِ وَلَهُ حَدِيثٌ.","1/4/77/9","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[10,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ أَبِي مُحَمَّدٍ الْوَجْنَانِيِّ أَنَّهُ أَخْبَرَنِي عَمَّنْ رَآهُ أَنَّهُ خَرَجَ مِنَ الدَّارِ قَبْلَ الْحَادِثِ بِعَشَرَةِ أَيَّامٍ وَهُوَ يَقُولُ اللهمَّ إِنَّكَ تَعْلَمُ أَنَّهَا مِنْ أَحَبِّ الْبِقَاعِ لَوْ لا الطَّرْدُ أَوْ كَلامٌ هَذَا نَحْوُهُ.","1/4/77/10","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[11,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ قَيْسٍ عَنْ بَعْضِ جَلاوِزَةِ السَّوَادِ قَالَ شَاهَدْتُ سِيمَاءَ آنِفاً بِسُرَّ مَنْ رَأَى وَقَدْ كَسَرَ بَابَ الدَّارِ فَخَرَجَ عَلَيْهِ وَبِيَدِهِ طَبَرْزِينٌ فَقَالَ لَهُ مَا تَصْنَعُ فِي دَارِي فَقَالَ سِيمَاءُ إِنَّ جَعْفَراً زَعَمَ أَنَّ أَبَاكَ مَضَى وَلا وَلَدَ لَهُ فَإِنْ كَانَتْ دَارَكَ فَقَدِ انْصَرَفْتُ عَنْكَ فَخَرَجَ عَنِ الدَّارِ قَالَ عَلِيُّ بْنُ قَيْسٍ فَخَرَجَ عَلَيْنَا خَادِمٌ مِنْ خَدَمِ الدَّارِ فَسَأَلْتُهُ عَنْ هَذَا الْخَبَرِ فَقَالَ لِي مَنْ حَدَّثَكَ بِهَذَا فَقُلْتُ لَهُ حَدَّثَنِي بَعْضُ جَلاوِزَةِ السَّوَادِ فَقَالَ لِي لا يَكَادُ يَخْفَى عَلَى النَّاسِ شَيْ‏ءٌ.","1/4/77/11","مرآة العقول: مجهول أيض ا · البهبودي: لم يخرجه"],[12,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ الْكُوفِيِّ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ الْمَكْفُوفِ عَنْ عَمْرٍو الاهْوَازِيِّ قَالَ أَرَانِيهِ أَبُو مُحَمَّدٍ (عَلَيْهِ السَّلام) وَقَالَ هَذَا صَاحِبُكُمْ.","1/4/77/12","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[13,3,"مُحَمَّدُ بْنُ يَحْيَى عَنِ الْحَسَنِ بْنِ عَلِيٍّ النَّيْسَابُورِيِّ عَنْ إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ عَبْدِ الله بْنِ مُوسَى بْنِ جَعْفَرٍ عَنْ أَبِي نَصْرٍ ظَرِيفٍ الْخَادِمِ أَنَّهُ رَآهُ.","1/4/77/13","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[14,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدٍ وَالْحَسَنِ ابْنَيْ عَلِيِّ بْنِ إِبْرَاهِيمَ أَنَّهُمَا حَدَّثَاهُ فِي سَنَةِ تِسْعٍ وَسَبْعِينَ وَمِائَتَيْنِ عَنْ مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ الْعَبْدِيِّ عَنْ ضَوْءِ بْنِ عَلِيٍّ الْعِجْلِيِّ عَنْ رَجُلٍ مِنْ أَهْلِ فَارِسَ سَمَّاهُ أَنَّ أَبَا مُحَمَّدٍ أَرَاهُ إِيَّاهُ.","1/4/77/14","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[15,3,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ أَبِي أَحْمَدَ بْنِ رَاشِدٍ عَنْ بَعْضِ أَهْلِ الْمَدَائِنِ قَالَ كُنْتُ حَاجّاً مَعَ رَفِيقٍ لِي فَوَافَيْنَا إِلَى الْمَوْقِفِ فَإِذَا شَابٌّ قَاعِدٌ عَلَيْهِ إِزَارٌ وَرِدَاءٌ وَفِي رِجْلَيْهِ نَعْلٌ صَفْرَاءُ قَوَّمْتُ الازَارَ وَالرِّدَاءَ بِمِائَةٍ وَخَمْسِينَ دِينَاراً وَلَيْسَ عَلَيْهِ أَثَرُ السَّفَرِ فَدَنَا مِنَّا سَائِلٌ فَرَدَدْنَاهُ فَدَنَا مِنَ الشَّابِّ فَسَأَلَهُ فَحَمَلَ شَيْئاً مِنَ الارْضِ وَنَاوَلَهُ فَدَعَا لَهُ السَّائِلُ وَاجْتَهَدَ فِي الدُّعَاءِ وَأَطَالَ فَقَامَ الشَّابُّ وَغَابَ عَنَّا فَدَنَوْنَا مِنَ السَّائِلِ فَقُلْنَا لَهُ وَيْحَكَ مَا أَعْطَاكَ فَأَرَانَا حَصَاةَ ذَهَبٍ مُضَرَّسَةً قَدَّرْنَاهَا عِشْرِينَ مِثْقَالاً فَقُلْتُ لِصَاحِبِي مَوْلانَا عِنْدَنَا وَنَحْنُ لا نَدْرِي ثُمَّ ذَهَبْنَا فِي طَلَبِهِ فَدُرْنَا الْمَوْقِفَ كُلَّهُ فَلَمْ نَقْدِرْ عَلَيْهِ فَسَأَلْنَا كُلَّ مَنْ كَانَ حَوْلَهُ مِنْ أَهْلِ مَكَّةَ وَالْمَدِينَةِ فَقَالُوا شَابٌّ عَلَوِيٌّ يَحُجُّ فِي كُلِّ سَنَةٍ مَاشِياً.","1/4/77/15","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[1,4,"عَلِيُّ بْنُ مُحَمَّدٍ عَمَّنْ ذَكَرَهُ عَنْ مُحَمَّدِ بْنِ أَحْمَدَ الْعَلَوِيِّ عَنْ دَاوُدَ بْنِ الْقَاسِمِ الْجَعْفَرِيِّ قَالَ سَمِعْتُ أَبَا الْحَسَنِ الْعَسْكَرِيَّ (عَلَيْهِ السَّلام) يَقُولُ الْخَلَفُ مِنْ بَعْدِي الْحَسَنُ فَكَيْفَ لَكُمْ بِالْخَلَفِ مِنْ بَعْدِ الْخَلَفِ فَقُلْتُ وَلِمَ جَعَلَنِيَ الله فِدَاكَ قَالَ إِنَّكُمْ لا تَرَوْنَ شَخْصَهُ وَلا يَحِلُّ لَكُمْ ذِكْرُهُ بِاسْمِهِ فَقُلْتُ فَكَيْفَ نَذْكُرُهُ فَقَالَ قُولُوا الْحُجَّةُ مِنْ آلِ مُحَمَّدٍ صَلَوَاتُ الله عَلَيْهِ وَسَلامُهُ.","1/4/78/1","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[2,4,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ أَبِي عَبْدِ الله الصَّالِحِيِّ قَالَ سَأَلَنِي أَصْحَابُنَا بَعْدَ مُضِيِّ أَبِي مُحَمَّدٍ (عَلَيْهِ السَّلام) أَنْ أَسْأَلَ عَنِ الاسْمِ وَالْمَكَانِ فَخَرَجَ الْجَوَابُ إِنْ دَلَلْتُهُمْ عَلَى الاسْمِ أَذَاعُوهُ وَإِنْ عَرَفُوا الْمَكَانَ دَلُّوا عَلَيْهِ.","1/4/78/2","البهبودي: لم يخرجه"],[3,4,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ ابْنِ فَضَّالٍ عَنِ الرَّيَّانِ بْنِ الصَّلْتِ قَالَ سَمِعْتُ أَبَا الْحَسَنِ الرِّضَا (عَلَيْهِ السَّلام) يَقُولُ وَسُئِلَ عَنِ الْقَائِمِ فَقَالَ لا يُرَى جِسْمُهُ وَلا يُسَمَّى اسْمُهُ.","1/4/78/3","مرآة العقول: موثق · البهبودي: لم يخرجه"],[4,4,"مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنِ الْحَسَنِ بْنِ مَحْبُوبٍ عَنِ ابْنِ رِئَابٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ صَاحِبُ هَذَا الامْرِ لا يُسَمِّيهِ بِاسْمِهِ إِلا كَافِرٌ.","1/4/78/4","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[1,5,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ مُحَمَّدِ بْنِ خَالِدٍ عَمَّنْ حَدَّثَهُ عَنِ الْمُفَضَّلِ بْنِ عُمَرَ وَمُحَمَّدُ بْنُ يَحْيَى عَنْ عَبْدِ الله بْنِ مُحَمَّدِ بْنِ عِيسَى عَنْ أَبِيهِ عَنْ بَعْضِ أَصْحَابِهِ عَنِ الْمُفَضَّلِ بْنِ عُمَرَ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ أَقْرَبُ مَا يَكُونُ الْعِبَادُ مِنَ الله جَلَّ ذِكْرُهُ وَأَرْضَى مَا يَكُونُ عَنْهُمْ إِذَا افْتَقَدُوا حُجَّةَ الله جَلَّ وَعَزَّ وَلَمْ يَظْهَرْ لَهُمْ وَلَمْ يَعْلَمُوا مَكَانَهُ وَهُمْ فِي ذَلِكَ يَعْلَمُونَ أَنَّهُ لَمْ تَبْطُلْ حُجَّةُ الله جَلَّ ذِكْرُهُ وَلا مِيثَاقُهُ فَعِنْدَهَا فَتَوَقَّعُوا الْفَرَجَ صَبَاحاً وَمَسَاءً فَإِنَّ أَشَدَّ مَا يَكُونُ غَضَبُ الله عَلَى أَعْدَائِهِ إِذَا افْتَقَدُوا حُجَّتَهُ وَلَمْ يَظْهَرْ لَهُمْ وَقَدْ عَلِمَ أَنَّ أَوْلِيَاءَهُ لا يَرْتَابُونَ وَلَوْ عَلِمَ أَنَّهُمْ يَرْتَابُونَ مَا غَيَّبَ حُجَّتَهُ عَنْهُمْ طَرْفَةَ عَيْنٍ وَلا يَكُونُ ذَلِكَ إِلا عَلَى رَأْسِ شِرَارِ النَّاسِ.","1/4/79/1","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[2,5,"الْحُسَيْنُ بْنُ مُحَمَّدٍ الاشْعَرِيُّ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ مِرْدَاسٍ عَنْ صَفْوَانَ بْنِ يَحْيَى وَالْحَسَنِ بْنِ مَحْبُوبٍ عَنْ هِشَامِ بْنِ سَالِمٍ عَنْ عَمَّارٍ السَّابَاطِيِّ قَالَ قُلْتُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) أَيُّمَا أَفْضَلُ الْعِبَادَةُ فِي السِّرِّ مَعَ الامَامِ مِنْكُمُ الْمُسْتَتِرِ فِي دَوْلَةِ الْبَاطِلِ أَوِ الْعِبَادَةُ فِي ظُهُورِ الْحَقِّ وَدَوْلَتِهِ مَعَ الامَامِ مِنْكُمُ الظَّاهِرِ فَقَالَ يَا عَمَّارُ الصَّدَقَةُ فِي السِّرِّ وَالله أَفْضَلُ مِنَ الصَّدَقَةِ فِي الْعَلانِيَةِ وَكَذَلِكَ وَالله عِبَادَتُكُمْ فِي السِّرِّ مَعَ إِمَامِكُمُ الْمُسْتَتِرِ فِي دَوْلَةِ الْبَاطِلِ وَتَخَوُّفُكُمْ مِنْ عَدُوِّكُمْ فِي دَوْلَةِ الْبَاطِلِ وَحَالِ الْهُدْنَةِ أَفْضَلُ مِمَّنْ يَعْبُدُ الله عَزَّ وَجَلَّ ذِكْرُهُ فِي ظُهُورِ الْحَقِّ مَعَ إِمَامِ الْحَقِّ الظَّاهِرِ فِي دَوْلَةِ الْحَقِّ وَلَيْسَتِ الْعِبَادَةُ مَعَ الْخَوْفِ فِي دَوْلَةِ الْبَاطِلِ مِثْلَ الْعِبَادَةِ وَالامْنِ فِي دَوْلَةِ الْحَقِّ وَاعْلَمُوا أَنَّ مَنْ صَلَّى مِنْكُمُ الْيَوْمَ صَلاةً فَرِيضَةً فِي جَمَاعَةٍ مُسْتَتِرٍ بِهَا مِنْ عَدُوِّهِ فِي وَقْتِهَا فَأَتَمَّهَا كَتَبَ الله لَهُ خَمْسِينَ صَلاةً فَرِيضَةً فِي جَمَاعَةٍ وَمَنْ صَلَّى مِنْكُمْ صَلاةً فَرِيضَةً وَحْدَهُ مُسْتَتِراً بِهَا مِنْ عَدُوِّهِ فِي وَقْتِهَا فَأَتَمَّهَا كَتَبَ الله عَزَّ وَجَلَّ بِهَا لَهُ خَمْساً وَعِشْرِينَ صَلاةً فَرِيضَةً وَحْدَانِيَّةً وَمَنْ صَلَّى مِنْكُمْ صَلاةً نَافِلَةً لِوَقْتِهَا فَأَتَمَّهَا كَتَبَ الله لَهُ بِهَا عَشْرَ صَلَوَاتٍ نَوَافِلَ وَمَنْ عَمِلَ مِنْكُمْ حَسَنَةً كَتَبَ الله عَزَّ وَجَلَّ لَهُ بِهَا عِشْرِينَ حَسَنَةً وَيُضَاعِفُ الله عَزَّ وَجَلَّ حَسَنَاتِ الْمُؤْمِنِ مِنْكُمْ إِذَا أَحْسَنَ أَعْمَالَهُ وَدَانَ بِالتَّقِيَّةِ عَلَى دِينِهِ وَإِمَامِهِ وَنَفْسِهِ وَأَمْسَكَ مِنْ لِسَانِهِ أَضْعَافاً مُضَاعَفَةً إِنَّ الله عَزَّ وَجَلَّ كَرِيمٌ قُلْتُ جُعِلْتُ فِدَاكَ قَدْ وَالله رَغَّبْتَنِي فِي الْعَمَلِ وَحَثَثْتَنِي عَلَيْهِ وَلَكِنْ أُحِبُّ أَنْ أَعْلَمَ كَيْفَ صِرْنَا نَحْنُ الْيَوْمَ أَفْضَلَ أَعْمَالاً مِنْ أَصْحَابِ الامَامِ الظَّاهِرِ مِنْكُمْ فِي دَوْلَةِ الْحَقِّ وَنَحْنُ عَلَى دِينٍ وَاحِدٍ فَقَالَ إِنَّكُمْ سَبَقْتُمُوهُمْ إِلَى الدُّخُولِ فِي دِينِ الله عَزَّ وَجَلَّ وَإِلَى الصَّلاةِ وَالصَّوْمِ وَالْحَجِّ وَإِلَى كُلِّ خَيْرٍ وَفِقْهٍ وَإِلَى عِبَادَةِ الله عَزَّ ذِكْرُهُ سِرّاً مِنْ عَدُوِّكُمْ مَعَ إِمَامِكُمُ الْمُسْتَتِرِ مُطِيعِينَ لَهُ صَابِرِينَ مَعَهُ مُنْتَظِرِينَ لِدَوْلَةِ الْحَقِّ خَائِفِينَ عَلَى إِمَامِكُمْ وَأَنْفُسِكُمْ مِنَ الْمُلُوكِ الظَّلَمَةِ تَنْتَظِرُونَ إِلَى حَقِّ إِمَامِكُمْ وَحُقُوقِكُمْ فِي أَيْدِي الظَّلَمَةِ قَدْ مَنَعُوكُمْ ذَلِكَ وَاضْطَرُّوكُمْ إِلَى حَرْثِ الدُّنْيَا وَطَلَبِ الْمَعَاشِ مَعَ الصَّبْرِ عَلَى دِينِكُمْ وَعِبَادَتِكُمْ وَطَاعَةِ إِمَامِكُمْ وَالْخَوْفِ مَعَ عَدُوِّكُمْ فَبِذَلِكَ ضَاعَفَ الله عَزَّ وَجَلَّ لَكُمُ الاعْمَالَ فَهَنِيئاً لَكُمْ قُلْتُ جُعِلْتُ فِدَاكَ فَمَا تَرَى إِذاً أَنْ نَكُونَ مِنْ أَصْحَابِ الْقَائِمِ وَيَظْهَرَ الْحَقُّ وَنَحْنُ الْيَوْمَ فِي إِمَامَتِكَ وَطَاعَتِكَ أَفْضَلُ أَعْمَالاً مِنْ أَصْحَابِ دَوْلَةِ الْحَقِّ وَالْعَدْلِ فَقَالَ سُبْحَانَ الله أَ مَا تُحِبُّونَ أَنْ يُظْهِرَ الله تَبَارَكَ وَتَعَالَى الْحَقَّ وَالْعَدْلَ فِي الْبِلادِ وَيَجْمَعَ الله الْكَلِمَةَ وَيُؤَلِّفَ الله بَيْنَ قُلُوبٍ مُخْتَلِفَةٍ وَلا يَعْصُونَ الله عَزَّ وَجَلَّ فِي أَرْضِهِ وَتُقَامَ حُدُودُهُ فِي خَلْقِهِ وَيَرُدَّ الله الْحَقَّ إِلَى أَهْلِهِ فَيَظْهَرَ حَتَّى لا يُسْتَخْفَى بِشَيْ‏ءٍ مِنَ الْحَقِّ مَخَافَةَ أَحَدٍ مِنَ الْخَلْقِ أَمَا وَالله يَا عَمَّارُ لا يَمُوتُ مِنْكُمْ مَيِّتٌ عَلَى الْحَالِ الَّتِي أَنْتُمْ عَلَيْهَا إِلا كَانَ أَفْضَلَ عِنْدَ الله مِنْ كَثِيرٍ مِنْ شُهَدَاءِ بَدْرٍ وَأُحُدٍ فَأَبْشِرُوا.","1/4/79/2","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[3,5,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ عَنِ ابْنِ مَحْبُوبٍ عَنْ أَبِي أُسَامَةَ عَنْ هِشَامٍ وَمُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ مَحْبُوبٍ عَنْ هِشَامِ بْنِ سَالِمٍ عَنْ أَبِي حَمْزَةَ عَنْ أَبِي إِسْحَاقَ قَالَ حَدَّثَنِي الثِّقَةُ مِنْ أَصْحَابِ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) أَنَّهُمْ سَمِعُوا أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) يَقُولُ فِي خُطْبَةٍ لَهُ اللهمَّ وَإِنِّي لاعْلَمُ أَنَّ الْعِلْمَ لا يَأْرِزُ كُلُّهُ وَلا يَنْقَطِعُ مَوَادُّهُ وَأَنَّكَ لا تُخْلِي أَرْضَكَ مِنْ حُجَّةٍ لَكَ عَلَى خَلْقِكَ ظَاهِرٍ لَيْسَ بِالْمُطَاعِ أَوْ خَائِفٍ مَغْمُورٍ كَيْلا تَبْطُلَ حُجَجُكَ وَلا يَضِلَّ أَوْلِيَاؤُكَ بَعْدَ إِذْ هَدَيْتَهُمْ بَلْ أَيْنَ هُمْ وَكَمْ أُولَئِكَ الاقَلُّونَ عَدَداً وَالاعْظَمُونَ عِنْدَ الله جَلَّ ذِكْرُهُ قَدْراً الْمُتَّبِعُونَ لِقَادَةِ الدِّينِ الائِمَّةِ الْهَادِينَ الَّذِينَ يَتَأَدَّبُونَ بِ‏آدَابِهِمْ وَيَنْهَجُونَ نَهْجَهُمْ فَعِنْدَ ذَلِكَ يَهْجُمُ بِهِمُ الْعِلْمُ عَلَى حَقِيقَةِ الايمَانِ فَتَسْتَجِيبُ أَرْوَاحُهُمْ لِقَادَةِ الْعِلْمِ وَيَسْتَلِينُونَ مِنْ حَدِيثِهِمْ مَا اسْتَوْعَرَ عَلَى غَيْرِهِمْ وَيَأْنَسُونَ بِمَا اسْتَوْحَشَ مِنْهُ الْمُكَذِّبُونَ وَأَبَاهُ الْمُسْرِفُونَ أُولَئِكَ أَتْبَاعُ الْعُلَمَاءِ صَحِبُوا أَهْلَ الدُّنْيَا بِطَاعَةِ الله تَبَارَكَ وَتَعَالَى وَأَوْلِيَائِهِ وَدَانُوا بِالتَّقِيَّةِ عَنْ دِينِهِمْ وَالْخَوْفِ مِنْ عَدُوِّهِمْ فَأَرْوَاحُهُمْ مُعَلَّقَةٌ بِالْمَحَلِّ الاعْلَى فَعُلَمَاؤُهُمْ وَأَتْبَاعُهُمْ خُرْسٌ صُمْتٌ فِي دَوْلَةِ الْبَاطِلِ مُنْتَظِرُونَ لِدَوْلَةِ الْحَقِّ وَسَيُحِقُّ الله الْحَقَّ بِكَلِمَاتِهِ وَيَمْحَقُ الْبَاطِلَ هَا هَا طُوبَى لَهُمْ عَلَى صَبْرِهِمْ عَلَى دِينِهِمْ فِي حَالِ هُدْنَتِهِمْ وَيَا شَوْقَاهْ إِلَى رُؤْيَتِهِمْ فِي حَالِ ظُهُورِ دَوْلَتِهِمْ وَسَيَجْمَعُنَا الله وَإِيَّاهُمْ فِي جَنَّاتِ عَدْنٍ وَمَنْ صَلَحَ مِنْ آبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ.","1/4/79/3","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[1,6,"مُحَمَّدُ بْنُ يَحْيَى وَالْحَسَنُ بْنُ مُحَمَّدٍ جَمِيعاً عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ الْكُوفِيِّ عَنِ الْحَسَنِ بْنِ مُحَمَّدٍ الصَّيْرَفِيِّ عَنْ صَالِحِ بْنِ خَالِدٍ عَنْ يَمَانٍ التَّمَّارِ قَالَ كُنَّا عِنْدَ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) جُلُوساً فَقَالَ لَنَا إِنَّ لِصَاحِبِ هَذَا الامْرِ غَيْبَةً الْمُتَمَسِّكُ فِيهَا بِدِينِهِ كَالْخَارِطِ لِلْقَتَادِ ثُمَّ قَالَ هَكَذَا بِيَدِهِ فَأَيُّكُمْ يُمْسِكُ شَوْكَ الْقَتَادِ بِيَدِهِ ثُمَّ أَطْرَقَ مَلِيّاً ثُمَّ قَالَ إِنَّ لِصَاحِبِ هَذَا الامْرِ غَيْبَةً فَلْيَتَّقِ الله عَبْدٌ وَلْيَتَمَسَّكْ بِدِينِهِ.","1/4/80/1","مرآة العقول: مجهول أو ضعيف على المشهور · البهبودي: لم يخرجه"],[2,6,"عَلِيُّ بْنُ مُحَمَّدٍ عَنِ الْحَسَنِ بْنِ عِيسَى بْنِ مُحَمَّدِ بْنِ عَلِيِّ بْنِ جَعْفَرٍ عَنْ أَبِيهِ عَنْ جَدِّهِ عَنْ عَلِيِّ بْنِ جَعْفَرٍ عَنْ أَخِيهِ مُوسَى بْنِ جَعْفَرٍ (عَلَيْهما السَّلام) قَالَ إِذَا فُقِدَ الْخَامِسُ مِنْ وُلْدِ السَّابِعِ فَالله الله فِي أَدْيَانِكُمْ لا يُزِيلُكُمْ عَنْهَا أَحَدٌ يَا بُنَيَّ إِنَّهُ لا بُدَّ لِصَاحِبِ هَذَا الامْرِ مِنْ غَيْبَةٍ حَتَّى يَرْجِعَ عَنْ هَذَا الامْرِ مَنْ كَانَ يَقُولُ بِهِ إِنَّمَا هِيَ مِحْنَةٌ مِنَ الله عَزَّ وَجَلَّ امْتَحَنَ بِهَا خَلْقَهُ لَوْ عَلِمَ آبَاؤُكُمْ وَأَجْدَادُكُمْ دِيناً أَصَحَّ مِنْ هَذَا لاتَّبَعُوهُ قَالَ فَقُلْتُ يَا سَيِّدِي مَنِ الْخَامِسُ مِنْ وُلْدِ السَّابِعِ فَقَالَ يَا بُنَيَّ عُقُولُكُمْ تَصْغُرُ عَنْ هَذَا وَأَحْلامُكُمْ تَضِيقُ عَنْ حَمْلِهِ وَلَكِنْ إِنْ تَعِيشُوا فَسَوْفَ تُدْرِكُونَهُ.","1/4/80/2","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[3,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ أَبِي نَجْرَانَ عَنْ مُحَمَّدِ بْنِ الْمُسَاوِرِ عَنِ الْمُفَضَّلِ بْنِ عُمَرَ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِيَّاكُمْ وَالتَّنْوِيهَ أَمَا وَالله لَيَغِيبَنَّ إِمَامُكُمْ سِنِيناً مِنْ دَهْرِكُمْ وَلَتُمَحَّصُنَّ حَتَّى يُقَالَ مَاتَ قُتِلَ هَلَكَ بِأَيِّ وَادٍ سَلَكَ وَلَتَدْمَعَنَّ عَلَيْهِ عُيُونُ الْمُؤْمِنِينَ وَلَتُكْفَؤُنَّ كَمَا تُكْفَأُ السُّفُنُ فِي أَمْوَاجِ الْبَحْرِ فَلا يَنْجُو إِلا مَنْ أَخَذَ الله مِيثَاقَهُ وَكَتَبَ فِي قَلْبِهِ الايمَانَ وَأَيَّدَهُ بِرُوحٍ مِنْهُ وَلَتُرْفَعَنَّ اثْنَتَا عَشْرَةَ رَايَةً مُشْتَبِهَةً لا يُدْرَى أَيٌّ مِنْ أَيٍّ قَالَ فَبَكَيْتُ ثُمَّ قُلْتُ فَكَيْفَ نَصْنَعُ قَالَ فَنَظَرَ إِلَى شَمْسٍ دَاخِلَةٍ فِي الصُّفَّةِ فَقَالَ يَا أَبَا عَبْدِ الله تَرَى هَذِهِ الشَّمْسَ قُلْتُ نَعَمْ فَقَالَ وَالله لامْرُنَا أَبْيَنُ مِنْ هَذِهِ الشَّمْسِ.","1/4/80/3","مرآة العقول: مجهول وقيل ضعيف · البهبودي: لم يخرجه"],[4,6,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنِ ابْنِ أَبِي نَجْرَانَ عَنْ فَضَالَةَ بْنِ أَيُّوبَ عَنْ سَدِيرٍ الصَّيْرَفِيِّ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِنَّ فِي صَاحِبِ هَذَا الامْرِ شَبَهاً مِنْ يُوسُفَ (عَلَيْهِ السَّلام) قَالَ قُلْتُ لَهُ كَأَنَّكَ تَذْكُرُهُ حَيَاتَهُ أَوْ غَيْبَتَهُ قَالَ فَقَالَ لِي وَمَا يُنْكَرُ مِنْ ذَلِكَ هَذِهِ الامَّةُ أَشْبَاهُ الْخَنَازِيرِ إِنَّ إِخْوَةَ يُوسُفَ (عَلَيْهِ السَّلام) كَانُوا أَسْبَاطاً أَوْلادَ الانْبِيَاءِ تَاجَرُوا يُوسُفَ وَبَايَعُوهُ وَخَاطَبُوهُ وَهُمْ إِخْوَتُهُ وَهُوَ أَخُوهُمْ فَلَمْ يَعْرِفُوهُ حَتَّى قَالَ أَنَا يُوسُفُ وَهَذَا أَخِي فَمَا تُنْكِرُ هَذِهِ الامَّةُ الْمَلْعُونَةُ أَنْ يَفْعَلَ الله عَزَّ وَجَلَّ بِحُجَّتِهِ فِي وَقْتٍ مِنَ الاوْقَاتِ كَمَا فَعَلَ بِيُوسُفَ إِنَّ يُوسُفَ (عَلَيْهِ السَّلام) كَانَ إِلَيْهِ مُلْكُ مِصْرَ وَكَانَ بَيْنَهُ وَبَيْنَ وَالِدِهِ مَسِيرَةُ ثَمَانِيَةَ عَشَرَ يَوْماً فَلَوْ أَرَادَ أَنْ يُعْلِمَهُ لَقَدَرَ عَلَى ذَلِكَ لَقَدْ سَارَ يَعْقُوبُ (عَلَيْهِ السَّلام) وَوُلْدُهُ عِنْدَ الْبِشَارَةِ تِسْعَةَ أَيَّامٍ مِنْ بَدْوِهِمْ إِلَى مِصْرَ فَمَا تُنْكِرُ هَذِهِ الامَّةُ أَنْ يَفْعَلَ الله جَلَّ وَعَزَّ بِحُجَّتِهِ كَمَا فَعَلَ بِيُوسُفَ أَنْ يَمْشِيَ فِي أَسْوَاقِهِمْ وَيَطَأَ بُسُطَهُمْ حَتَّى يَأْذَنَ الله فِي ذَلِكَ لَهُ كَمَا أَذِنَ لِيُوسُفَ قَالُوا أَ إِنَّكَ لانْتَ يُوسُفُ قالَ أَنَا يُوسُفُ.","1/4/80/4","مرآة العقول: حسن · البهبودي: لم يخرجه"],[5,6,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنِ الْحَسَنِ بْنِ مُوسَى الْخَشَّابِ عَنْ عَبْدِ الله بْنِ مُوسَى عَنْ عَبْدِ الله بْنِ بُكَيْرٍ عَنْ زُرَارَةَ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِنَّ لِلْغُلامِ غَيْبَةً قَبْلَ أَنْ يَقُومَ قَالَ قُلْتُ وَلِمَ قَالَ يَخَافُ وَأَوْمَأَ بِيَدِهِ إِلَى بَطْنِهِ ثُمَّ قَالَ يَا زُرَارَةُ وَهُوَ الْمُنْتَظَرُ وَهُوَ الَّذِي يُشَكُّ فِي وِلادَتِهِ مِنْهُمْ مَنْ يَقُولُ مَاتَ أَبُوهُ بِلا خَلَفٍ وَمِنْهُمْ مَنْ يَقُولُ حَمْلٌ وَمِنْهُمْ مَنْ يَقُولُ إِنَّهُ وُلِدَ قَبْلَ مَوْتِ أَبِيهِ بِسَنَتَيْنِ وَهُوَ الْمُنْتَظَرُ غَيْرَ أَنَّ الله عَزَّ وَجَلَّ يُحِبُّ أَنْ يَمْتَحِنَ الشِّيعَةَ فَعِنْدَ ذَلِكَ يَرْتَابُ الْمُبْطِلُونَ يَا زُرَارَةُ قَالَ قُلْتُ جُعِلْتُ فِدَاكَ إِنْ أَدْرَكْتُ ذَلِكَ الزَّمَانَ أَيَّ شَيْ‏ءٍ أَعْمَلُ قَالَ يَا زُرَارَةُ إِذَا أَدْرَكْتَ هَذَا الزَّمَانَ فَادْعُ بِهَذَا الدُّعَاءِ اللهمَّ عَرِّفْنِي نَفْسَكَ فَإِنَّكَ إِنْ لَمْ تُعَرِّفْنِي نَفْسَكَ لَمْ أَعْرِفْ نَبِيَّكَ اللهمَّ عَرِّفْنِي رَسُولَكَ فَإِنَّكَ إِنْ لَمْ تُعَرِّفْنِي رَسُولَكَ لَمْ أَعْرِفْ حُجَّتَكَ اللهمَّ عَرِّفْنِي حُجَّتَكَ فَإِنَّكَ إِنْ لَمْ تُعَرِّفْنِي حُجَّتَكَ ضَلَلْتُ عَنْ دِينِي ثُمَّ قَالَ يَا زُرَارَةُ لا بُدَّ مِنْ قَتْلِ غُلامٍ بِالْمَدِينَةِ قُلْتُ جُعِلْتُ فِدَاكَ أَ لَيْسَ يَقْتُلُهُ جَيْشُ السُّفْيَانِيِّ قَالَ لا وَلَكِنْ يَقْتُلُهُ جَيْشُ آلِ بَنِي فُلانٍ يَجِي‏ءُ حَتَّى يَدْخُلَ الْمَدِينَةَ فَيَأْخُذُ الْغُلامَ فَيَقْتُلُهُ فَإِذَا قَتَلَهُ بَغْياً وَعُدْوَاناً وَظُلْماً لا يُمْهَلُونَ فَعِنْدَ ذَلِكَ تَوَقُّعُ الْفَرَجِ إِنْ شَاءَ الله.","1/4/80/5","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[6,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ إِسْحَاقَ بْنِ مُحَمَّدٍ عَنْ يَحْيَى بْنِ الْمُثَنَّى عَنْ عَبْدِ الله بْنِ بُكَيْرٍ عَنْ عُبَيْدِ بْنِ زُرَارَةَ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ يَفْقِدُ النَّاسُ إِمَامَهُمْ يَشْهَدُ الْمَوْسِمَ فَيَرَاهُمْ وَلا يَرَوْنَهُ.","1/4/80/6","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[7,6,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ عَبْدِ الله بْنِ مُحَمَّدِ بْنِ خَالِدٍ قَالَ حَدَّثَنِي مُنْذِرُ بْنُ مُحَمَّدِ بْنِ قَابُوسَ عَنْ مَنْصُورِ بْنِ السِّنْدِيِّ عَنْ أَبِي دَاوُدَ الْمُسْتَرِقِّ عَنْ ثَعْلَبَةَ بْنِ مَيْمُونٍ عَنْ مَالِكٍ الْجُهَنِيِّ عَنِ الْحَارِثِ بْنِ الْمُغِيرَةِ عَنِ الاصْبَغِ بْنِ نُبَاتَةَ قَالَ أَتَيْتُ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) فَوَجَدْتُهُ مُتَفَكِّراً يَنْكُتُ فِي الارْضِ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ مَا لِي أَرَاكَ مُتَفَكِّراً تَنْكُتُ فِي الارْضِ أَ رَغْبَةً مِنْكَ فِيهَا فَقَالَ لا وَالله مَا رَغِبْتُ فِيهَا وَلا فِي الدُّنْيَا يَوْماً قَطُّ وَلَكِنِّي فَكَّرْتُ فِي مَوْلُودٍ يَكُونُ مِنْ ظَهْرِي الْحَادِيَ عَشَرَ مِنْ وُلْدِي هُوَ الْمَهْدِيُّ الَّذِي يَمْلا الارْضَ عَدْلاً وَقِسْطاً كَمَا مُلِئَتْ جَوْراً وَظُلْماً تَكُونُ لَهُ غَيْبَةٌ وَحَيْرَةٌ يَضِلُّ فِيهَا أَقْوَامٌ وَيَهْتَدِي فِيهَا آخَرُونَ فَقُلْتُ يَا أَمِيرَ الْمُؤْمِنِينَ وَكَمْ تَكُونُ الْحَيْرَةُ وَالْغَيْبَةُ قَالَ سِتَّةَ أَيَّامٍ أَوْ سِتَّةَ أَشْهُرٍ أَوْ سِتَّ سِنِينَ فَقُلْتُ وَإِنَّ هَذَا لَكَائِنٌ فَقَالَ نَعَمْ كَمَا أَنَّهُ مَخْلُوقٌ وَأَنَّى لَكَ بِهَذَا الامْرِ يَا أَصْبَغُ أُولَئِكَ خِيَارُ هَذِهِ الامَّةِ مَعَ خِيَارِ أَبْرَارِ هَذِهِ الْعِتْرَةِ فَقُلْتُ ثُمَّ مَا يَكُونُ بَعْدَ ذَلِكَ فَقَالَ ثُمَّ يَفْعَلُ الله مَا يَشَاءُ فَإِنَّ لَهُ بَدَاءَاتٍ وَإِرَادَاتٍ وَغَايَاتٍ وَنِهَايَاتِ.","1/4/80/7","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[8,6,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ حَنَانِ بْنِ سَدِيرٍ عَنْ مَعْرُوفِ بْنِ خَرَّبُوذَ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ إِنَّمَا نَحْنُ كَنُجُومِ السَّمَاءِ كُلَّمَا غَابَ نَجْمٌ طَلَعَ نَجْمٌ حَتَّى إِذَا أَشَرْتُمْ بِأَصَابِعِكُمْ وَمِلْتُمْ بِأَعْنَاقِكُمْ غَيَّبَ الله عَنْكُمْ نَجْمَكُمْ فَاسْتَوَتْ بَنُو عَبْدِ الْمُطَّلِبِ فَلَمْ يُعْرَفْ أَيٌّ مِنْ أَيٍّ فَإِذَا طَلَعَ نَجْمُكُمْ فَاحْمَدُوا رَبَّكُمْ.","1/4/80/8","مرآة العقول: موثق حسن · البهبودي: صحيح"],[9,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ الْحَسَنِ بْنِ مُعَاوِيَةَ عَنْ عَبْدِ الله بْنِ جَبَلَةَ عَنْ عَبْدِ الله بْنِ بُكَيْرٍ عَنْ زُرَارَةَ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِنَّ لِلْقَائِمِ (عَلَيْهِ السَّلام) غَيْبَةً قَبْلَ أَنْ يَقُومَ قُلْتُ وَلِمَ قَالَ إِنَّهُ يَخَافُ وَأَوْمَأَ بِيَدِهِ إِلَى بَطْنِهِ يَعْنِي الْقَتْلَ.","1/4/80/9","مرآة العقول: ضعيف أو مجهول · البهبودي: لم يخرجه"],[10,6,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنِ ابْنِ أَبِي عُمَيْرٍ عَنْ أَبِي أَيُّوبَ الْخَزَّازِ عَنْ مُحَمَّدِ بْنِ مُسْلِمٍ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِنْ بَلَغَكُمْ عَنْ صَاحِبِ هَذَا الامْرِ غَيْبَةٌ فَلا تُنْكِرُوهَا.","1/4/80/10","مرآة العقول: حسن · البهبودي: صحيح"],[11,6,"الْحُسَيْنُ بْنُ مُحَمَّدٍ وَمُحَمَّدُ بْنُ يَحْيَى عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ الْحَسَنِ بْنِ مُعَاوِيَةَ عَنْ عَبْدِ الله بْنِ جَبَلَةَ عَنْ إِبْرَاهِيمَ بْنِ خَلَفِ بْنِ عَبَّادٍ الانْمَاطِيِّ عَنْ مُفَضَّلِ بْنِ عُمَرَ قَالَ كُنْتُ عِنْدَ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) وَعِنْدَهُ فِي الْبَيْتِ أُنَاسٌ فَظَنَنْتُ أَنَّهُ إِنَّمَا أَرَادَ بِذَلِكَ غَيْرِي فَقَالَ أَمَا وَالله لَيَغِيبَنَّ عَنْكُمْ صَاحِبُ هَذَا الامْرِ وَلَيَخْمِلَنَّ هَذَا حَتَّى يُقَالَ مَاتَ هَلَكَ فِي أَيِّ وَادٍ سَلَكَ وَلَتُكْفَؤُنَّ كَمَا تُكْفَأُ السَّفِينَةُ فِي أَمْوَاجِ الْبَحْرِ لا يَنْجُو إِلا مَنْ أَخَذَ الله مِيثَاقَهُ وَكَتَبَ الايمَانَ فِي قَلْبِهِ وَأَيَّدَهُ بِرُوحٍ مِنْهُ وَلَتُرْفَعَنَّ اثْنَتَا عَشْرَةَ رَايَةً مُشْتَبِهَةً لا يُدْرَى أَيٌّ مِنْ أَيٍّ قَالَ فَبَكَيْتُ فَقَالَ مَا يُبْكِيكَ يَا أَبَا عَبْدِ الله فَقُلْتُ جُعِلْتُ فِدَاكَ كَيْفَ لا أَبْكِي وَأَنْتَ تَقُولُ اثْنَتَا عَشْرَةَ رَايَةً مُشْتَبِهَةً لا يُدْرَى أَيٌّ مِنْ أَيٍّ قَالَ وَفِي مَجْلِسِهِ كَوَّةٌ تَدْخُلُ فِيهَا الشَّمْسُ فَقَالَ أَ بَيِّنَةٌ هَذِهِ فَقُلْتُ نَعَمْ قَالَ أَمْرُنَا أَبْيَنُ مِنْ هَذِهِ الشَّمْسِ.","1/4/80/11","مرآة العقول: ضعيف أو مجهول · البهبودي: لم يخرجه"],[12,6,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ الْقَاسِمِ بْنِ إِسْمَاعِيلَ الانْبَارِيِّ عَنْ يَحْيَى بْنِ الْمُثَنَّى عَنْ عَبْدِ الله بْنِ بُكَيْرٍ عَنْ عُبَيْدِ بْنِ زُرَارَةَ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ لِلْقَائِمِ غَيْبَتَانِ يَشْهَدُ فِي إِحْدَاهُمَا الْمَوَاسِمَ يَرَى النَّاسَ وَلا يَرَوْنَهُ.","1/4/80/12","مرآة العقول: ضعيف أو مجهول · البهبودي: لم يخرجه"],[13,6,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ وَمُحَمَّدُ بْنُ يَحْيَى وَغَيْرُهُ عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ وَعَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ جَمِيعاً عَنِ ابْنِ مَحْبُوبٍ عَنْ هِشَامِ بْنِ سَالِمٍ عَنْ أَبِي حَمْزَةَ عَنْ أَبِي إِسْحَاقَ السَّبِيعِيِّ عَنْ بَعْضِ أَصْحَابِ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) مِمَّنْ يُوثَقُ بِهِ أَنَّ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) تَكَلَّمَ بِهَذَا الْكَلامِ وَحُفِظَ عَنْهُ وَخَطَبَ بِهِ عَلَى مِنْبَرِ الْكُوفَةِ اللهمَّ إِنَّهُ لا بُدَّ لَكَ مِنْ حُجَجٍ فِي أَرْضِكَ حُجَّةٍ بَعْدَ حُجَّةٍ عَلَى خَلْقِكَ يَهْدُونَهُمْ إِلَى دِينِكَ وَيُعَلِّمُونَهُمْ عِلْمَكَ كَيْلا يَتَفَرَّقَ أَتْبَاعُ أَوْلِيَائِكَ ظَاهِرٍ غَيْرِ مُطَاعٍ أَوْ مُكْتَتَمٍ يُتَرَقَّبُ إِنْ غَابَ عَنِ النَّاسِ شَخْصُهُمْ فِي حَالِ هُدْنَتِهِمْ فَلَمْ يَغِبْ عَنْهُمْ قَدِيمُ مَبْثُوثِ عِلْمِهِمْ وَآدَابُهُمْ فِي قُلُوبِ الْمُؤْمِنِينَ مُثْبَتَةٌ فَهُمْ بِهَا عَامِلُونَ وَيَقُولُ (عَلَيْهِ السَّلام) فِي هَذِهِ الْخُطْبَةِ فِي مَوْضِعٍ آخَرَ فِيمَنْ هَذَا وَلِهَذَا يَأْرِزُ الْعِلْمُ إِذَا لَمْ يُوجَدْ لَهُ حَمَلَةٌ يَحْفَظُونَهُ وَيَرْوُونَهُ كَمَا سَمِعُوهُ مِنَ الْعُلَمَاءِ وَيَصْدُقُونَ عَلَيْهِمْ فِيهِ اللهمَّ فَإِنِّي لاعْلَمُ أَنَّ الْعِلْمَ لا يَأْرِزُ كُلُّهُ وَلا يَنْقَطِعُ مَوَادُّهُ وَإِنَّكَ لا تُخْلِي أَرْضَكَ مِنْ حُجَّةٍ لَكَ عَلَى خَلْقِكَ ظَاهِرٍ لَيْسَ بِالْمُطَاعِ أَوْ خَائِفٍ مَغْمُورٍ كَيْلا تَبْطُلَ حُجَّتُكَ وَلا يَضِلَّ أَوْلِيَاؤُكَ بَعْدَ إِذْ هَدَيْتَهُمْ بَلْ أَيْنَ هُمْ وَكَمْ هُمْ أُولَئِكَ الاقَلُّونَ عَدَداً الاعْظَمُونَ عِنْدَ الله قَدْراً.","1/4/80/13","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[14,6,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ عَنْ مُوسَى بْنِ الْقَاسِمِ بْنِ مُعَاوِيَةَ الْبَجَلِيِّ عَنْ عَلِيِّ بْنِ جَعْفَرٍ عَنْ أَخِيهِ مُوسَى بْنِ جَعْفَرٍ (عَلَيْهما السَّلام) فِي قَوْلِ الله عَزَّ وَجَلَّ قُلْ أَ رَأَيْتُمْ إِنْ أَصْبَحَ ماؤُكُمْ غَوْراً فَمَنْ يَأْتِيكُمْ بِماءٍ مَعِينٍ قَالَ إِذَا غَابَ عَنْكُمْ إِمَامُكُمْ فَمَنْ يَأْتِيكُمْ بِإِمَامٍ جَدِيدٍ.","1/4/80/14","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[15,6,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ الْحَكَمِ عَنْ أَبِي أَيُّوبَ الْخَزَّازِ عَنْ مُحَمَّدِ بْنِ مُسْلِمٍ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِنْ بَلَغَكُمْ عَنْ صَاحِبِكُمْ غَيْبَةٌ فَلا تُنْكِرُوهَا.","1/4/80/15","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[16,6,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْحَسَنِ بْنِ عَلِيٍّ الْوَشَّاءِ عَنْ عَلِيِّ بْنِ أَبِي حَمْزَةَ عَنْ أَبِي بَصِيرٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ لا بُدَّ لِصَاحِبِ هَذَا الامْرِ مِنْ غَيْبَةٍ وَلا بُدَّ لَهُ فِي غَيْبَتِهِ مِنْ عُزْلَةٍ وَنِعْمَ الْمَنْزِلُ طَيْبَةُ وَمَا بِثَلاثِينَ مِنْ وَحْشَةٍ.","1/4/80/16","مرآة العقول: ضعيف أو موثق · البهبودي: لم يخرجه"],[17,6,"وَبِهَذَا الاسْنَادِ عَنِ الْوَشَّاءِ عَنْ عَلِيِّ بْنِ الْحَسَنِ عَنْ أَبَانِ بْنِ تَغْلِبَ قَالَ قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) كَيْفَ أَنْتَ إِذَا وَقَعَتِ الْبَطْشَةُ بَيْنَ الْمَسْجِدَيْنِ فَيَأْرِزُ الْعِلْمُ كَمَا تَأْرِزُ الْحَيَّةُ فِي جُحْرِهَا وَاخْتَلَفَتِ الشِّيعَةُ وَسَمَّى بَعْضُهُمْ بَعْضاً كَذَّابِينَ وَتَفَلَ بَعْضُهُمْ فِي وُجُوهِ بَعْضٍ قُلْتُ جُعِلْتُ فِدَاكَ مَا عِنْدَ ذَلِكَ مِنْ خَيْرٍ فَقَالَ لِي الْخَيْرُ كُلُّهُ عِنْدَ ذَلِكَ ثَلاثاً.","1/4/80/17","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[18,6,"وَبِهَذَا الاسْنَادِ عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ أَبِيهِ مُحَمَّدِ بْنِ عِيسَى عَنِ ابْنِ بُكَيْرٍ عَنْ زُرَارَةَ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ إِنَّ لِلْقَائِمِ غَيْبَةً قَبْلَ أَنْ يَقُومَ إِنَّهُ يَخَافُ وَأَوْمَأَ بِيَدِهِ إِلَى بَطْنِهِ يَعْنِي الْقَتْلَ.","1/4/80/18","مرآة العقول: موثق كالصحيح · البهبودي: لم يخرجه"],[19,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنِ ابْنِ مَحْبُوبٍ عَنْ إِسْحَاقَ بْنِ عَمَّارٍ قَالَ قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) لِلْقَائِمِ غَيْبَتَانِ إِحْدَاهُمَا قَصِيرَةٌ وَالاخْرَى طَوِيلَةٌ الْغَيْبَةُ الاولَى لا يَعْلَمُ بِمَكَانِهِ فِيهَا إِلا خَاصَّةُ شِيعَتِهِ وَالاخْرَى لا يَعْلَمُ بِمَكَانِهِ فِيهَا إِلا خَاصَّةُ مَوَالِيهِ.","1/4/80/19","مرآة العقول: موثق · البهبودي: صحيح"],[20,6,"مُحَمَّدُ بْنُ يَحْيَى وَأَحْمَدُ بْنُ إِدْرِيسَ عَنِ الْحَسَنِ بْنِ عَلِيٍّ الْكُوفِيِّ عَنْ عَلِيِّ بْنِ حَسَّانَ عَنْ عَمِّهِ عَبْدِ الرَّحْمَنِ بْنِ كَثِيرٍ عَنْ مُفَضَّلِ بْنِ عُمَرَ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ لِصَاحِبِ هَذَا الامْرِ غَيْبَتَانِ إِحْدَاهُمَا يَرْجِعُ مِنْهَا إِلَى أَهْلِهِ وَالاخْرَى يُقَالُ هَلَكَ فِي أَيِّ وَادٍ سَلَكَ قُلْتُ كَيْفَ نَصْنَعُ إِذَا كَانَ كَذَلِكَ قَالَ إِذَا ادَّعَاهَا مُدَّعٍ فَاسْأَلُوهُ عَنْ أَشْيَاءَ يُجِيبُ فِيهَا مِثْلَهُ.","1/4/80/20","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[21,6,"أَحْمَدُ بْنُ إِدْرِيسَ عَنْ مُحَمَّدِ بْنِ أَحْمَدَ عَنْ جَعْفَرِ بْنِ الْقَاسِمِ عَنْ مُحَمَّدِ بْنِ الْوَلِيدِ الْخَزَّازِ عَنِ الْوَلِيدِ بْنِ عُقْبَةَ عَنِ الْحَارِثِ بْنِ زِيَادٍ عَنْ شُعَيْبٍ عَنْ أَبِي حَمْزَةَ قَالَ دَخَلْتُ عَلَى أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) فَقُلْتُ لَهُ أَنْتَ صَاحِبُ هَذَا الامْرِ فَقَالَ لا فَقُلْتُ فَوَلَدُكَ فَقَالَ لا فَقُلْتُ فَوَلَدُ وَلَدِكَ هُوَ قَالَ لا فَقُلْتُ فَوَلَدُ وَلَدِ وَلَدِكَ فَقَالَ لا قُلْتُ مَنْ هُوَ قَالَ الَّذِي يَمْلاهَا عَدْلاً كَمَا مُلِئَتْ ظُلْماً وَجَوْراً عَلَى فَتْرَةٍ مِنَ الائِمَّةِ كَمَا أَنَّ رَسُولَ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) بُعِثَ عَلَى فَتْرَةٍ مِنَ الرُّسُلِ.","1/4/80/21","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[22,6,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ مُوسَى بْنِ جَعْفَرٍ الْبَغْدَادِيِّ عَنْ وَهْبِ بْنِ شَاذَانَ عَنِ الْحَسَنِ بْنِ أَبِي الرَّبِيعِ عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ عَنْ أُمِّ هَانِئٍ قَالَتْ سَأَلْتُ أَبَا جَعْفَرٍ مُحَمَّدَ بن علي (عَلَيْهما السَّلام) عَنْ قَوْلِ الله تَعَالَى فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوارِ الْكُنَّسِ قَالَتْ فَقَالَ إِمَامٌ يَخْنِسُ سَنَةَ سِتِّينَ وَمِائَتَيْنِ ثُمَّ يَظْهَرُ كَالشِّهَابِ يَتَوَقَّدُ فِي اللَّيْلَةِ الظَّلْمَاءِ فَإِنْ أَدْرَكْتِ زَمَانَهُ قَرَّتْ عَيْنُكِ.","1/4/80/22","مرآة العقول: ضعيف أو مجهول · البهبودي: لم يخرجه"],[23,6,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ سَعْدِ بْنِ عَبْدِ الله عَنْ أَحْمَدَ بْنِ الْحَسَنِ عَنْ عُمَرَ بْنِ يَزِيدَ عَنِ الْحَسَنِ بْنِ الرَّبِيعِ الْهَمْدَانِيِّ قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ إِسْحَاقَ عَنْ أُسَيْدِ بْنِ ثَعْلَبَةَ عَنْ أُمِّ هَانِئٍ قَالَتْ لَقِيتُ أَبَا جَعْفَرٍ مُحَمَّدَ بن علي (عَلَيْهما السَّلام) فَسَأَلْتُهُ عَنْ هَذِهِ الايَةِ فَلا أُقْسِمُ بِالْخُنَّسِ الْجَوارِ الْكُنَّسِ قَالَ الْخُنَّسُ إِمَامٌ يَخْنِسُ فِي زَمَانِهِ عِنْدَ انْقِطَاعٍ مِنْ عِلْمِهِ عِنْدَ النَّاسِ سَنَةَ سِتِّينَ وَمِائَتَيْنِ ثُمَّ يَبْدُو كَالشِّهَابِ الْوَاقِدِ فِي ظُلْمَةِ اللَّيْلِ فَإِنْ أَدْرَكْتِ ذَلِكِ قَرَّتْ عَيْنُكِ.","1/4/80/23","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[24,6,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ بَعْضِ أَصْحَابِنَا عَنْ أَيُّوبَ بْنِ نُوحٍ عَنْ أَبِي الْحَسَنِ الثَّالِثِ (عَلَيْهِ السَّلام) قَالَ إِذَا رُفِعَ عِلْمُكُمْ مِنْ بَيْنِ أَظْهُرِكُمْ فَتَوَقَّعُوا الْفَرَجَ مِنْ تَحْتِ أَقْدَامِكُمْ.","1/4/80/24","مرآة العقول: مرسل · البهبودي: لم يخرجه"],[25,6,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ سَعْدِ بْنِ عَبْدِ الله عَنْ أَيُّوبَ بْنِ نُوحٍ قَالَ قُلْتُ لابِي الْحَسَنِ الرِّضَا (عَلَيْهِ السَّلام) إِنِّي أَرْجُو أَنْ تَكُونَ صَاحِبَ هَذَا الامْرِ وَأَنْ يَسُوقَهُ الله إِلَيْكَ بِغَيْرِ سَيْفٍ فَقَدْ بُويِعَ لَكَ وَضُرِبَتِ الدَّرَاهِمُ بِاسْمِكَ فَقَالَ مَا مِنَّا أَحَدٌ اخْتَلَفَتْ إِلَيْهِ الْكُتُبُ وَأُشِيرَ إِلَيْهِ بِالاصَابِعِ وَسُئِلَ عَنِ الْمَسَائِلِ وَحُمِلَتْ إِلَيْهِ الامْوَالُ إِلا اغْتِيلَ أَوْ مَاتَ عَلَى فِرَاشِهِ حَتَّى يَبْعَثَ الله لِهَذَا الامْرِ غُلاماً مِنَّا خَفِيَّ الْوِلادَةِ وَالْمَنْشَإِ غَيْرَ خَفِيٍّ فِي نَسَبِهِ.","1/4/80/25","مرآة العقول: مرسل كالصحيح · البهبودي: صحيح"],[26,6,"الْحُسَيْنُ بْنُ مُحَمَّدٍ وَغَيْرُهُ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ الْعَبَّاسِ بْنِ عَامِرٍ عَنْ مُوسَى بْنِ هِلالٍ الْكِنْدِيِّ عَنْ عَبْدِ الله بْنِ عَطَاءٍ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ قُلْتُ لَهُ إِنَّ شِيعَتَكَ بِالْعِرَاقِ كَثِيرَةٌ وَالله مَا فِي أَهْلِ بَيْتِكَ مِثْلُكَ فَكَيْفَ لا تَخْرُجُ قَالَ فَقَالَ يَا عَبْدَ الله بْنَ عَطَاءٍ قَدْ أَخَذْتَ تَفْرُشُ أُذُنَيْكَ لِلنَّوْكَى إِي وَالله مَا أَنَا بِصَاحِبِكُمْ قَالَ قُلْتُ لَهُ فَمَنْ صَاحِبُنَا قَالَ انْظُرُوا مَنْ عَمِيَ عَلَى النَّاسِ وِلادَتُهُ فَذَاكَ صَاحِبُكُمْ إِنَّهُ لَيْسَ مِنَّا أَحَدٌ يُشَارُ إِلَيْهِ بِالاصْبَعِ وَيُمْضَغُ بِالالْسُنِ إِلا مَاتَ غَيْظاً أَوْ رَغِمَ أَنْفُهُ.","1/4/80/26","مرآة العقول: ضعيف أو مجهول · البهبودي: لم يخرجه"],[27,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْحُسَيْنِ بْنِ سَعِيدٍ عَنِ ابْنِ أَبِي عُمَيْرٍ عَنْ هِشَامِ بْنِ سَالِمٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ يَقُومُ الْقَائِمُ وَلَيْسَ لاحَدٍ فِي عُنُقِهِ عَهْدٌ وَلا عَقْدٌ وَلا بَيْعَةٌ.","1/4/80/27","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[28,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ فَضَّالٍ عَنِ الْحَسَنِ بْنِ عَلِيٍّ الْعَطَّارِ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ مَنْصُورٍ عَمَّنْ ذَكَرَهُ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ قُلْتُ إِذَا أَصْبَحْتُ وَأَمْسَيْتُ لا أَرَى إِمَاماً أَئْتَمُّ بِهِ مَا أَصْنَعُ قَالَ فَأَحِبَّ مَنْ كُنْتَ تُحِبُّ وَأَبْغِضْ مَنْ كُنْتَ تُبْغِضُ حَتَّى يُظْهِرَهُ الله عَزَّ وَجَلَّ.","1/4/80/28","مرآة العقول: مرسل · البهبودي: لم يخرجه"],[29,6,"الْحُسَيْنُ بْنُ أَحْمَدَ عَنْ أَحْمَدَ بْنِ هِلالٍ قَالَ حَدَّثَنَا عُثْمَانُ بْنُ عِيسَى عَنْ خَالِدِ بْنِ نَجِيحٍ عَنْ زُرَارَةَ بْنِ أَعْيَنَ قَالَ قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) لا بُدَّ لِلْغُلامِ مِنْ غَيْبَةٍ قُلْتُ وَلِمَ قَالَ يَخَافُ وَأَوْمَأَ بِيَدِهِ إِلَى بَطْنِهِ وَهُوَ الْمُنْتَظَرُ وَهُوَ الَّذِي يَشُكُّ النَّاسُ فِي وِلادَتِهِ فَمِنْهُمْ مَنْ يَقُولُ حَمْلٌ وَمِنْهُمْ مَنْ يَقُولُ مَاتَ أَبُوهُ وَلَمْ يُخَلِّفْ وَمِنْهُمْ مَنْ يَقُولُ وُلِدَ قَبْلَ مَوْتِ أَبِيهِ بِسَنَتَيْنِ قَالَ زُرَارَةُ فَقُلْتُ وَمَا تَأْمُرُنِي لَوْ أَدْرَكْتُ ذَلِكَ الزَّمَانَ قَالَ ادْعُ الله بِهَذَا الدُّعَاءِ اللهمَّ عَرِّفْنِي نَفْسَكَ فَإِنَّكَ إِنْ لَمْ تُعَرِّفْنِي نَفْسَكَ لَمْ أَعْرِفْكَ اللهمَّ عَرِّفْنِي نَبِيَّكَ فَإِنَّكَ إِنْ لَمْ تُعَرِّفْنِي نَبِيَّكَ لَمْ أَعْرِفْهُ قَطُّ اللهمَّ عَرِّفْنِي حُجَّتَكَ فَإِنَّكَ إِنْ لَمْ تُعَرِّفْنِي حُجَّتَكَ ضَلَلْتُ عَنْ دِينِي قَالَ أَحْمَدُ بْنُ الْهِلالِ سَمِعْتُ هَذَا الْحَدِيثَ مُنْذُ سِتٍّ وَخَمْسِينَ سَنَةً.","1/4/80/29","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[30,6,"أَبُو عَلِيٍّ الاشْعَرِيُّ عَنْ مُحَمَّدِ بْنِ حَسَّانَ عَنْ مُحَمَّدِ بْنِ عَلِيٍّ عَنْ عَبْدِ الله بْنِ الْقَاسِمِ عَنِ الْمُفَضَّلِ بْنِ عُمَرَ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) فِي قَوْلِ الله عَزَّ وَجَلَّ فَإِذا نُقِرَ فِي النَّاقُورِ قَالَ إِنَّ مِنَّا إِمَاماً مُظَفَّراً مُسْتَتِراً فَإِذَا أَرَادَ الله عَزَّ ذِكْرُهُ إِظْهَارَ أَمْرِهِ نَكَتَ فِي قَلْبِهِ نُكْتَةً فَظَهَرَ فَقَامَ بِأَمْرِ الله تَبَارَكَ وَتَعَالَى.","1/4/80/30","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[31,6,"مُحَمَّدُ بْنُ يَحْيَى عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنْ أَحْمَدَ بْنِ الْحُسَيْنِ عَنْ مُحَمَّدِ بْنِ عَبْدِ الله عَنْ مُحَمَّدِ بْنِ الْفَرَجِ قَالَ كَتَبَ إِلَيَّ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) إِذَا غَضِبَ الله تَبَارَكَ وَتَعَالَى عَلَى خَلْقِهِ نَحَّانَا عَنْ جِوَارِهِمْ.","1/4/80/31","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[1,7,"عَلِيُّ بْنُ إِبْرَاهِيمَ بْنِ هَاشِمٍ عَنْ أَبِيهِ عَنِ ابْنِ مَحْبُوبٍ عَنْ سَلامِ بْنِ عَبْدِ الله وَمُحَمَّدُ بْنُ الْحَسَنِ وَعَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ وَأَبُو عَلِيٍّ الاشْعَرِيُّ عَنْ مُحَمَّدِ بْنِ حَسَّانَ جَمِيعاً عَنْ مُحَمَّدِ بْنِ عَلِيٍّ عَنْ عَلِيِّ بْنِ أَسْبَاطٍ عَنْ سَلامِ بْنِ عَبْدِ الله الْهَاشِمِيِّ قَالَ مُحَمَّدُ بْنُ عَلِيٍّ وَقَدْ سَمِعْتُهُ مِنْهُ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ بَعَثَ طَلْحَةُ وَالزُّبَيْرُ رَجُلاً مِنْ عَبْدِ الْقَيْسِ يُقَالُ لَهُ خِدَاشٌ إِلَى أَمِيرِ الْمُؤْمِنِينَ (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَقَالا لَهُ إِنَّا نَبْعَثُكَ إِلَى رَجُلٍ طَالَ مَا كُنَّا نَعْرِفُهُ وَأَهْلَ بَيْتِهِ بِالسِّحْرِ وَالْكِهَانَةِ وَأَنْتَ أَوْثَقُ مَنْ بِحَضْرَتِنَا مِنْ أَنْفُسِنَا مِنْ أَنْ تَمْتَنِعَ مِنْ ذَلِكَ وَأَنْ تُحَاجَّهُ لَنَا حَتَّى تَقِفَهُ عَلَى أَمْرٍ مَعْلُومٍ وَاعْلَمْ أَنَّهُ أَعْظَمُ النَّاسِ دَعْوًى فَلا يَكْسِرَنَّكَ ذَلِكَ عَنْهُ وَمِنَ الابْوَابِ الَّتِي يَخْدَعُ النَّاسَ بِهَا الطَّعَامُ وَالشَّرَابُ وَالْعَسَلُ وَالدُّهْنُ وَأَنْ يُخَالِيَ الرَّجُلَ فَلا تَأْكُلْ لَهُ طَعَاماً وَلا تَشْرَبْ لَهُ شَرَاباً وَلا تَمَسَّ لَهُ عَسَلاً وَلا دُهْناً وَلا تَخْلُ مَعَهُ وَاحْذَرْ هَذَا كُلَّهُ مِنْهُ وَانْطَلِقْ عَلَى بَرَكَةِ الله فَإِذَا رَأَيْتَهُ فَاقْرَأْ آيَةَ السُّخْرَةِ وَتَعَوَّذْ بِالله مِنْ كَيْدِهِ وَكَيْدِ الشَّيْطَانِ فَإِذَا جَلَسْتَ إِلَيْهِ فَلا تُمَكِّنْهُ مِنْ بَصَرِكَ كُلِّهِ وَلا تَسْتَأْنِسْ بِهِ ثُمَّ قُلْ لَهُ إِنَّ أَخَوَيْكَ فِي الدِّينِ وَابْنَيْ عَمِّكَ فِي الْقَرَابَةِ يُنَاشِدَانِكَ الْقَطِيعَةَ وَيَقُولانِ لَكَ أَ مَا تَعْلَمُ أَنَّا تَرَكْنَا النَّاسَ لَكَ وَخَالَفْنَا عَشَائِرَنَا فِيكَ مُنْذُ قَبَضَ الله عَزَّ وَجَلَّ مُحَمَّداً (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَلَمَّا نِلْتَ أَدْنَى مَنَالٍ ضَيَّعْتَ حُرْمَتَنَا وَقَطَعْتَ رَجَاءَنَا ثُمَّ قَدْ رَأَيْتَ أَفْعَالَنَا فِيكَ وَقُدْرَتَنَا عَلَى النَّأْيِ عَنْكَ وَسَعَةِ الْبِلادِ دُونَكَ وَأَنَّ مَنْ كَانَ يَصْرِفُكَ عَنَّا وَعَنْ صِلَتِنَا كَانَ أَقَلَّ لَكَ نَفْعاً وَأَضْعَفَ عَنْكَ دَفْعاً مِنَّا وَقَدْ وَضَحَ الصُّبْحُ لِذِي عَيْنَيْنِ وَقَدْ بَلَغَنَا عَنْكَ انْتِهَاكٌ لَنَا وَدُعَاءٌ عَلَيْنَا فَمَا الَّذِي يَحْمِلُكَ عَلَى ذَلِكَ فَقَدْ كُنَّا نَرَى أَنَّكَ أَشْجَعُ فُرْسَانِ الْعَرَبِ أَ تَتَّخِذُ اللَّعْنَ لَنَا دِيناً وَتَرَى أَنَّ ذَلِكَ يَكْسِرُنَا عَنْكَ فَلَمَّا أَتَى خِدَاشٌ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) صَنَعَ مَا أَمَرَاهُ فَلَمَّا نَظَرَ إِلَيْهِ علي (عَلَيْهِ السَّلام) وَهُوَ يُنَاجِي نَفْسَهُ ضَحِكَ وَقَالَ هَاهُنَا يَا أَخَا عَبْدِ قَيْسٍ وَأَشَارَ لَهُ إِلَى مَجْلِسٍ قَرِيبٍ مِنْهُ فَقَالَ مَا أَوْسَعَ الْمَكَانَ أُرِيدُ أَنْ أُؤَدِّيَ إِلَيْكَ رِسَالَةً قَالَ بَلْ تَطْعَمُ وَتَشْرَبُ وَتَحُلُّ ثِيَابَكَ وَتَدَّهِنُ ثُمَّ تُؤَدِّي رِسَالَتَكَ قُمْ يَا قَنْبَرُ فَأَنْزِلْهُ قَالَ مَا بِي إِلَى شَيْ‏ءٍ مِمَّا ذَكَرْتَ حَاجَةٌ قَالَ فَأَخْلُو بِكَ قَالَ كُلُّ سِرٍّ لِي عَلانِيَةٌ قَالَ فَأَنْشُدُكَ بِالله الَّذِي هُوَ أَقْرَبُ إِلَيْكَ مِنْ نَفْسِكَ الْحَائِلِ بَيْنَكَ وَبَيْنَ قَلْبِكَ الَّذِي يَعْلَمُ خَائِنَةَ الاعْيُنِ وَمَا تُخْفِي الصُّدُورُ أَ تَقَدَّمَ إِلَيْكَ الزُّبَيْرُ بِمَا عَرَضْتُ عَلَيْكَ قَالَ اللهمَّ نَعَمْ قَالَ لَوْ كَتَمْتَ بَعْدَ مَا سَأَلْتُكَ مَا ارْتَدَّ إِلَيْكَ طَرْفُكَ فَأَنْشُدُكَ الله هَلْ عَلَّمَكَ كَلاماً تَقُولُهُ إِذَا أَتَيْتَنِي قَالَ اللهمَّ نَعَمْ قَالَ علي (عَلَيْهِ السَّلام) آيَةَ السُّخْرَةِ قَالَ نَعَمْ قَالَ فَاقْرَأْهَا فَقَرَأَهَا وَجَعَلَ علي (عَلَيْهِ السَّلام) يُكَرِّرُهَا وَيُرَدِّدُهَا وَيَفْتَحُ عَلَيْهِ إِذَا أَخْطَأَ حَتَّى إِذَا قَرَأَهَا سَبْعِينَ مَرَّةً قَالَ الرَّجُلُ مَا يَرَى أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) أَمْرَهُ بِتَرَدُّدِهَا سَبْعِينَ مَرَّةً ثُمَّ قَالَ لَهُ أَ تَجِدُ قَلْبَكَ اطْمَأَنَّ قَالَ إِي وَالَّذِي نَفْسِي بِيَدِهِ قَالَ فَمَا قَالا لَكَ فَأَخْبَرَهُ فَقَالَ قُلْ لَهُمَا كَفَى بِمَنْطِقِكُمَا حُجَّةً عَلَيْكُمَا وَلَكِنَّ الله لا يَهْدِي الْقَوْمَ الظَّالِمِينَ زَعَمْتُمَا أَنَّكُمَا أَخَوَايَ فِي الدِّينِ وَابْنَا عَمِّي فِي النَّسَبِ فَأَمَّا النَّسَبُ فَلا أُنْكِرُهُ وَإِنْ كَانَ النَّسَبُ مَقْطُوعاً إِلا مَا وَصَلَهُ الله بِالاسْلامِ وَأَمَّا قَوْلُكُمَا إِنَّكُمَا أَخَوَايَ فِي الدِّينِ فَإِنْ كُنْتُمَا صَادِقَيْنِ فَقَدْ فَارَقْتُمَا كِتَابَ الله عَزَّ وَجَلَّ وَعَصَيْتُمَا أَمْرَهُ بِأَفْعَالِكُمَا فِي أَخِيكُمَا فِي الدِّينِ وَإِلا فَقَدْ كَذَبْتُمَا وَافْتَرَيْتُمَا بِادِّعَائِكُمَا أَنَّكُمَا أَخَوَايَ فِي الدِّينِ وَأَمَّا مُفَارَقَتُكُمَا النَّاسَ مُنْذُ قَبَضَ الله مُحَمَّداً (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَإِنْ كُنْتُمَا فَارَقْتُمَاهُمْ بِحَقٍّ فَقَدْ نَقَضْتُمَا ذَلِكَ الْحَقَّ بِفِرَاقِكُمَا إِيَّايَ أَخِيراً وَإِنْ فَارَقْتُمَاهُمْ بِبَاطِلٍ فَقَدْ وَقَعَ إِثْمُ ذَلِكَ الْبَاطِلِ عَلَيْكُمَا مَعَ الْحَدَثِ الَّذِي أَحْدَثْتُمَا مَعَ أَنَّ صَفْقَتَكُمَا بِمُفَارَقَتِكُمَا النَّاسَ لَمْ تَكُنْ. إِلا لِطَمَعِ الدُّنْيَا زَعَمْتُمَا وَذَلِكَ قَوْلُكُمَا فَقَطَعْتَ رَجَاءَنَا لا تَعِيبَانِ بِحَمْدِ الله مِنْ دِينِي شَيْئاً وَأَمَّا الَّذِي صَرَفَنِي عَنْ صِلَتِكُمَا فَالَّذِي صَرَفَكُمَا عَنِ الْحَقِّ وَحَمَلَكُمَا عَلَى خَلْعِهِ مِنْ رِقَابِكُمَا كَمَا يَخْلَعُ الْحَرُونُ لِجَامَهُ وَهُوَ الله رَبِّي لا أُشْرِكُ بِهِ شَيْئاً فَلا تَقُولا أَقَلَّ نَفْعاً وَأَضْعَفَ دَفْعاً فَتَسْتَحِقَّا اسْمَ الشِّرْكِ مَعَ النِّفَاقِ وَأَمَّا قَوْلُكُمَا إِنِّي أَشْجَعُ فُرْسَانِ الْعَرَبِ وَهَرْبُكُمَا مِنْ لَعْنِي وَدُعَائِي فَإِنَّ لِكُلِّ مَوْقِفٍ عَمَلاً إِذَا اخْتَلَفَتِ الاسِنَّةُ وَمَاجَتْ لُبُودُ الْخَيْلِ وَمَلا سَحَرَاكُمَا أَجْوَافَكُمَا فَثَمَّ يَكْفِينِيَ الله بِكَمَالِ الْقَلْبِ وَأَمَّا إِذَا أَبَيْتُمَا بِأَنِّي أَدْعُو الله فَلا تَجْزَعَا مِنْ أَنْ يَدْعُوَ عَلَيْكُمَا رَجُلٌ سَاحِرٌ مِنْ قَوْمٍ سَحَرَةٍ زَعَمْتُمَا اللهمَّ أَقْعِصِ الزُّبَيْرَ بِشَرِّ قِتْلَةٍ وَاسْفِكْ دَمَهُ عَلَى ضَلالَةٍ وَعَرِّفْ طَلْحَةَ الْمَذَلَّةَ وَادَّخِرْ لَهُمَا فِي الاخِرَةِ شَرّاً مِنْ ذَلِكَ إِنْ كَانَا ظَلَمَانِي وَافْتَرَيَا عَلَيَّ وَكَتَمَا شَهَادَتَهُمَا وَعَصَيَاكَ وَعَصَيَا رَسُولَكَ فِيَّ قُلْ آمِينَ قَالَ خِدَاشٌ آمِينَ ثُمَّ قَالَ خِدَاشٌ لِنَفْسِهِ وَالله مَا رَأَيْتُ لِحْيَةً قَطُّ أَبْيَنَ خَطَأً مِنْكَ حَامِلَ حُجَّةٍ يَنْقُضُ بَعْضُهَا بَعْضاً لَمْ يَجْعَلِ الله لَهَا مِسَاكاً أَنَا أَبْرَأُ إِلَى الله مِنْهُمَا قَالَ علي (عَلَيْهِ السَّلام) ارْجِعْ إِلَيْهِمَا وَأَعْلِمْهُمَا مَا قُلْتُ قَالَ لا وَالله حَتَّى تَسْأَلَ الله أَنْ يَرُدَّنِي إِلَيْكَ عَاجِلاً وَأَنْ يُوَفِّقَنِي لِرِضَاهُ فِيكَ فَفَعَلَ فَلَمْ يَلْبَثْ أَنِ انْصَرَفَ وَقُتِلَ مَعَهُ يَوْمَ الْجَمَلِ رَحِمَهُ الله.","1/4/81/1","مرآة العقول: سنده الول مجهول والثاني ضعيف · البهبودي: لم يخرجه"],[2,7,"عَلِيُّ بْنُ مُحَمَّدٍ وَمُحَمَّدُ بْنُ الْحَسَنِ عَنْ سَهْلِ بْنِ زِيَادٍ وَأَبُو عَلِيٍّ الاشْعَرِيُّ عَنْ مُحَمَّدِ بْنِ حَسَّانَ جَمِيعاً عَنْ مُحَمَّدِ بْنِ عَلِيٍّ عَنْ نَصْرِ بْنِ مُزَاحِمٍ عَنْ عَمْرِو بْنِ سَعِيدٍ عَنْ جَرَّاحِ بْنِ عَبْدِ الله عَنْ رَافِعِ بْنِ سَلَمَةَ قَالَ كُنْتُ مَعَ عَلِيِّ بْنِ أَبِي طَالِبٍ صَلَوَاتُ الله عَلَيْهِ يَوْمَ النَّهْرَوَانِ فَبَيْنَا علي (عَلَيْهِ السَّلام) جَالِسٌ إِذْ جَاءَ فَارِسٌ فَقَالَ السَّلامُ عَلَيْكَ يَا عَلِيُّ فَقَالَ لَهُ علي (عَلَيْهِ السَّلام) وَعَلَيْكَ السَّلامُ مَا لَكَ ثَكِلَتْكَ أُمُّكَ لَمْ تُسَلِّمْ عَلَيَّ بِإِمْرَةِ الْمُؤْمِنِينَ قَالَ بَلَى سَأُخْبِرُكَ عَنْ ذَلِكَ كُنْتُ إِذْ كُنْتَ عَلَى الْحَقِّ بِصِفِّينَ فَلَمَّا حَكَّمْتَ الْحَكَمَيْنِ بَرِئْتُ مِنْكَ وَسَمَّيْتُكَ مُشْرِكاً فَأَصْبَحْتُ لا أَدْرِي إِلَى أَيْنَ أَصْرِفُ وَلايَتِي وَالله لانْ أَعْرِفَ هُدَاكَ مِنْ ضَلالَتِكَ أَحَبُّ إِلَيَّ مِنَ الدُّنْيَا وَمَا فِيهَا فَقَالَ لَهُ علي (عَلَيْهِ السَّلام) ثَكِلَتْكَ أُمُّكَ قِفْ مِنِّي قَرِيباً أُرِيكَ عَلامَاتِ الْهُدَى مِنْ عَلامَاتِ الضَّلالَةِ فَوَقَفَ الرَّجُلُ قَرِيباً مِنْهُ فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ أَقْبَلَ فَارِسٌ يَرْكُضُ حَتَّى أَتَى عَلِيّاً (عَلَيْهِ السَّلام) فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ أَبْشِرْ بِالْفَتْحِ أَقَرَّ الله عَيْنَكَ قَدْ وَالله قُتِلَ الْقَوْمُ أَجْمَعُونَ فَقَالَ لَهُ مِنْ دُونِ النَّهَرِ أَوْ مِنْ خَلْفِهِ قَالَ بَلْ مِنْ دُونِهِ فَقَالَ كَذَبْتَ وَالَّذِي فَلَقَ الْحَبَّةَ وَبَرَأَ النَّسَمَةَ لا يَعْبُرُونَ أَبَداً حَتَّى يُقْتَلُوا فَقَالَ الرَّجُلُ فَازْدَدْتُ فِيهِ بَصِيرَةً فَجَاءَ آخَرُ يَرْكُضُ عَلَى فَرَسٍ لَهُ فَقَالَ لَهُ مِثْلَ ذَلِكَ فَرَدَّ عَلَيْهِ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) مِثْلَ الَّذِي رَدَّ عَلَى صَاحِبِهِ قَالَ الرَّجُلُ الشَّاكُّ وَهَمَمْتُ أَنْ أَحْمِلَ عَلَى علي (عَلَيْهِ السَّلام) فَأَفْلَقَ هَامَتَهُ بِالسَّيْفِ ثُمَّ جَاءَ فَارِسَانِ يَرْكُضَانِ قَدْ أَعْرَقَا فَرَسَيْهِمَا فَقَالا أَقَرَّ الله عَيْنَكَ يَا أَمِيرَ الْمُؤْمِنِينَ أَبْشِرْ بِالْفَتْحِ قَدْ وَالله قُتِلَ الْقَوْمُ أَجْمَعُونَ فَقَالَ علي (عَلَيْهِ السَّلام) أَ مِنْ خَلْفِ النَّهَرِ أَوْ مِنْ دُونِهِ قَالا لا بَلْ مِنْ خَلْفِهِ إِنَّهُمْ لَمَّا اقْتَحَمُوا خَيْلَهُمُ النَّهْرَوَانَ وَضَرَبَ الْمَاءُ لَبَّاتِ خُيُولِهِمْ رَجَعُوا فَأُصِيبُوا فَقَالَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) صَدَقْتُمَا فَنَزَلَ الرَّجُلُ عَنْ فَرَسِهِ فَأَخَذَ بِيَدِ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) وَبِرِجْلِهِ فَقَبَّلَهُمَا فَقَالَ علي (عَلَيْهِ السَّلام) هَذِهِ لَكَ آيَةٌ.","1/4/81/2","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[3,7,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ أَبِي عَلِيٍّ مُحَمَّدِ بْنِ إِسْمَاعِيلَ بْنِ مُوسَى بْنِ جَعْفَرٍ عَنْ أَحْمَدَ بْنِ الْقَاسِمِ الْعِجْلِيِّ عَنْ أَحْمَدَ بْنِ يَحْيَى الْمَعْرُوفِ بِكُرْدٍ عَنْ مُحَمَّدِ بْنِ خُدَاهِيِّ عَنْ عَبْدِ الله بْنِ أَيُّوبَ عَنْ عَبْدِ الله بْنِ هَاشِمٍ عَنْ عَبْدِ الْكَرِيمِ بْنِ عَمْرٍو الْخَثْعَمِيِّ عَنْ حَبَابَةَ الْوَالِبِيَّةِ قَالَتْ رَأَيْتُ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) فِي شُرْطَةِ الْخَمِيسِ وَمَعَهُ دِرَّةٌ لَهَا سَبَابَتَانِ يَضْرِبُ بِهَا بَيَّاعِي الْجِرِّيِّ وَالْمَارْمَاهِي وَالزِّمَّارِ وَيَقُولُ لَهُمْ يَا بَيَّاعِي مُسُوخِ بَنِي إِسْرَائِيلَ وَجُنْدِ بَنِي مَرْوَانَ فَقَامَ إِلَيْهِ فُرَاتُ بْنُ أَحْنَفَ فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ وَمَا جُنْدُ بَنِي مَرْوَانَ قَالَ فَقَالَ لَهُ أَقْوَامٌ حَلَقُوا اللِّحَى وَفَتَلُوا الشَّوَارِبَ فَمُسِخُوا فَلَمْ أَرَ نَاطِقاً أَحْسَنَ نُطْقاً مِنْهُ ثُمَّ اتَّبَعْتُهُ فَلَمْ أَزَلْ أَقْفُو أَثَرَهُ حَتَّى قَعَدَ فِي رَحَبَةِ الْمَسْجِدِ فَقُلْتُ لَهُ يَا أَمِيرَ الْمُؤْمِنِينَ مَا دَلالَةُ الامَامَةِ يَرْحَمُكَ الله قَالَتْ فَقَالَ ائْتِينِي بِتِلْكِ الْحَصَاةِ وَأَشَارَ بِيَدِهِ إِلَى حَصَاةٍ فَأَتَيْتُهُ بِهَا فَطَبَعَ لِي فِيهَا بِخَاتَمِهِ ثُمَّ قَالَ لِي يَا حَبَابَةُ إِذَا ادَّعَى مُدَّعٍ الامَامَةَ فَقَدَرَ أَنْ يَطْبَعَ كَمَا رَأَيْتِ فَاعْلَمِي أَنَّهُ إِمَامٌ مُفْتَرَضُ الطَّاعَةِ وَالامَامُ لا يَعْزُبُ عَنْهُ شَيْ‏ءٌ يُرِيدُهُ قَالَتْ ثُمَّ انْصَرَفْتُ حَتَّى قُبِضَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) فَجِئْتُ إِلَى الْحَسَنِ (عَلَيْهِ السَّلام) وَهُوَ فِي مَجْلِسِ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) وَالنَّاسُ يَسْأَلُونَهُ فَقَالَ يَا حَبَابَةُ الْوَالِبِيَّةُ فَقُلْتُ نَعَمْ يَا مَوْلايَ فَقَالَ هَاتِي مَا مَعَكِ قَالَ فَأَعْطَيْتُهُ فَطَبَعَ فِيهَا كَمَا طَبَعَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) قَالَتْ ثُمَّ أَتَيْتُ الْحُسَيْنَ (عَلَيْهِ السَّلام) وَهُوَ فِي مَسْجِدِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَقَرَّبَ وَرَحَّبَ ثُمَّ قَالَ لِي إِنَّ فِي الدَّلالَةِ دَلِيلاً عَلَى مَا تُرِيدِينَ أَ فَتُرِيدِينَ دَلالَةَ الامَامَةِ فَقُلْتُ نَعَمْ يَا سَيِّدِي فَقَالَ هَاتِي مَا مَعَكِ فَنَاوَلْتُهُ الْحَصَاةَ فَطَبَعَ لِي فِيهَا قَالَتْ ثُمَّ أَتَيْتُ عَلِيَّ بن الحسين (عَلَيْهما السَّلام) وَقَدْ بَلَغَ بِيَ الْكِبَرُ إِلَى أَنْ أُرْعِشْتُ وَأَنَا أَعُدُّ يَوْمَئِذٍ مِائَةً وَثَلاثَ عَشْرَةَ سَنَةً فَرَأَيْتُهُ رَاكِعاً وَسَاجِداً وَمَشْغُولاً بِالْعِبَادَةِ فَيَئِسْتُ مِنَ الدَّلالَةِ فَأَوْمَأَ إِلَيَّ بِالسَّبَّابَةِ فَعَادَ إِلَيَّ شَبَابِي قَالَتْ فَقُلْتُ يَا سَيِّدِي كَمْ مَضَى مِنَ الدُّنْيَا وَكَمْ بَقِيَ فَقَالَ أَمَّا مَا مَضَى فَنَعَمْ وَأَمَّا مَا بَقِيَ فَلا قَالَتْ ثُمَّ قَالَ لِي هَاتِي مَا مَعَكِ فَأَعْطَيْتُهُ الْحَصَاةَ فَطَبَعَ لِي فِيهَا ثُمَّ أَتَيْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) فَطَبَعَ لِي فِيهَا ثُمَّ أَتَيْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) فَطَبَعَ لِي فِيهَا ثُمَّ أَتَيْتُ أَبَا الْحَسَنِ مُوسَى (عَلَيْهِ السَّلام) فَطَبَعَ لِي فِيهَا ثُمَّ أَتَيْتُ الرِّضَا (عَلَيْهِ السَّلام) فَطَبَعَ لِي فِيهَا وَعَاشَتْ حَبَابَةُ بَعْدَ ذَلِكَ تِسْعَةَ أَشْهُرٍ عَلَى مَا ذَكَرَ مُحَمَّدُ بْنُ هِشَامٍ.","1/4/81/3","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[4,7,"مُحَمَّدُ بْنُ أَبِي عَبْدِ الله وَعَلِيُّ بْنُ مُحَمَّدٍ عَنْ إِسْحَاقَ بْنِ مُحَمَّدٍ النَّخَعِيِّ عَنْ أَبِي هَاشِمٍ دَاوُدَ بْنِ الْقَاسِمِ الْجَعْفَرِيِّ قَالَ كُنْتُ عِنْدَ أَبِي مُحَمَّدٍ (عَلَيْهِ السَّلام) فَاسْتُؤْذِنَ لِرَجُلٍ مِنْ أَهْلِ الْيَمَنِ عَلَيْهِ فَدَخَلَ رَجُلٌ عَبْلٌ طَوِيلٌ جَسِيمٌ فَسَلَّمَ عَلَيْهِ بِالْوَلايَةِ فَرَدَّ عَلَيْهِ بِالْقَبُولِ وَأَمَرَهُ بِالْجُلُوسِ فَجَلَسَ مُلاصِقاً لِي فَقُلْتُ فِي نَفْسِي لَيْتَ شِعْرِي مَنْ هَذَا فَقَالَ أَبُو مُحَمَّدٍ (عَلَيْهِ السَّلام) هَذَا مِنْ وُلْدِ الاعْرَابِيَّةِ صَاحِبَةِ الْحَصَاةِ الَّتِي طَبَعَ آبَائِي (عَلَيْهم السَّلام) فِيهَا بِخَوَاتِيمِهِمْ فَانْطَبَعَتْ وَقَدْ جَاءَ بِهَا مَعَهُ يُرِيدُ أَنْ أَطْبَعَ فِيهَا ثُمَّ قَالَ هَاتِهَا فَأَخْرَجَ حَصَاةً وَفِي جَانِبٍ مِنْهَا مَوْضِعٌ أَمْلَسُ فَأَخَذَهَا أَبُو مُحَمَّدٍ (عَلَيْهِ السَّلام) ثُمَّ أَخْرَجَ خَاتَمَهُ فَطَبَعَ فِيهَا فَانْطَبَعَ فَكَأَنِّي أَرَى نَقْشَ خَاتَمِهِ السَّاعَةَ الْحَسَنُ بْنُ عَلِيٍّ فَقُلْتُ لِلْيَمَانِيِّ رَأَيْتَهُ قَبْلَ هَذَا قَطُّ قَالَ لا وَالله وَإِنِّي لَمُنْذُ دَهْرٍ حَرِيصٌ عَلَى رُؤْيَتِهِ حَتَّى كَانَ السَّاعَةَ أَتَانِي شَابٌّ لَسْتُ أَرَاهُ فَقَالَ لِي قُمْ فَادْخُلْ فَدَخَلْتُ ثُمَّ نَهَضَ الْيَمَانِيُّ وَهُوَ يَقُولُ رَحْمَةُ الله وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ ذُرِّيَّةً بَعْضُهَا مِنْ بَعْضٍ أَشْهَدُ بِالله إِنَّ حَقَّكَ لَوَاجِبٌ كَوُجُوبِ حَقِّ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) وَالائِمَّةِ مِنْ بَعْدِهِ صَلَوَاتُ الله عَلَيْهِمْ أَجْمَعِينَ ثُمَّ مَضَى فَلَمْ أَرَهُ بَعْدَ ذَلِكَ قَالَ إِسْحَاقُ قَالَ أَبُو هَاشِمٍ الْجَعْفَرِيُّ وَسَأَلْتُهُ عَنِ اسْمِهِ فَقَالَ اسْمِي مِهْجَعُ بْنُ الصَّلْتِ بْنِ عُقْبَةَ بْنِ سِمْعَانَ بْنِ غَانِمِ ابْنِ أُمِّ غَانِمٍ وَهِيَ الاعْرَابِيَّةُ الْيَمَانِيَّةُ صَاحِبَةُ الْحَصَاةِ الَّتِي طَبَعَ فِيهَا أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) وَالسِّبْطُ إِلَى وَقْتِ أَبِي الْحَسَنِ (عَلَيْهِ السَّلام )","1/4/81/4","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[5,7,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ مَحْبُوبٍ عَنْ عَلِيِّ بْنِ رِئَابٍ عَنْ أَبِي عُبَيْدَةَ وَزُرَارَةَ جَمِيعاً عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ لَمَّا قُتِلَ الْحُسَيْنُ (عَلَيْهِ السَّلام) أَرْسَلَ مُحَمَّدُ بْنُ الْحَنَفِيَّةِ إِلَى عَلِيِّ بن الحسين (عَلَيْهما السَّلام) فَخَلا بِهِ فَقَالَ لَهُ يَا ابْنَ أَخِي قَدْ عَلِمْتَ أَنَّ رَسُولَ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) دَفَعَ الْوَصِيَّةَ وَالامَامَةَ مِنْ بَعْدِهِ إِلَى أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) ثُمَّ إِلَى الْحَسَنِ (عَلَيْهِ السَّلام) ثُمَّ إِلَى الْحُسَيْنِ (عَلَيْهِ السَّلام) وَقَدْ قُتِلَ أَبُوكَ رَضِيَ الله عَنْهُ وَصَلَّى عَلَى رُوحِهِ وَلَمْ يُوصِ وَأَنَا عَمُّكَ وَصِنْوُ أَبِيكَ وَوِلادَتِي مِنْ علي (عَلَيْهِ السَّلام) فِي سِنِّي وَقَدِيمِي أَحَقُّ بِهَا مِنْكَ فِي حَدَاثَتِكَ فَلا تُنَازِعْنِي فِي الْوَصِيَّةِ وَالامَامَةِ وَلا تُحَاجَّنِي فَقَالَ لَهُ عَلِيُّ بن الحسين (عَلَيْهما السَّلام) يَا عَمِّ اتَّقِ الله وَلا تَدَّعِ مَا لَيْسَ لَكَ بِحَقٍّ إِنِّي أَعِظُكَ أَنْ تَكُونَ مِنَ الْجَاهِلِينَ إِنَّ أَبِي يَا عَمِّ صَلَوَاتُ الله عَلَيْهِ أَوْصَى إِلَيَّ قَبْلَ أَنْ يَتَوَجَّهَ إِلَى الْعِرَاقِ وَعَهِدَ إِلَيَّ فِي ذَلِكَ قَبْلَ أَنْ يُسْتَشْهَدَ بِسَاعَةٍ وَهَذَا سِلاحُ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) عِنْدِي فَلا تَتَعَرَّضْ لِهَذَا فَإِنِّي أَخَافُ عَلَيْكَ نَقْصَ الْعُمُرِ وَتَشَتُّتَ الْحَالِ إِنَّ الله عَزَّ وَجَلَّ جَعَلَ الْوَصِيَّةَ وَالامَامَةَ فِي عَقِبِ الْحُسَيْنِ (عَلَيْهِ السَّلام) فَإِذَا أَرَدْتَ أَنْ تَعْلَمَ ذَلِكَ فَانْطَلِقْ بِنَا إِلَى الْحَجَرِ الاسْوَدِ حَتَّى نَتَحَاكَمَ إِلَيْهِ وَنَسْأَلَهُ عَنْ ذَلِكَ قَالَ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) وَكَانَ الْكَلامُ بَيْنَهُمَا بِمَكَّةَ فَانْطَلَقَا حَتَّى أَتَيَا الْحَجَرَ الاسْوَدَ فَقَالَ عَلِيُّ بْنُ الْحُسَيْنِ لِمُحَمَّدِ بْنِ الْحَنَفِيَّةِ ابْدَأْ أَنْتَ فَابْتَهِلْ إِلَى الله عَزَّ وَجَلَّ وَسَلْهُ أَنْ يُنْطِقَ لَكَ الْحَجَرَ ثُمَّ سَلْ فَابْتَهَلَ مُحَمَّدٌ فِي الدُّعَاءِ وَسَأَلَ الله ثُمَّ دَعَا الْحَجَرَ فَلَمْ يُجِبْهُ فَقَالَ عَلِيُّ بن الحسين (عَلَيْهما السَّلام) يَا عَمِّ لَوْ كُنْتَ وَصِيّاً وَإِمَاماً لاجَابَكَ قَالَ لَهُ مُحَمَّدٌ فَادْعُ الله أَنْتَ يَا ابْنَ أَخِي وَسَلْهُ فَدَعَا الله عَلِيُّ بن الحسين (عَلَيْهما السَّلام) بِمَا أَرَادَ ثُمَّ قَالَ أَسْأَلُكَ بِالَّذِي جَعَلَ فِيكَ مِيثَاقَ الانْبِيَاءِ وَمِيثَاقَ الاوْصِيَاءِ وَمِيثَاقَ النَّاسِ أَجْمَعِينَ لَمَّا أَخْبَرْتَنَا مَنِ الْوَصِيُّ وَالامَامُ بَعْدَ الْحُسَيْنِ بن علي (عَلَيْهما السَّلام) قَالَ فَتَحَرَّكَ الْحَجَرُ حَتَّى كَادَ أَنْ يَزُولَ عَنْ مَوْضِعِهِ ثُمَّ أَنْطَقَهُ الله عَزَّ وَجَلَّ بِلِسَانٍ عَرَبِيٍّ مُبِينٍ فَقَالَ اللهمَّ إِنَّ الْوَصِيَّةَ وَالامَامَةَ بَعْدَ الْحُسَيْنِ بن علي (عَلَيْهما السَّلام) إِلَى عَلِيِّ بْنِ الْحُسَيْنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ وَابْنِ فَاطِمَةَ بِنْتِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) قَالَ فَانْصَرَفَ مُحَمَّدُ بْنُ عَلِيٍّ وَهُوَ يَتَوَلَّى عَلِيَّ بْنَ الْحُسَيْنِ (عَلَيْهما السَّلام ) عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ حَمَّادِ بْنِ عِيسَى عَنْ حَرِيزٍ عَنْ زُرَارَةَ عَنْ ابي جعفر (عَلَيْهِ السَّلام) مِثْلَهُ.","1/4/81/5","مرآة العقول: صحيح وسنده التي حسن كالصحيح · البهبودي: لم يخرجه"],[6,7,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنِ الْمُعَلَّى بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ عَلِيٍّ قَالَ أَخْبَرَنِي سَمَاعَةُ بْنُ مِهْرَانَ قَالَ أَخْبَرَنِي الْكَلْبِيُّ النَّسَّابَةُ قَالَ دَخَلْتُ الْمَدِينَةَ وَلَسْتُ أَعْرِفُ شَيْئاً مِنْ هَذَا الامْرِ فَأَتَيْتُ الْمَسْجِدَ فَإِذَا جَمَاعَةٌ مِنْ قُرَيْشٍ فَقُلْتُ أَخْبِرُونِي عَنْ عَالِمِ أَهْلِ هَذَا الْبَيْتِ فَقَالُوا عَبْدُ الله بْنُ الْحَسَنِ فَأَتَيْتُ مَنْزِلَهُ فَاسْتَأْذَنْتُ فَخَرَجَ إِلَيَّ رَجُلٌ ظَنَنْتُ أَنَّهُ غُلامٌ لَهُ فَقُلْتُ لَهُ اسْتَأْذِنْ لِي عَلَى مَوْلاكَ فَدَخَلَ ثُمَّ خَرَجَ فَقَالَ لِيَ ادْخُلْ فَدَخَلْتُ فَإِذَا أَنَا بِشَيْخٍ مُعْتَكِفٍ شَدِيدِ الاجْتِهَادِ فَسَلَّمْتُ عَلَيْهِ فَقَالَ لِي مَنْ أَنْتَ فَقُلْتُ أَنَا الْكَلْبِيُّ النَّسَّابَةُ فَقَالَ مَا حَاجَتُكَ فَقُلْتُ جِئْتُ أَسْأَلُكَ فَقَالَ أَ مَرَرْتَ بِابْنِي مُحَمَّدٍ قُلْتُ بَدَأْتُ بِكَ فَقَالَ سَلْ فَقُلْتُ أَخْبِرْنِي عَنْ رَجُلٍ قَالَ لامْرَأَتِهِ أَنْتِ طَالِقٌ عَدَدَ نُجُومِ السَّمَاءِ فَقَالَ تَبِينُ بِرَأْسِ الْجَوْزَاءِ وَالْبَاقِي وِزْرٌ عَلَيْهِ وَعُقُوبَةٌ فَقُلْتُ فِي نَفْسِي وَاحِدَةٌ فَقُلْتُ مَا يَقُولُ الشَّيْخُ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ فَقَالَ قَدْ مَسَحَ قَوْمٌ صَالِحُونَ وَنَحْنُ أَهْلَ الْبَيْتِ لا نَمْسَحُ فَقُلْتُ فِي نَفْسِي ثِنْتَانِ فَقُلْتُ مَا تَقُولُ فِي أَكْلِ الْجِرِّيِّ أَ حَلالٌ هُوَ أَمْ حَرَامٌ فَقَالَ حَلالٌ إِلا أَنَّا أَهْلَ الْبَيْتِ نَعَافُهُ فَقُلْتُ فِي نَفْسِي ثَلاثٌ فَقُلْتُ فَمَا تَقُولُ فِي شُرْبِ النَّبِيذِ فَقَالَ حَلالٌ إِلا أَنَّا أَهْلَ الْبَيْتِ لا نَشْرَبُهُ فَقُمْتُ فَخَرَجْتُ مِنْ عِنْدِهِ وَأَنَا أَقُولُ هَذِهِ الْعِصَابَةُ تَكْذِبُ عَلَى أَهْلِ هَذَا الْبَيْتِ فَدَخَلْتُ الْمَسْجِدَ فَنَظَرْتُ إِلَى جَمَاعَةٍ مِنْ قُرَيْشٍ وَغَيْرِهِمْ مِنَ النَّاسِ فَسَلَّمْتُ عَلَيْهِمْ ثُمَّ قُلْتُ لَهُمْ مَنْ أَعْلَمُ أَهْلِ هَذَا الْبَيْتِ فَقَالُوا عَبْدُ الله بْنُ الْحَسَنِ فَقُلْتُ قَدْ أَتَيْتُهُ فَلَمْ أَجِدْ عِنْدَهُ شَيْئاً فَرَفَعَ رَجُلٌ مِنَ الْقَوْمِ رَأْسَهُ فَقَالَ ائْتِ جَعْفَرَ بْنَ مُحَمَّدٍ (عَلَيْهما السَّلام) فَهُوَ أَعْلَمُ أَهْلِ هَذَا الْبَيْتِ فَلامَهُ بَعْضُ مَنْ كَانَ بِالْحَضْرَةِ فَقُلْتُ إِنَّ الْقَوْمَ إِنَّمَا مَنَعَهُمْ مِنْ إِرْشَادِي إِلَيْهِ أَوَّلَ مَرَّةٍ الْحَسَدُ فَقُلْتُ لَهُ وَيْحَكَ إِيَّاهُ أَرَدْتُ فَمَضَيْتُ حَتَّى صِرْتُ إِلَى مَنْزِلِهِ فَقَرَعْتُ الْبَابَ فَخَرَجَ غُلامٌ لَهُ فَقَالَ ادْخُلْ يَا أَخَا كَلْبٍ فَوَ الله لَقَدْ أَدْهَشَنِي فَدَخَلْتُ وَأَنَا مُضْطَرِبٌ وَنَظَرْتُ فَإِذَا شَيْخٌ عَلَى مُصَلىً بِلا مِرْفَقَةٍ وَلا بَرْدَعَةٍ فَابْتَدَأَنِي بَعْدَ أَنْ سَلَّمْتُ عَلَيْهِ فَقَالَ لِي مَنْ أَنْتَ فَقُلْتُ فِي نَفْسِي يَا سُبْحَانَ الله غُلامُهُ يَقُولُ لِي بِالْبَابِ ادْخُلْ يَا أَخَا كَلْبٍ وَيَسْأَلُنِي الْمَوْلَى مَنْ أَنْتَ فَقُلْتُ لَهُ أَنَا الْكَلْبِيُّ. النَّسَّابَةُ فَضَرَبَ بِيَدِهِ عَلَى جَبْهَتِهِ وَقَالَ كَذَبَ الْعَادِلُونَ بِالله وَضَلُّوا ضَلالاً بَعِيداً وَخَسِرُوا خُسْرَاناً مُبِيناً يَا أَخَا كَلْبٍ إِنَّ الله عَزَّ وَجَلَّ يَقُولُ وَعاداً وَثَمُودَ وَأَصْحابَ الرَّسِّ وَقُرُوناً بَيْنَ ذلِكَ كَثِيراً أَ فَتَنْسِبُهَا أَنْتَ فَقُلْتُ لا جُعِلْتُ فِدَاكَ فَقَالَ لِي أَ فَتَنْسِبُ نَفْسَكَ قُلْتُ نَعَمْ أَنَا فُلانُ بْنُ فُلانِ بْنِ فُلانٍ حَتَّى ارْتَفَعْتُ فَقَالَ لِي قِفْ لَيْسَ حَيْثُ تَذْهَبُ وَيْحَكَ أَ تَدْرِي مَنْ فُلانُ بْنُ فُلانٍ قُلْتُ نَعَمْ فُلانُ بْنُ فُلانٍ قَالَ إِنَّ فُلانَ بْنَ فُلانٍ ابْنُ فُلانٍ الرَّاعِي الْكُرْدِيِّ إِنَّمَا كَانَ فُلانٌ الرَّاعِي الْكُرْدِيُّ عَلَى جَبَلِ آلِ فُلانٍ فَنَزَلَ إِلَى فُلانَةَ امْرَأَةِ فُلانٍ مِنْ جَبَلِهِ الَّذِي كَانَ يَرْعَى غَنَمَهُ عَلَيْهِ فَأَطْعَمَهَا شَيْئاً وَغَشِيَهَا فَوَلَدَتْ فُلاناً وَفُلانُ بْنُ فُلانٍ مِنْ فُلانَةَ وَفُلانِ بْنِ فُلانٍ ثُمَّ قَالَ أَ تَعْرِفُ هَذِهِ الاسَامِيَ قُلْتُ لا وَالله جُعِلْتُ فِدَاكَ فَإِنْ رَأَيْتَ أَنْ تَكُفَّ عَنْ هَذَا فَعَلْتَ فَقَالَ إِنَّمَا قُلْتَ فَقُلْتُ فَقُلْتُ إِنِّي لا أَعُودُ قَالَ لا نَعُودُ إِذاً وَاسْأَلْ عَمَّا جِئْتَ لَهُ فَقُلْتُ لَهُ أَخْبِرْنِي عَنْ رَجُلٍ قَالَ لامْرَأَتِهِ أَنْتِ طَالِقٌ عَدَدَ نُجُومِ السَّمَاءِ فَقَالَ وَيْحَكَ أَ مَا تَقْرَأُ سُورَةَ الطَّلاقِ قُلْتُ بَلَى قَالَ فَاقْرَأْ فَقَرَأْتُ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ قَالَ أَ تَرَى هَاهُنَا نُجُومَ السَّمَاءِ قُلْتُ لا قُلْتُ فَرَجُلٌ قَالَ لامْرَأَتِهِ أَنْتِ طَالِقٌ ثَلاثاً قَالَ تُرَدُّ إِلَى كِتَابِ الله وَسُنَّةِ نَبِيِّهِ (صَلَّى اللهُ عَلَيْهِ وَآلِه) ثُمَّ قَالَ لا طَلاقَ إِلا عَلَى طُهْرٍ مِنْ غَيْرِ جِمَاعٍ بِشَاهِدَيْنِ مَقْبُولَيْنِ فَقُلْتُ فِي نَفْسِي وَاحِدَةٌ ثُمَّ قَالَ سَلْ قُلْتُ مَا تَقُولُ فِي الْمَسْحِ عَلَى الْخُفَّيْنِ فَتَبَسَّمَ ثُمَّ قَالَ إِذَا كَانَ يَوْمُ الْقِيَامَةِ وَرَدَّ الله كُلَّ شَيْ‏ءٍ إِلَى شَيْئِهِ وَرَدَّ الْجِلْدَ إِلَى الْغَنَمِ فَتَرَى أَصْحَابَ الْمَسْحِ أَيْنَ يَذْهَبُ وُضُوؤُهُمْ فَقُلْتُ فِي نَفْسِي ثِنْتَانِ ثُمَّ الْتَفَتَ إِلَيَّ فَقَالَ سَلْ فَقُلْتُ أَخْبِرْنِي عَنْ أَكْلِ الْجِرِّيِّ فَقَالَ إِنَّ الله عَزَّ وَجَلَّ مَسَخَ طَائِفَةً مِنْ بَنِي إِسْرَائِيلَ فَمَا أَخَذَ مِنْهُمْ بَحْراً فَهُوَ الْجِرِّيُّ وَالْمَارْمَاهِي وَالزِّمَّارُ وَمَا سِوَى ذَلِكَ وَمَا أَخَذَ مِنْهُمْ بَرّاً فَالْقِرَدَةُ وَالْخَنَازِيرُ وَالْوَبْرُ وَالْوَرَكُ وَمَا سِوَى ذَلِكَ فَقُلْتُ فِي نَفْسِي ثَلاثٌ ثُمَّ الْتَفَتَ إِلَيَّ فَقَالَ سَلْ وَقُمْ فَقُلْتُ مَا تَقُولُ فِي النَّبِيذِ فَقَالَ حَلالٌ فَقُلْتُ إِنَّا نَنْبِذُ فَنَطْرَحُ فِيهِ الْعَكَرَ وَمَا سِوَى ذَلِكَ وَنَشْرَبُهُ فَقَالَ شَهْ شَهْ تِلْكَ الْخَمْرَةُ الْمُنْتِنَةُ فَقُلْتُ جُعِلْتُ فِدَاكَ فَأَيَّ نَبِيذٍ تَعْنِي فَقَالَ إِنَّ أَهْلَ الْمَدِينَةِ شَكَوْا إِلَى رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) تَغْيِيرَ الْمَاءِ وَفَسَادَ طَبَائِعِهِمْ فَأَمَرَهُمْ أَنْ يَنْبِذُوا فَكَانَ الرَّجُلُ يَأْمُرُ خَادِمَهُ أَنْ يَنْبِذَ لَهُ فَيَعْمِدُ إِلَى كَفٍّ مِنَ التَّمْرِ فَيَقْذِفُ بِهِ فِي الشَّنِّ فَمِنْهُ شُرْبُهُ وَمِنْهُ طَهُورُهُ فَقُلْتُ وَكَمْ كَانَ عَدَدُ التَّمْرِ الَّذِي كَانَ فِي الْكَفِّ فَقَالَ مَا حَمَلَ الْكَفُّ فَقُلْتُ وَاحِدَةٌ وَثِنْتَانِ فَقَالَ رُبَّمَا كَانَتْ وَاحِدَةً وَرُبَّمَا كَانَتْ ثِنْتَيْنِ فَقُلْتُ وَكَمْ كَانَ يَسَعُ الشَّنُّ فَقَالَ مَا بَيْنَ الارْبَعِينَ إِلَى الثَّمَانِينَ إِلَى مَا فَوْقَ ذَلِكَ فَقُلْتُ بِالارْطَالِ فَقَالَ نَعَمْ أَرْطَالٌ بِمِكْيَالِ الْعِرَاقِ قَالَ سَمَاعَةُ قَالَ الْكَلْبِيُّ ثُمَّ نَهَضَ (عَلَيْهِ السَّلام) وَقُمْتُ فَخَرَجْتُ وَأَنَا أَضْرِبُ بِيَدِي عَلَى الاخْرَى وَأَنَا أَقُولُ إِنْ كَانَ شَيْ‏ءٌ فَهَذَا فَلَمْ يَزَلِ الْكَلْبِيُّ يَدِينُ الله بِحُبِّ آلِ هَذَا الْبَيْتِ حَتَّى مَاتَ.","1/4/81/6","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[7,7,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى عَنْ أَبِي يَحْيَى الْوَاسِطِيِّ عَنْ هِشَامِ بْنِ سَالِمٍ قَالَ كُنَّا بِالْمَدِينَةِ بَعْدَ وَفَاةِ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) أَنَا وَصَاحِبُ الطَّاقِ وَالنَّاسُ مُجْتَمِعُونَ عَلَى عَبْدِ الله بْنِ جَعْفَرٍ أَنَّهُ صَاحِبُ الامْرِ بَعْدَ أَبِيهِ فَدَخَلْنَا عَلَيْهِ أَنَا وَصَاحِبُ الطَّاقِ وَالنَّاسُ عِنْدَهُ وَذَلِكَ أَنَّهُمْ رَوَوْا عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) أَنَّهُ قَالَ إِنَّ الامْرَ فِي الْكَبِيرِ مَا لَمْ تَكُنْ بِهِ عَاهَةٌ فَدَخَلْنَا عَلَيْهِ نَسْأَلُهُ عَمَّا كُنَّا نَسْأَلُ عَنْهُ أَبَاهُ فَسَأَلْنَاهُ عَنِ الزَّكَاةِ فِي كَمْ تَجِبُ فَقَالَ فِي مِائَتَيْنِ خَمْسَةٌ فَقُلْنَا فَفِي مِائَةٍ فَقَالَ دِرْهَمَانِ وَنِصْفٌ فَقُلْنَا وَالله مَا تَقُولُ الْمُرْجِئَةُ هَذَا قَالَ فَرَفَعَ يَدَهُ إِلَى السَّمَاءِ فَقَالَ وَالله مَا أَدْرِي مَا تَقُولُ الْمُرْجِئَةُ قَالَ فَخَرَجْنَا مِنْ عِنْدِهِ ضُلالاً لا نَدْرِي إِلَى أَيْنَ نَتَوَجَّهُ أَنَا وَأَبُو جَعْفَرٍ الاحْوَلُ فَقَعَدْنَا فِي بَعْضِ أَزِقَّةِ الْمَدِينَةِ بَاكِينَ حَيَارَى لا نَدْرِي إِلَى أَيْنَ نَتَوَجَّهُ وَلا مَنْ نَقْصِدُ وَنَقُولُ إِلَى الْمُرْجِئَةِ إِلَى الْقَدَرِيَّةِ إِلَى الزَّيْدِيَّةِ إِلَى الْمُعْتَزِلَةِ إِلَى الْخَوَارِجِ فَنَحْنُ كَذَلِكَ إِذْ رَأَيْتُ رَجُلاً شَيْخاً لا أَعْرِفُهُ يُومِئُ إِلَيَّ بِيَدِهِ فَخِفْتُ أَنْ يَكُونَ عَيْناً مِنْ عُيُونِ أَبِي جَعْفَرٍ الْمَنْصُورِ وَذَلِكَ أَنَّهُ كَانَ لَهُ بِالْمَدِينَةِ جَوَاسِيسُ يَنْظُرُونَ إِلَى مَنِ اتَّفَقَتْ شِيعَةُ جَعْفَرٍ (عَلَيْهِ السَّلام) عَلَيْهِ فَيَضْرِبُونَ عُنُقَهُ فَخِفْتُ أَنْ يَكُونَ مِنْهُمْ فَقُلْتُ لِلاحْوَلِ تَنَحَّ فَإِنِّي خَائِفٌ عَلَى نَفْسِي وَعَلَيْكَ وَإِنَّمَا يُرِيدُنِي لا يُرِيدُكَ فَتَنَحَّ عَنِّي لا تَهْلِكْ وَتُعِينَ عَلَى نَفْسِكَ فَتَنَحَّى غَيْرَ بَعِيدٍ وَتَبِعْتُ الشَّيْخَ وَذَلِكَ أَنِّي ظَنَنْتُ أَنِّي لا أَقْدِرُ عَلَى التَّخَلُّصِ مِنْهُ فَمَا زِلْتُ أَتْبَعُهُ وَقَدْ عَزَمْتُ عَلَى الْمَوْتِ حَتَّى وَرَدَ بِي عَلَى بَابِ أَبِي الْحَسَنِ (عَلَيْهِ السَّلام) ثُمَّ خَلانِي وَمَضَى فَإِذَا خَادِمٌ بِالْبَابِ فَقَالَ لِيَ ادْخُلْ رَحِمَكَ الله فَدَخَلْتُ فَإِذَا أَبُو الْحَسَنِ مُوسَى (عَلَيْهِ السَّلام) فَقَالَ لِيَ ابْتِدَاءً مِنْهُ لا إِلَى الْمُرْجِئَةِ وَلا إِلَى الْقَدَرِيَّةِ وَلا إِلَى الزَّيْدِيَّةِ وَلا إِلَى الْمُعْتَزِلَةِ وَلا إِلَى الْخَوَارِجِ إِلَيَّ إِلَيَّ فَقُلْتُ جُعِلْتُ فِدَاكَ مَضَى أَبُوكَ قَالَ نَعَمْ قُلْتُ مَضَى مَوْتاً قَالَ نَعَمْ قُلْتُ فَمَنْ لَنَا مِنْ بَعْدِهِ فَقَالَ إِنْ شَاءَ الله أَنْ يَهْدِيَكَ هَدَاكَ قُلْتُ جُعِلْتُ فِدَاكَ إِنَّ عَبْدَ الله يَزْعُمُ أَنَّهُ مِنْ بَعْدِ أَبِيهِ قَالَ يُرِيدُ عَبْدُ الله أَنْ لا يُعْبَدَ الله قَالَ قُلْتُ جُعِلْتُ فِدَاكَ فَمَنْ لَنَا مِنْ بَعْدِهِ قَالَ إِنْ شَاءَ الله أَنْ يَهْدِيَكَ هَدَاكَ قَالَ قُلْتُ جُعِلْتُ فِدَاكَ فَأَنْتَ هُوَ قَالَ لا مَا أَقُولُ ذَلِكَ قَالَ فَقُلْتُ فِي نَفْسِي لَمْ أُصِبْ طَرِيقَ الْمَسْأَلَةِ ثُمَّ قُلْتُ لَهُ جُعِلْتُ فِدَاكَ عَلَيْكَ إِمَامٌ قَالَ لا فَدَاخَلَنِي شَيْ‏ءٌ لا يَعْلَمُ إِلا الله عَزَّ وَجَلَّ إِعْظَاماً لَهُ وَهَيْبَةً أَكْثَرَ مِمَّا كَانَ يَحُلُّ بِي مِنْ أَبِيهِ إِذَا دَخَلْتُ عَلَيْهِ ثُمَّ قُلْتُ لَهُ جُعِلْتُ فِدَاكَ أَسْأَلُكَ عَمَّا كُنْتُ أَسْأَلُ أَبَاكَ فَقَالَ سَلْ تُخْبَرْ وَلا تُذِعْ فَإِنْ أَذَعْتَ فَهُوَ الذَّبْحُ فَسَأَلْتُهُ فَإِذَا هُوَ بَحْرٌ لا يُنْزَفُ قُلْتُ جُعِلْتُ فِدَاكَ شِيعَتُكَ وَشِيعَةُ أَبِيكَ ضُلالٌ فَأُلْقِي إِلَيْهِمْ وَأَدْعُوهُمْ إِلَيْكَ وَقَدْ أَخَذْتَ عَلَيَّ الْكِتْمَانَ قَالَ مَنْ آنَسْتَ مِنْهُ رُشْداً فَأَلْقِ إِلَيْهِ وَخُذْ عَلَيْهِ الْكِتْمَانَ فَإِنْ أَذَاعُوا فَهُوَ الذَّبْحُ وَأَشَارَ بِيَدِهِ إِلَى حَلْقِهِ قَالَ فَخَرَجْتُ مِنْ عِنْدِهِ فَلَقِيتُ أَبَا جَعْفَرٍ الاحْوَلَ فَقَالَ لِي مَا وَرَاءَكَ قُلْتُ الْهُدَى فَحَدَّثْتُهُ بِالْقِصَّةِ قَالَ ثُمَّ لَقِينَا الْفُضَيْلَ وَأَبَا بَصِيرٍ فَدَخَلا عَلَيْهِ وَسَمِعَا كَلامَهُ وَسَاءَلاهُ وَقَطَعَا عَلَيْهِ بِالامَامَةِ ثُمَّ لَقِينَا النَّاسَ أَفْوَاجاً فَكُلُّ مَنْ دَخَلَ عَلَيْهِ قَطَعَ إِلا طَائِفَةَ عَمَّارٍ وَأَصْحَابَهُ وَبَقِيَ عَبْدُ الله لا يَدْخُلُ إِلَيْهِ إِلا قَلِيلٌ مِنَ النَّاسِ فَلَمَّا رَأَى ذَلِكَ قَالَ مَا حَالَ النَّاسَ فَأُخْبِرَ أَنَّ هِشَاماً صَدَّ عَنْكَ النَّاسَ قَالَ هِشَامٌ فَأَقْعَدَ لِي بِالْمَدِينَةِ غَيْرَ وَاحِدٍ لِيَضْرِبُونِي.","1/4/81/7","مرآة العقول: مجهول بأبي يحيى · البهبودي: لم يخرجه"],[8,7,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ فُلانٍ الْوَاقِفِيِّ قَالَ كَانَ لِيَ ابْنُ عَمٍّ يُقَالُ لَهُ الْحَسَنُ بْنُ عَبْدِ الله كَانَ زَاهِداً وَكَانَ مِنْ أَعْبَدِ أَهْلِ زَمَانِهِ وَكَانَ يَتَّقِيهِ السُّلْطَانُ لِجِدِّهِ فِي الدِّينِ وَاجْتِهَادِهِ وَرُبَّمَا اسْتَقْبَلَ السُّلْطَانَ بِكَلامٍ صَعْبٍ يَعِظُهُ وَيَأْمُرُهُ بِالْمَعْرُوفِ وَيَنْهَاهُ عَنِ الْمُنْكَرِ وَكَانَ السُّلْطَانُ يَحْتَمِلُهُ لِصَلاحِهِ وَلَمْ تَزَلْ هَذِهِ حَالَتَهُ حَتَّى كَانَ يَوْمٌ مِنَ الايَّامِ إِذْ دَخَلَ عَلَيْهِ أَبُو الْحَسَنِ مُوسَى (عَلَيْهِ السَّلام) وَهُوَ فِي الْمَسْجِدِ فَرَآهُ فَأَوْمَأَ إِلَيْهِ فَأَتَاهُ فَقَالَ لَهُ يَا أَبَا عَلِيٍّ مَا أَحَبَّ إِلَيَّ مَا أَنْتَ فِيهِ وَأَسَرَّنِي إِلا أَنَّهُ لَيْسَتْ لَكَ مَعْرِفَةٌ فَاطْلُبِ الْمَعْرِفَةَ قَالَ جُعِلْتُ فِدَاكَ وَمَا الْمَعْرِفَةُ قَالَ اذْهَبْ فَتَفَقَّهْ وَاطْلُبِ الْحَدِيثَ قَالَ عَمَّنْ قَالَ عَنْ فُقَهَاءِ أَهْلِ الْمَدِينَةِ ثُمَّ اعْرِضْ عَلَيَّ الْحَدِيثَ قَالَ فَذَهَبَ فَكَتَبَ ثُمَّ جَاءَهُ فَقَرَأَهُ عَلَيْهِ فَأَسْقَطَهُ كُلَّهُ ثُمَّ قَالَ لَهُ اذْهَبْ فَاعْرِفِ الْمَعْرِفَةَ وَكَانَ الرَّجُلُ مَعْنِيّاً بِدِينِهِ فَلَمْ يَزَلْ يَتَرَصَّدُ أَبَا الْحَسَنِ (عَلَيْهِ السَّلام) حَتَّى خَرَجَ إِلَى ضَيْعَةٍ لَهُ فَلَقِيَهُ فِي الطَّرِيقِ فَقَالَ لَهُ جُعِلْتُ فِدَاكَ إِنِّي أَحْتَجُّ عَلَيْكَ بَيْنَ يَدَيِ الله فَدُلَّنِي عَلَى الْمَعْرِفَةِ قَالَ فَأَخْبَرَهُ بِأَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) وَمَا كَانَ بَعْدَ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَأَخْبَرَهُ بِأَمْرِ الرَّجُلَيْنِ فَقَبِلَ مِنْهُ ثُمَّ قَالَ لَهُ فَمَنْ كَانَ بَعْدَ أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) قَالَ الْحَسَنُ (عَلَيْهِ السَّلام) ثُمَّ الْحُسَيْنُ (عَلَيْهِ السَّلام) حَتَّى انْتَهَى إِلَى نَفْسِهِ ثُمَّ سَكَتَ قَالَ فَقَالَ لَهُ جُعِلْتُ فِدَاكَ فَمَنْ هُوَ الْيَوْمَ قَالَ إِنْ أَخْبَرْتُكَ تَقْبَلُ قَالَ بَلَى جُعِلْتُ فِدَاكَ قَالَ أَنَا هُوَ قَالَ فَشَيْ‏ءٌ أَسْتَدِلُّ بِهِ قَالَ اذْهَبْ إِلَى تِلْكَ الشَّجَرَةِ وَأَشَارَ بِيَدِهِ إِلَى أُمِّ غَيْلانَ فَقُلْ لَهَا يَقُولُ لَكِ مُوسَى بْنُ جَعْفَرٍ أَقْبِلِي قَالَ فَأَتَيْتُهَا فَرَأَيْتُهَا وَالله تَخُدُّ الارْضَ خَدّاً حَتَّى وَقَفَتْ بَيْنَ يَدَيْهِ ثُمَّ أَشَارَ إِلَيْهَا فَرَجَعَتْ قَالَ فَأَقَرَّ بِهِ ثُمَّ لَزِمَ الصَّمْتَ وَالْعِبَادَةَ فَكَانَ لا يَرَاهُ أَحَدٌ يَتَكَلَّمُ بَعْدَ ذَلِكَ. مُحَمَّدُ بْنُ يَحْيَى وَأَحْمَدُ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ الْحَسَنِ عَنْ إِبْرَاهِيمَ بْنِ هَاشِمٍ مِثْلَهُ.","1/4/81/8","مرآة العقول: مجهول بسنديه · البهبودي: لم يخرجه"],[9,7,"مُحَمَّدُ بْنُ يَحْيَى وَأَحْمَدُ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ الْحَسَنِ عَنْ أَحْمَدَ بْنِ الْحُسَيْنِ عَنْ مُحَمَّدِ بْنِ الطَّيِّبِ عَنْ عَبْدِ الْوَهَّابِ بْنِ مَنْصُورٍ عَنْ مُحَمَّدِ بْنِ أَبِي الْعَلاءِ قَالَ سَمِعْتُ يَحْيَى بْنَ أَكْثَمَ قَاضِيَ سَامَرَّاءَ بَعْدَ مَا جَهَدْتُ بِهِ وَنَاظَرْتُهُ وَحَاوَرْتُهُ وَوَاصَلْتُهُ وَسَأَلْتُهُ عَنْ عُلُومِ آلِ مُحَمَّدٍ فَقَالَ بَيْنَا أَنَا ذَاتَ يَوْمٍ دَخَلْتُ أَطُوفُ بِقَبْرِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَرَأَيْتُ مُحَمَّدَ بْنَ عَلِيٍّ الرِّضَا (عَلَيْهِ السَّلام) يَطُوفُ بِهِ فَنَاظَرْتُهُ فِي مَسَائِلَ عِنْدِي فَأَخْرَجَهَا إِلَيَّ فَقُلْتُ لَهُ وَالله إِنِّي أُرِيدُ أَنْ أَسْأَلَكَ مَسْأَلَةً وَإِنِّي وَالله لاسْتَحْيِي مِنْ ذَلِكَ فَقَالَ لِي أَنَا أُخْبِرُكَ قَبْلَ أَنْ تَسْأَلَنِي تَسْأَلُنِي عَنِ الامَامِ فَقُلْتُ هُوَ وَالله هَذَا فَقَالَ أَنَا هُوَ فَقُلْتُ عَلامَةً فَكَانَ فِي يَدِهِ عَصًا فَنَطَقَتْ وَقَالَتْ إِنَّ مَوْلايَ إِمَامُ هَذَا الزَّمَانِ وَهُوَ الْحُجَّةُ.","1/4/81/9","مرآة العقول: مجهول أو ضعيف بأبي يحي ى · البهبودي: لم يخرجه"],[10,7,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ أَوْ غَيْرِهِ عَنْ عَلِيِّ بْنِ الْحَكَمِ عَنِ الْحُسَيْنِ بْنِ عُمَرَ بْنِ يَزِيدَ قَالَ دَخَلْتُ عَلَى الرِّضَا (عَلَيْهِ السَّلام) وَأَنَا يَوْمَئِذٍ وَاقِفٌ وَقَدْ كَانَ أَبِي سَأَلَ أَبَاهُ عَنْ سَبْعِ مَسَائِلَ فَأَجَابَهُ فِي سِتٍّ وَأَمْسَكَ عَنِ السَّابِعَةِ فَقُلْتُ وَالله لاسْأَلَنَّهُ عَمَّا سَأَلَ أَبِي أَبَاهُ فَإِنْ أَجَابَ بِمِثْلِ جَوَابِ أَبِيهِ كَانَتْ دَلالَةً فَسَأَلْتُهُ فَأَجَابَ بِمِثْلِ جَوَابِ أَبِيهِ أَبِي فِي الْمَسَائِلِ السِّتِّ فَلَمْ يَزِدْ فِي الْجَوَابِ وَاواً وَلا يَاءً وَأَمْسَكَ عَنِ السَّابِعَةِ وَقَدْ كَانَ أَبِي قَالَ لابِيهِ إِنِّي أَحْتَجُّ عَلَيْكَ عِنْدَ الله يَوْمَ الْقِيَامَةِ أَنَّكَ زَعَمْتَ أَنَّ عَبْدَ الله لَمْ يَكُنْ إِمَاماً فَوَضَعَ يَدَهُ عَلَى عُنُقِهِ ثُمَّ قَالَ لَهُ نَعَمْ احْتَجَّ عَلَيَّ بِذَلِكَ عِنْدَ الله عَزَّ وَجَلَّ فَمَا كَانَ فِيهِ مِنْ إِثْمٍ فَهُوَ فِي رَقَبَتِي فَلَمَّا وَدَّعْتُهُ قَالَ إِنَّهُ لَيْسَ أَحَدٌ مِنْ شِيعَتِنَا يُبْتَلَى بِبَلِيَّةٍ أَوْ يَشْتَكِي فَيَصْبِرُ عَلَى ذَلِكَ إِلا كَتَبَ الله لَهُ أَجْرَ أَلْفِ شَهِيدٍ فَقُلْتُ فِي نَفْسِي وَالله مَا كَانَ لِهَذَا ذِكْرٌ فَلَمَّا مَضَيْتُ وَكُنْتُ فِي بَعْضِ الطَّرِيقِ خَرَجَ بِي عِرْقُ الْمَدِينِيِّ فَلَقِيتُ مِنْهُ شِدَّةً فَلَمَّا كَانَ مِنْ قَابِلٍ حَجَجْتُ فَدَخَلْتُ عَلَيْهِ وَقَدْ بَقِيَ مِنْ وَجَعِي بَقِيَّةٌ فَشَكَوْتُ إِلَيْهِ وَقُلْتُ لَهُ جُعِلْتُ فِدَاكَ عَوِّذْ رِجْلِي وَبَسَطْتُهَا بَيْنَ يَدَيْهِ فَقَالَ لِي لَيْسَ عَلَى رِجْلِكَ هَذِهِ بَأْسٌ وَلَكِنْ أَرِنِي رِجْلَكَ الصَّحِيحَةَ فَبَسَطْتُهَا بَيْنَ يَدَيْهِ فَعَوَّذَهَا فَلَمَّا خَرَجْتُ لَمْ أَلْبَثْ إِلا يَسِيراً حَتَّى خَرَجَ بِيَ الْعِرْقُ وَكَانَ وَجَعُهُ يَسِيراً.","1/4/81/10","مرآة العقول: مجهول · البهبودي: صحيح"],[11,7,"أَحْمَدُ بْنُ مِهْرَانَ عَنْ مُحَمَّدِ بْنِ عَلِيٍّ عَنِ ابْنِ قِيَامَا الْوَاسِطِيِّ وَكَانَ مِنَ الْوَاقِفَةِ قَالَ دَخَلْتُ عَلَى عَلِيِّ بْنِ مُوسَى الرِّضَا (عَلَيْهِ السَّلام) فَقُلْتُ لَهُ يَكُونُ إِمَامَانِ قَالَ لا إِلا وَأَحَدُهُمَا صَامِتٌ فَقُلْتُ لَهُ هُوَ ذَا أَنْتَ لَيْسَ لَكَ صَامِتٌ وَلَمْ يَكُنْ وُلِدَ لَهُ أَبُو جَعْفَرٍ بَعْدُ فَقَالَ لِي وَالله لَيَجْعَلَنَّ الله مِنِّي مَا يُثْبِتُ بِهِ الْحَقَّ وَأَهْلَهُ وَيَمْحَقُ بِهِ الْبَاطِلَ وَأَهْلَهُ فَوُلِدَ لَهُ بَعْدَ سَنَةٍ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) فَقِيلَ لابْنِ قِيَامَا أَ لا تُقْنِعُكَ هَذِهِ الايَةُ فَقَالَ أَمَا وَالله إِنَّهَا لآَيَةٌ عَظِيمَةٌ وَلَكِنْ كَيْفَ أَصْنَعُ بِمَا قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) فِي ابْنِهِ.","1/4/81/11","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[12,7,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنِ الْوَشَّاءِ قَالَ أَتَيْتُ خُرَاسَانَ وَأَنَا وَاقِفٌ فَحَمَلْتُ مَعِي مَتَاعاً وَكَانَ مَعِي ثَوْبٌ وَشِيٌّ فِي بَعْضِ الرِّزَمِ وَلَمْ أَشْعُرْ بِهِ وَلَمْ أَعْرِفْ مَكَانَهُ فَلَمَّا قَدِمْتُ مَرْوَ وَنَزَلْتُ فِي بَعْضِ مَنَازِلِهَا لَمْ أَشْعُرْ إِلا وَرَجُلٌ مَدَنِيٌّ مِنْ بَعْضِ مُوَلَّدِيهَا فَقَالَ لِي إِنَّ أَبَا الْحَسَنِ الرِّضَا (عَلَيْهِ السَّلام) يَقُولُ لَكَ ابْعَثْ إِلَيَّ الثَّوْبَ الْوَشِيَّ الَّذِي عِنْدَكَ قَالَ فَقُلْتُ وَمَنْ أَخْبَرَ أَبَا الْحَسَنِ بِقُدُومِي وَأَنَا قَدِمْتُ آنِفاً وَمَا عِنْدِي ثَوْبٌ وَشِيٌّ فَرَجَعَ إِلَيْهِ وَعَادَ إِلَيَّ فَقَالَ يَقُولُ لَكَ بَلَى هُوَ فِي مَوْضِعِ كَذَا وَكَذَا وَرِزْمَتُهُ كَذَا وَكَذَا فَطَلَبْتُهُ حَيْثُ قَالَ فَوَجَدْتُهُ فِي أَسْفَلِ الرِّزْمَةِ فَبَعَثْتُ بِهِ إِلَيْهِ.","1/4/81/12","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[13,7,"ابْنُ فَضَّالٍ عَنْ عَبْدِ الله بْنِ الْمُغِيرَةِ قَالَ كُنْتُ وَاقِفاً وَحَجَجْتُ عَلَى تِلْكَ الْحَالِ فَلَمَّا صِرْتُ بِمَكَّةَ خَلَجَ فِي صَدْرِي شَيْ‏ءٌ فَتَعَلَّقْتُ بِالْمُلْتَزَمِ ثُمَّ قُلْتُ اللهمَّ قَدْ عَلِمْتَ طَلِبَتِي وَإِرَادَتِي فَأَرْشِدْنِي إِلَى خَيْرِ الادْيَانِ فَوَقَعَ فِي نَفْسِي أَنْ آتِيَ الرِّضَا (عَلَيْهِ السَّلام) فَأَتَيْتُ الْمَدِينَةَ فَوَقَفْتُ بِبَابِهِ وَقُلْتُ لِلْغُلامِ قُلْ لِمَوْلاكَ رَجُلٌ مِنْ أَهْلِ الْعِرَاقِ بِالْبَابِ قَالَ فَسَمِعْتُ نِدَاءَهُ وَهُوَ يَقُولُ ادْخُلْ يَا عَبْدَ الله بْنَ الْمُغِيرَةِ ادْخُلْ يَا عَبْدَ الله بْنَ الْمُغِيرَةِ فَدَخَلْتُ فَلَمَّا نَظَرَ إِلَيَّ قَالَ لِي قَدْ أَجَابَ الله دُعَاءَكَ وَهَدَاكَ لِدِينِهِ فَقُلْتُ أَشْهَدُ أَنَّكَ حُجَّةُ الله وَأَمِينُهُ عَلَى خَلْقِهِ.","1/4/81/13","مرآة العقول: موثق وفي أول السند إرسا ل · البهبودي: صحيح"],[14,7,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عَبْدِ الله قَالَ كَانَ عَبْدُ الله بْنُ هُلَيْلٍ يَقُولُ بِعَبْدِ الله فَصَارَ إِلَى الْعَسْكَرِ فَرَجَعَ عَنْ ذَلِكَ فَسَأَلْتُهُ عَنْ سَبَبِ رُجُوعِهِ فَقَالَ إِنِّي عَرَضْتُ لابِي الْحَسَنِ (عَلَيْهِ السَّلام) أَنْ أَسْأَلَهُ عَنْ ذَلِكَ فَوَافَقَنِي فِي طَرِيقٍ ضَيِّقٍ فَمَالَ نَحْوِي حَتَّى إِذَا حَاذَانِي أَقْبَلَ نَحْوِي بِشَيْ‏ءٍ مِنْ فِيهِ فَوَقَعَ عَلَى صَدْرِي فَأَخَذْتُهُ فَإِذَا هُوَ رَقٌّ فِيهِ مَكْتُوبٌ مَا كَانَ هُنَالِكَ وَلا كَذَلِكَ.","1/4/81/14","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[15,7,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ بَعْضِ أَصْحَابِنَا ذَكَرَ اسْمَهُ قَالَ حَدَّثَنَا مُحَمَّدُ بْنُ إِبْرَاهِيمَ قَالَ أَخْبَرَنَا مُوسَى بْنُ مُحَمَّدِ بْنِ إِسْمَاعِيلَ بْنِ عُبَيْدِ الله بْنِ الْعَبَّاسِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ حَدَّثَنِي جَعْفَرُ بْنُ زَيْدِ بْنِ مُوسَى عَنْ أَبِيهِ عَنْ آبَائِهِ (عَلَيْهم السَّلام) قَالُوا جَاءَتْ أُمُّ أَسْلَمَ يَوْماً إِلَى النَّبِيِّ (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَهُوَ فِي مَنْزِلِ أُمِّ سَلَمَةَ فَسَأَلَتْهَا عَنْ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَقَالَتْ خَرَجَ فِي بَعْضِ الْحَوَائِجِ وَالسَّاعَةَ يَجِي‏ءُ فَانْتَظَرَتْهُ عِنْدَ أُمِّ سَلَمَةَ حَتَّى جَاءَ (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَقَالَتْ أُمُّ أَسْلَمَ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ الله إِنِّي قَدْ قَرَأْتُ الْكُتُبَ وَعَلِمْتُ كُلَّ نَبِيٍّ وَوَصِيٍّ فَمُوسَى كَانَ لَهُ وَصِيٌّ فِي حَيَاتِهِ وَوَصِيٌّ بَعْدَ مَوْتِهِ وَكَذَلِكَ عِيسَى فَمَنْ وَصِيُّكَ يَا رَسُولَ الله فَقَالَ لَهَا يَا أُمَّ أَسْلَمَ وَصِيِّي فِي حَيَاتِي وَبَعْدَ مَمَاتِي وَاحِدٌ ثُمَّ قَالَ لَهَا يَا أُمَّ أَسْلَمَ مَنْ فَعَلَ فِعْلِي هَذَا فَهُوَ وَصِيِّي ثُمَّ ضَرَبَ بِيَدِهِ إِلَى حَصَاةٍ مِنَ الارْضِ فَفَرَكَهَا بِإِصْبَعِهِ فَجَعَلَهَا شِبْهَ الدَّقِيقِ ثُمَّ عَجَنَهَا ثُمَّ طَبَعَهَا بِخَاتَمِهِ ثُمَّ قَالَ مَنْ فَعَلَ فِعْلِي هَذَا فَهُوَ وَصِيِّي فِي حَيَاتِي وَبَعْدَ مَمَاتِي فَخَرَجْتُ مِنْ عِنْدِهِ فَأَتَيْتُ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) فَقُلْتُ بِأَبِي أَنْتَ وَأُمِّي أَنْتَ وَصِيُّ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) قَالَ نَعَمْ يَا أُمَّ أَسْلَمَ ثُمَّ ضَرَبَ بِيَدِهِ إِلَى حَصَاةٍ فَفَرَكَهَا فَجَعَلَهَا كَهَيْئَةِ الدَّقِيقِ ثُمَّ عَجَنَهَا وَخَتَمَهَا بِخَاتَمِهِ ثُمَّ قَالَ يَا أُمَّ أَسْلَمَ مَنْ فَعَلَ فِعْلِي هَذَا فَهُوَ وَصِيِّي فَأَتَيْتُ الْحَسَنَ (عَلَيْهِ السَّلام) وَهُوَ غُلامٌ فَقُلْتُ لَهُ يَا سَيِّدِي أَنْتَ وَصِيُّ أَبِيكَ فَقَالَ نَعَمْ يَا أُمَّ أَسْلَمَ وَضَرَبَ بِيَدِهِ وَأَخَذَ حَصَاةً فَفَعَلَ بِهَا كَفِعْلِهِمَا فَخَرَجْتُ مِنْ عِنْدِهِ فَأَتَيْتُ الْحُسَيْنَ (عَلَيْهِ السَّلام) وَإِنِّي لَمُسْتَصْغِرَةٌ لِسِنِّهِ فَقُلْتُ لَهُ بِأَبِي أَنْتَ وَأُمِّي أَنْتَ وَصِيُّ أَخِيكَ فَقَالَ نَعَمْ يَا أُمَّ أَسْلَمَ ائْتِينِي بِحَصَاةٍ ثُمَّ فَعَلَ كَفِعْلِهِمْ فَعَمَرَتْ أُمُّ أَسْلَمَ حَتَّى لَحِقَتْ بِعَلِيِّ بْنِ الْحُسَيْنِ بَعْدَ قَتْلِ الْحُسَيْنِ (عَلَيْهِ السَّلام) فِي مُنْصَرَفِهِ فَسَأَلَتْهُ أَنْتَ وَصِيُّ أَبِيكَ فَقَالَ نَعَمْ ثُمَّ فَعَلَ كَفِعْلِهِمْ صَلَوَاتُ الله عَلَيْهِمْ أَجْمَعِينَ.","1/4/81/15","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[16,7,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْحُسَيْنِ بْنِ سَعِيدٍ عَنِ الْحُسَيْنِ بْنِ الْجَارُودِ عَنْ مُوسَى بْنِ بَكْرِ بْنِ دَابٍ عَمَّنْ حَدَّثَهُ عَنْ ابي جعفر (عَلَيْهِ السَّلام) أَنَّ زَيْدَ بْنَ عَلِيِّ بن الحسين (عَلَيْهما السَّلام) دَخَلَ عَلَى أَبِي جَعْفَرٍ مُحَمَّدِ بْنِ عَلِيٍّ وَمَعَهُ كُتُبٌ مِنْ أَهْلِ الْكُوفَةِ يَدْعُونَهُ فِيهَا إِلَى أَنْفُسِهِمْ وَيُخْبِرُونَهُ بِاجْتِمَاعِهِمْ وَيَأْمُرُونَهُ بِالْخُرُوجِ فَقَالَ لَهُ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) هَذِهِ الْكُتُبُ ابْتِدَاءٌ مِنْهُمْ أَوْ جَوَابُ مَا كَتَبْتَ بِهِ إِلَيْهِمْ وَدَعَوْتَهُمْ إِلَيْهِ فَقَالَ بَلِ ابْتِدَاءٌ مِنَ الْقَوْمِ لِمَعْرِفَتِهِمْ بِحَقِّنَا وَبِقَرَابَتِنَا مِنْ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَلِمَا يَجِدُونَ فِي كِتَابِ الله عَزَّ وَجَلَّ مِنْ وُجُوبِ مَوَدَّتِنَا وَفَرْضِ طَاعَتِنَا وَلِمَا نَحْنُ فِيهِ مِنَ الضِّيقِ وَالضَّنْكِ وَالْبَلاءِ فَقَالَ لَهُ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) إِنَّ الطَّاعَةَ مَفْرُوضَةٌ مِنَ الله عَزَّ وَجَلَّ وَسُنَّةٌ أَمْضَاهَا فِي الاوَّلِينَ وَكَذَلِكَ يُجْرِيهَا فِي الاخِرِينَ وَالطَّاعَةُ لِوَاحِدٍ مِنَّا وَالْمَوَدَّةُ لِلْجَمِيعِ وَأَمْرُ الله يَجْرِي لاوْلِيَائِهِ بِحُكْمٍ مَوْصُولٍ وَقَضَاءٍ مَفْصُولٍ وَحَتْمٍ مَقْضِيٍّ وَقَدَرٍ مَقْدُورٍ وَأَجَلٍ مُسَمًّى لِوَقْتٍ مَعْلُومٍ فَلا يَسْتَخِفَّنَّكَ الَّذِينَ لا يُوقِنُونَ إِنَّهُمْ لَنْ يُغْنُوا عَنْكَ مِنَ الله شَيْئاً فَلا تَعْجَلْ فَإِنَّ الله لا يَعْجَلُ لِعَجَلَةِ الْعِبَادِ وَلا تَسْبِقَنَّ الله فَتُعْجِزَكَ الْبَلِيَّةُ فَتَصْرَعَكَ قَالَ فَغَضِبَ زَيْدٌ عِنْدَ ذَلِكَ ثُمَّ قَالَ لَيْسَ الامَامُ مِنَّا مَنْ جَلَسَ فِي بَيْتِهِ وَأَرْخَى سِتْرَهُ وَثَبَّطَ عَنِ الْجِهَادِ وَلَكِنَّ الامَامَ مِنَّا مَنْ مَنَعَ حَوْزَتَهُ وَجَاهَدَ فِي سَبِيلِ الله حَقَّ جِهَادِهِ وَدَفَعَ عَنْ رَعِيَّتِهِ وَذَبَّ عَنْ حَرِيمِهِ قَالَ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) هَلْ تَعْرِفُ يَا أَخِي مِنْ نَفْسِكَ شَيْئاً مِمَّا نَسَبْتَهَا إِلَيْهِ فَتَجِي‏ءَ عَلَيْهِ بِشَاهِدٍ مِنْ كِتَابِ الله أَوْ حُجَّةٍ مِنْ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) أَوْ تَضْرِبَ بِهِ مَثَلاً فَإِنَّ الله عَزَّ وَجَلَّ أَحَلَّ حَلالاً وَحَرَّمَ حَرَاماً وَفَرَضَ فَرَائِضَ وَضَرَبَ أَمْثَالاً وَسَنَّ سُنَناً وَلَمْ يَجْعَلِ الامَامَ الْقَائِمَ بِأَمْرِهِ شُبْهَةً فِيمَا فَرَضَ لَهُ مِنَ الطَّاعَةِ أَنْ يَسْبِقَهُ بِأَمْرٍ قَبْلَ مَحَلِّهِ أَوْ يُجَاهِدَ فِيهِ قَبْلَ حُلُولِهِ وَقَدْ قَالَ الله عَزَّ وَجَلَّ فِي الصَّيْدِ لا تَقْتُلُوا الصَّيْدَ وَأَنْتُمْ حُرُمٌ أَ فَقَتْلُ الصَّيْدِ أَعْظَمُ أَمْ قَتْلُ النَّفْسِ الَّتِي حَرَّمَ الله وَجَعَلَ لِكُلِّ شَيْ‏ءٍ مَحَلاً وَقَالَ الله عَزَّ وَجَلَّ وَإِذا حَلَلْتُمْ فَاصْطادُوا وَقَالَ عَزَّ وَجَلَّ لا تُحِلُّوا شَعائِرَ الله وَلا الشَّهْرَ الْحَرامَ فَجَعَلَ الشُّهُورَ عِدَّةً مَعْلُومَةً فَجَعَلَ مِنْهَا أَرْبَعَةً حُرُماً وَقَالَ فَسِيحُوا فِي الارْضِ أَرْبَعَةَ أَشْهُرٍ وَاعْلَمُوا أَنَّكُمْ غَيْرُ مُعْجِزِي الله ثُمَّ قَالَ تَبَارَكَ وَتَعَالَى فَإِذَا انْسَلَخَ الاشْهُرُ الْحُرُمُ فَاقْتُلُوا الْمُشْرِكِينَ حَيْثُ وَجَدْتُمُوهُمْ فَجَعَلَ لِذَلِكَ مَحَلاً وَقَالَ وَلا تَعْزِمُوا عُقْدَةَ النِّكاحِ حَتَّى يَبْلُغَ الْكِتابُ أَجَلَهُ فَجَعَلَ لِكُلِّ شَيْ‏ءٍ أَجَلاً وَلِكُلِّ أَجَلٍ كِتَاباً فَإِنْ كُنْتَ عَلَى بَيِّنَةٍ مِنْ رَبِّكَ وَيَقِينٍ مِنْ أَمْرِكَ وَتِبْيَانٍ مِنْ شَأْنِكَ فَشَأْنَكَ وَإِلا فَلا تَرُومَنَّ أَمْراً أَنْتَ مِنْهُ فِي شَكٍّ وَشُبْهَةٍ وَلا تَتَعَاطَ زَوَالَ مُلْكٍ لَمْ تَنْقَضِ أُكُلُهُ وَلَمْ يَنْقَطِعْ مَدَاهُ وَلَمْ يَبْلُغِ الْكِتَابُ أَجَلَهُ فَلَوْ قَدْ بَلَغَ مَدَاهُ وَانْقَطَعَ أُكُلُهُ وَبَلَغَ الْكِتَابُ أَجَلَهُ لانْقَطَعَ الْفَصْلُ وَتَتَابَعَ النِّظَامُ وَلاعْقَبَ الله فِي التَّابِعِ وَالْمَتْبُوعِ الذُّلَّ وَالصَّغَارَ أَعُوذُ بِالله مِنْ إِمَامٍ ضَلَّ عَنْ وَقْتِهِ فَكَانَ التَّابِعُ فِيهِ أَعْلَمَ مِنَ الْمَتْبُوعِ أَ تُرِيدُ يَا أَخِي أَنْ تُحْيِيَ مِلَّةَ قَوْمٍ قَدْ كَفَرُوا بِ‏آيَاتِ الله وَعَصَوْا رَسُولَهُ وَاتَّبَعُوا أَهْوَاءَهُمْ بِغَيْرِ هُدًى مِنَ الله وَادَّعَوُا الْخِلافَةَ بِلا بُرْهَانٍ مِنَ الله وَلا عَهْدٍ مِنْ رَسُولِهِ أُعِيذُكَ بِالله يَا أَخِي أَنْ تَكُونَ غَداً الْمَصْلُوبَ بِالْكُنَاسَةِ ثُمَّ ارْفَضَّتْ عَيْنَاهُ وَسَالَتْ دُمُوعُهُ ثُمَّ قَالَ الله بَيْنَنَا وَبَيْنَ مَنْ هَتَكَ سِتْرَنَا وَجَحَدَنَا حَقَّنَا وَأَفْشَى سِرَّنَا وَنَسَبَنَا إِلَى غَيْرِ جَدِّنَا وَقَالَ فِينَا مَا لَمْ نَقُلْهُ فِي أَنْفُسِنَا.","1/4/81/16","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[17,7,"بَعْضُ أَصْحَابِنَا عَنْ مُحَمَّدِ بْنِ حَسَّانَ عَنْ مُحَمَّدِ بْنِ رَنْجَوَيْهِ عَنْ عَبْدِ الله بْنِ الْحَكَمِ الارْمَنِيِّ عَنْ عَبْدِ الله بْنِ إِبْرَاهِيمَ بْنِ مُحَمَّدٍ الْجَعْفَرِيِّ قَالَ أَتَيْنَا خَدِيجَةَ بِنْتَ عُمَرَ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ بْنِ عَلِيِّ بْنِ أَبِي طَالِبٍ (عَلَيْهِ السَّلام) نُعَزِّيهَا بِابْنِ بِنْتِهَا فَوَجَدْنَا عِنْدَهَا مُوسَى بْنَ عَبْدِ الله بْنِ الْحَسَنِ فَإِذَا هِيَ فِي نَاحِيَةٍ قَرِيباً مِنَ النِّسَاءِ فَعَزَّيْنَاهُمْ ثُمَّ أَقْبَلْنَا عَلَيْهِ فَإِذَا هُوَ يَقُولُ لابْنَةِ أَبِي يَشْكُرَ الرَّاثِيَةِ قُولِي فَقَالَتْ. اعْدُدْ رَسُولَ الله وَاعْدُدْ بَعْدَهُ***أَسَدَ الالَهِ وَثَالِثاً عَبَّاسَا وَاعْدُدْ عَلِيَّ الْخَيْرِ وَاعْدُدْ جَعْفَراً***وَاعْدُدْ عَقِيلاً بَعْدَهُ الرُّوَّاسَا فَقَالَ أَحْسَنْتِ وَأَطْرَبْتِنِي زِيدِينِي فَانْدَفَعَتْ تَقُولُ. وَمِنَّا إِمَامُ الْمُتَّقِينَ مُحَمَّدٌ*** وَفَارِسُهُ ذَاكَ الامَامُ الْمُطَهَّرُ وَ مِنَّا عَلِيٌّ صِهْرُهُ وَابْنُ عَمِّهِ*** وَحَمْزَةُ مِنَّا وَالْمُهَذَّبُ جَعْفَرُ فَأَقَمْنَا عِنْدَهَا حَتَّى كَادَ اللَّيْلُ أَنْ يَجِي‏ءَ ثُمَّ قَالَتْ خَدِيجَةُ سَمِعْتُ عَمِّي مُحَمَّدَ بْنَ عَلِيٍّ صَلَوَاتُ الله عَلَيْهِ وَهُوَ يَقُولُ إِنَّمَا تَحْتَاجُ الْمَرْأَةُ فِي الْمَأْتَمِ إِلَى النَّوْحِ لِتَسِيلَ دَمْعَتُهَا وَلا يَنْبَغِي لَهَا أَنْ تَقُولَ هُجْراً فَإِذَا جَاءَ اللَّيْلُ فَلا تُؤْذِي الْمَلائِكَةَ بِالنَّوْحِ ثُمَّ خَرَجْنَا فَغَدَوْنَا إِلَيْهَا غُدْوَةً فَتَذَاكَرْنَا عِنْدَهَا اخْتِزَالَ مَنْزِلِهَا مِنْ دَارِ أَبِي عَبْدِ الله جَعْفَرِ بْنِ مُحَمَّدٍ فَقَالَ هَذِهِ دَارٌ تُسَمَّى دَارَ السَّرِقَةِ فَقَالَتْ هَذَا مَا اصْطَفَى مَهْدِيُّنَا تَعْنِي مُحَمَّدَ بْنَ عَبْدِ الله بْنِ الْحَسَنِ تُمَازِحُهُ بِذَلِكَ فَقَالَ مُوسَى بْنُ عَبْدِ الله وَالله لاخْبِرَنَّكُمْ بِالْعَجَبِ رَأَيْتُ أَبِي رَحِمَهُ الله لَمَّا أَخَذَ فِي أَمْرِ مُحَمَّدِ بْنِ عَبْدِ الله وَأَجْمَعَ عَلَى لِقَاءِ أَصْحَابِهِ فَقَالَ لا أَجِدُ هَذَا الامْرَ يَسْتَقِيمُ إِلا أَنْ أَلْقَى أَبَا عَبْدِ الله جَعْفَرَ بْنَ مُحَمَّدٍ فَانْطَلَقَ وَهُوَ مُتَّكٍ عَلَيَّ فَانْطَلَقْتُ مَعَهُ حَتَّى أَتَيْنَا أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) فَلَقِينَاهُ خَارِجاً يُرِيدُ الْمَسْجِدَ فَاسْتَوْقَفَهُ أَبِي وَكَلَّمَهُ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) لَيْسَ هَذَا مَوْضِعَ ذَلِكَ نَلْتَقِي إِنْ شَاءَ الله فَرَجَعَ أَبِي مَسْرُوراً ثُمَّ أَقَامَ حَتَّى إِذَا كَانَ الْغَدُ أَوْ بَعْدَهُ بِيَوْمٍ انْطَلَقْنَا حَتَّى أَتَيْنَاهُ فَدَخَلَ عَلَيْهِ أَبِي وَأَنَا مَعَهُ فَابْتَدَأَ الْكَلامَ ثُمَّ قَالَ لَهُ فِيمَا يَقُولُ قَدْ عَلِمْتَ جُعِلْتُ فِدَاكَ أَنَّ السِّنَّ لِي عَلَيْكَ وَأَنَّ فِي قَوْمِكَ مَنْ هُوَ أَسَنُّ مِنْكَ وَلَكِنَّ الله عَزَّ وَجَلَّ قَدْ قَدَّمَ لَكَ فَضْلاً لَيْسَ هُوَ لاحَدٍ مِنْ قَوْمِكَ وَقَدْ جِئْتُكَ مُعْتَمِداً لِمَا أَعْلَمُ مِنْ بِرِّكَ وَأَعْلَمُ فَدَيْتُكَ أَنَّكَ إِذَا أَجَبْتَنِي لَمْ يَتَخَلَّفْ عَنِّي أَحَدٌ مِنْ أَصْحَابِكَ وَلَمْ يَخْتَلِفْ عَلَيَّ اثْنَانِ مِنْ قُرَيْشٍ وَلا غَيْرِهِمْ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) إِنَّكَ تَجِدُ غَيْرِي أَطْوَعَ لَكَ مِنِّي وَلا حَاجَةَ لَكَ فِيَّ فَوَ الله إِنَّكَ لَتَعْلَمُ أَنِّي أُرِيدُ الْبَادِيَةَ أَوْ أَهُمُّ بِهَا فَأَثْقُلُ عَنْهَا وَأُرِيدُ الْحَجَّ فَمَا أُدْرِكُهُ إِلا بَعْدَ كَدٍّ وَتَعَبٍ وَمَشَقَّةٍ عَلَى نَفْسِي فَاطْلُبْ غَيْرِي وَسَلْهُ ذَلِكَ وَلا تُعْلِمْهُمْ أَنَّكَ جِئْتَنِي فَقَالَ لَهُ النَّاسُ مَادُّونَ أَعْنَاقَهُمْ إِلَيْكَ وَإِنْ أَجَبْتَنِي لَمْ يَتَخَلَّفْ عَنِّي أَحَدٌ وَلَكَ أَنْ لا تُكَلَّفَ قِتَالاً وَلا مَكْرُوهاً قَالَ وَهَجَمَ عَلَيْنَا نَاسٌ فَدَخَلُوا وَقَطَعُوا كَلامَنَا فَقَالَ أَبِي جُعِلْتُ فِدَاكَ مَا تَقُولُ فَقَالَ نَلْتَقِي إِنْ شَاءَ الله فَقَالَ أَ لَيْسَ عَلَى مَا أُحِبُّ فَقَالَ عَلَى مَا تُحِبُّ إِنْ شَاءَ الله مِنْ إِصْلاحِكَ ثُمَّ انْصَرَفَ حَتَّى جَاءَ الْبَيْتَ فَبَعَثَ رَسُولاً إِلَى مُحَمَّدٍ فِي جَبَلٍ بِجُهَيْنَةَ يُقَالُ لَهُ الاشْقَرُ عَلَى لَيْلَتَيْنِ مِنَ الْمَدِينَةِ فَبَشَّرَهُ وَأَعْلَمَهُ أَنَّهُ قَدْ ظَفِرَ لَهُ بِوَجْهِ حَاجَتِهِ وَمَا طَلَبَ ثُمَّ عَادَ بَعْدَ ثَلاثَةِ أَيَّامٍ فَوُقِّفْنَا بِالْبَابِ وَلَمْ نَكُنْ نُحْجَبُ إِذَا جِئْنَا فَأَبْطَأَ الرَّسُولُ ثُمَّ أَذِنَ لَنَا فَدَخَلْنَا عَلَيْهِ فَجَلَسْتُ فِي نَاحِيَةِ الْحُجْرَةِ وَدَنَا أَبِي إِلَيْهِ فَقَبَّلَ رَأْسَهُ ثُمَّ قَالَ جُعِلْتُ فِدَاكَ قَدْ عُدْتُ إِلَيْكَ رَاجِياً مُؤَمِّلاً قَدِ انْبَسَطَ رَجَائِي وَأَمَلِي وَرَجَوْتُ الدَّرْكَ لِحَاجَتِي فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) يَا ابْنَ عَمِّ إِنِّي أُعِيذُكَ بِالله مِنَ التَّعَرُّضِ لِهَذَا الامْرِ الَّذِي أَمْسَيْتَ فِيهِ وَإِنِّي لَخَائِفٌ عَلَيْكَ أَنْ يُكْسِبَكَ شَرّاً فَجَرَى الْكَلامُ بَيْنَهُمَا حَتَّى أَفْضَى إِلَى مَا لَمْ يَكُنْ يُرِيدُ وَكَانَ مِنْ قَوْلِهِ بِأَيِّ شَيْ‏ءٍ كَانَ الْحُسَيْنُ أَحَقَّ بِهَا مِنْ الْحَسَنِ فَقَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) رَحِمَ الله الْحَسَنَ وَرَحِمَ الْحُسَيْنَ وَكَيْفَ ذَكَرْتَ هَذَا قَالَ لانَّ الْحُسَيْنَ (عَلَيْهِ السَّلام) كَانَ يَنْبَغِي لَهُ إِذَا عَدَلَ أَنْ يَجْعَلَهَا فِي الاسَنِّ مِنْ وُلْدِ الْحَسَنِ فَقَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) إِنَّ الله تَبَارَكَ وَتَعَالَى لَمَّا أَنْ أَوْحَى إِلَى مُحَمَّدٍ (صَلَّى اللهُ عَلَيْهِ وَآلِه) أَوْحَى إِلَيْهِ بِمَا شَاءَ وَلَمْ يُؤَامِرْ أَحَداً مِنْ خَلْقِهِ وَأَمَرَ مُحَمَّدٌ (صَلَّى اللهُ عَلَيْهِ وَآلِه) عَلِيّاً (عَلَيْهِ السَّلام) بِمَا شَاءَ فَفَعَلَ مَا أُمِرَ بِهِ وَلَسْنَا نَقُولُ فِيهِ إِلا مَا قَالَ رَسُولُ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) مِنْ تَبْجِيلِهِ وَتَصْدِيقِهِ فَلَوْ كَانَ أَمَرَ الْحُسَيْنَ أَنْ يُصَيِّرَهَا فِي الاسَنِّ أَوْ يَنْقُلَهَا فِي وُلْدِهِمَا يَعْنِي الْوَصِيَّةَ لَفَعَلَ ذَلِكَ الْحُسَيْنُ وَمَا هُوَ بِالْمُتَّهَمِ عِنْدَنَا فِي الذَّخِيرَةِ لِنَفْسِهِ وَلَقَدْ وَلَّى وَتَرَكَ ذَلِكَ وَلَكِنَّهُ مَضَى لِمَا أُمِرَ بِهِ وَهُوَ جَدُّكَ وَعَمُّكَ فَإِنْ قُلْتَ خَيْراً فَمَا أَوْلاكَ بِهِ وَإِنْ قُلْتَ هُجْراً فَيَغْفِرُ الله لَكَ أَطِعْنِي يَا ابْنَ. عَمِّ وَاسْمَعْ كَلامِي فَوَ الله الَّذِي لا إِلَهَ إِلا هُوَ لا آلُوكَ نُصْحاً وَحِرْصاً فَكَيْفَ وَلا أَرَاكَ تَفْعَلُ وَمَا لامْرِ الله مِنْ مَرَدٍّ فَسُرَّ أَبِي عِنْدَ ذَلِكَ فَقَالَ لَهُ أَبُو عَبْدِ الله وَالله إِنَّكَ لَتَعْلَمُ أَنَّهُ الاحْوَلُ الاكْشَفُ الاخْضَرُ الْمَقْتُولُ بِسُدَّةِ أَشْجَعَ عِنْدَ بَطْنِ مَسِيلِهَا فَقَالَ أَبِي لَيْسَ هُوَ ذَلِكَ وَالله لَيُحَارِبَنَّ بِالْيَوْمِ يَوْماً وَبِالسَّاعَةِ سَاعَةً وَبِالسَّنَةِ سَنَةً وَلَيَقُومَنَّ بِثَأْرِ بَنِي أَبِي طَالِبٍ جَمِيعاً فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) يَغْفِرُ الله لَكَ مَا أَخْوَفَنِي أَنْ يَكُونَ هَذَا الْبَيْتُ يَلْحَقُ صَاحِبَنَا مَنَّتْكَ نَفْسُكَ فِي الْخَلاءِ ضَلالاً لا وَالله لا يَمْلِكُ أَكْثَرَ مِنْ حِيطَانِ الْمَدِينَةِ وَلا يَبْلُغُ عَمَلُهُ الطَّائِفَ إِذَا أَحْفَلَ يَعْنِي إِذَا أَجْهَدَ نَفْسَهُ وَمَا لِلامْرِ مِنْ بُدٍّ أَنْ يَقَعَ فَاتَّقِ الله وَارْحَمْ نَفْسَكَ وَبَنِي أَبِيكَ فَوَ الله إِنِّي لارَاهُ أَشْأَمَ سَلْحَةٍ أَخْرَجَتْهَا أَصْلابُ الرِّجَالِ إِلَى أَرْحَامِ النِّسَاءِ وَالله إِنَّهُ الْمَقْتُولُ بِسُدَّةِ أَشْجَعَ بَيْنَ دُورِهَا وَالله لَكَأَنِّي بِهِ صَرِيعاً مَسْلُوباً بِزَّتُهُ بَيْنَ رِجْلَيْهِ لَبِنَةٌ وَلا يَنْفَعُ هَذَا الْغُلامَ مَا يَسْمَعُ قَالَ مُوسَى بْنُ عَبْدِ الله يَعْنِينِي وَلَيَخْرُجَنَّ مَعَهُ فَيُهْزَمُ وَيُقْتَلُ صَاحِبُهُ ثُمَّ يَمْضِي فَيَخْرُجُ مَعَهُ رَايَةٌ أُخْرَى فَيُقْتَلُ كَبْشُهَا وَيَتَفَرَّقُ جَيْشُهَا فَإِنْ أَطَاعَنِي فَلْيَطْلُبِ الامَانَ عِنْدَ ذَلِكَ مِنْ بَنِي الْعَبَّاسِ حَتَّى يَأْتِيَهُ الله بِالْفَرَجِ وَلَقَدْ عَلِمْتَ بِأَنَّ هَذَا الامْرَ لا يَتِمُّ وَإِنَّكَ لَتَعْلَمُ وَنَعْلَمُ أَنَّ ابْنَكَ الاحْوَلُ الاخْضَرُ الاكْشَفُ الْمَقْتُولُ بِسُدَّةِ أَشْجَعَ بَيْنَ دُورِهَا عِنْدَ بَطْنِ مَسِيلِهَا فَقَامَ أَبِي وَهُوَ يَقُولُ بَلْ يُغْنِي الله عَنْكَ وَلَتَعُودَنَّ أَوْ لَيَقِي الله بِكَ وَبِغَيْرِكَ وَمَا أَرَدْتَ بِهَذَا إِلا امْتِنَاعَ غَيْرِكَ وَأَنْ تَكُونَ ذَرِيعَتَهُمْ إِلَى ذَلِكَ فَقَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) الله يَعْلَمُ مَا أُرِيدُ إِلا نُصْحَكَ وَرُشْدَكَ وَمَا عَلَيَّ إِلا الْجُهْدُ فَقَامَ أَبِي يَجُرُّ ثَوْبَهُ مُغْضَباً فَلَحِقَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) فَقَالَ لَهُ أُخْبِرُكَ أَنِّي سَمِعْتُ عَمَّكَ وَهُوَ خَالُكَ يَذْكُرُ أَنَّكَ وَبَنِي. أَبِيكَ سَتُقْتَلُونَ فَإِنْ أَطَعْتَنِي وَرَأَيْتَ أَنْ تَدْفَعَ بِالَّتِي هِيَ أَحْسَنُ فَافْعَلْ فَوَ الله الَّذِي لا إِلَهَ إِلا هُوَ عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الرَّحْمَنُ الرَّحِيمُ الْكَبِيرُ الْمُتَعَالِ عَلَى خَلْقِهِ لَوَدِدْتُ أَنِّي فَدَيْتُكَ بِوُلْدِي وَبِأَحَبِّهِمْ إِلَيَّ وَبِأَحَبِّ أَهْلِ بَيْتِي إِلَيَّ وَمَا يَعْدِلُكَ عِنْدِي شَيْ‏ءٌ فَلا تَرَى أَنِّي غَشَشْتُكَ فَخَرَجَ أَبِي مِنْ عِنْدِهِ مُغْضَباً أَسِفاً قَالَ فَمَا أَقَمْنَا بَعْدَ ذَلِكَ إِلا قَلِيلاً عِشْرِينَ لَيْلَةً أَوْ نَحْوَهَا حَتَّى قَدِمَتْ رُسُلُ أَبِي جَعْفَرٍ فَأَخَذُوا أَبِي وَعُمُومَتِي سُلَيْمَانَ بْنَ حَسَنٍ وَحَسَنَ بْنَ حَسَنٍ وَإِبْرَاهِيمَ بْنَ حَسَنٍ وَدَاوُدَ بْنَ حَسَنٍ وَعَلِيَّ بْنَ حَسَنٍ وَسُلَيْمَانَ بْنَ دَاوُدَ بْنِ حَسَنٍ وَعَلِيَّ بْنَ إِبْرَاهِيمَ بْنِ حَسَنٍ وَحَسَنَ بْنَ جَعْفَرِ بْنِ حَسَنٍ وَطَبَاطَبَا إِبْرَاهِيمَ بْنَ إِسْمَاعِيلَ بْنِ حَسَنٍ وَعَبْدَ الله بْنَ دَاوُدَ قَالَ فَصُفِّدُوا فِي الْحَدِيدِ ثُمَّ حُمِلُوا فِي مَحَامِلَ أَعْرَاءً لا وِطَاءَ فِيهَا وَوُقِّفُوا بِالْمُصَلَّى لِكَيْ يُشْمِتَهُمُ النَّاسُ قَالَ فَكَفَّ النَّاسُ عَنْهُمْ وَرَقُّوا لَهُمْ لِلْحَالِ الَّتِي هُمْ فِيهَا ثُمَّ انْطَلَقُوا بِهِمْ حَتَّى وُقِّفُوا عِنْدَ بَابِ مَسْجِدِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) قَالَ عَبْدُ الله بْنُ إِبْرَاهِيمَ الْجَعْفَرِيُّ فَحَدَّثَتْنَا خَدِيجَةُ بِنْتُ عُمَرَ بْنِ عَلِيٍّ أَنَّهُمْ لَمَّا أُوقِفُوا عِنْدَ بَابِ الْمَسْجِدِ الْبَابِ الَّذِي يُقَالُ لَهُ بَابُ جَبْرَئِيلَ اطَّلَعَ عَلَيْهِمْ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) وَعَامَّةُ رِدَائِهِ مَطْرُوحٌ بِالارْضِ ثُمَّ اطَّلَعَ مِنْ بَابِ الْمَسْجِدِ فَقَالَ لَعَنَكُمُ الله يَا مَعَاشِرَ الانْصَارِ ثَلاثاً مَا عَلَى هَذَا عَاهَدْتُمْ رَسُولَ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَلا بَايَعْتُمُوهُ أَمَا وَالله إِنْ كُنْتُ حَرِيصاً وَلَكِنِّي غُلِبْتُ وَلَيْسَ لِلْقَضَاءِ مَدْفَعٌ ثُمَّ قَامَ وَأَخَذَ إِحْدَى نَعْلَيْهِ فَأَدْخَلَهَا رِجْلَهُ وَالاخْرَى فِي يَدِهِ وَعَامَّةُ رِدَائِهِ يَجُرُّهُ فِي الارْضِ ثُمَّ دَخَلَ بَيْتَهُ فَحُمَّ عِشْرِينَ لَيْلَةً لَمْ يَزَلْ يَبْكِي فِيهِ اللَّيْلَ وَالنَّهَارَ حَتَّى خِفْنَا عَلَيْهِ فَهَذَا حَدِيثُ خَدِيجَةَ قَالَ الْجَعْفَرِيُّ وَحَدَّثَنَا مُوسَى بْنُ عَبْدِ الله بْنِ الْحَسَنِ أَنَّهُ لَمَّا طُلِعَ بِالْقَوْمِ فِي الْمَحَامِلِ قَامَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) مِنَ الْمَسْجِدِ ثُمَّ أَهْوَى إِلَى الْمَحْمِلِ الَّذِي فِيهِ عَبْدُ الله بْنُ الْحَسَنِ يُرِيدُ كَلامَهُ فَمُنِعَ أَشَدَّ الْمَنْعِ وَأَهْوَى إِلَيْهِ الْحَرَسِيُّ فَدَفَعَهُ وَقَالَ تَنَحَّ عَنْ هَذَا فَإِنَّ الله سَيَكْفِيكَ وَيَكْفِي غَيْرَكَ ثُمَّ دَخَلَ بِهِمُ الزُّقَاقَ وَرَجَعَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) إِلَى مَنْزِلِهِ فَلَمْ يَبْلُغْ بِهِمُ الْبَقِيعَ حَتَّى ابْتُلِيَ الْحَرَسِيُّ بَلاءً شَدِيداً رَمَحَتْهُ نَاقَتُهُ فَدَقَّتْ وَرِكَهُ فَمَاتَ فِيهَا وَمَضَى بِالْقَوْمِ فَأَقَمْنَا بَعْدَ ذَلِكَ حِيناً ثُمَّ أَتَى مُحَمَّدُ بْنُ عَبْدِ الله بْنِ حَسَنٍ فَأُخْبِرَ أَنَّ أَبَاهُ وَعُمُومَتَهُ قُتِلُوا قَتَلَهُمْ أَبُو جَعْفَرٍ إِلا حَسَنَ. بْنَ جَعْفَرٍ وَطَبَاطَبَا وَعَلِيَّ بْنَ إِبْرَاهِيمَ وَسُلَيْمَانَ بْنَ دَاوُدَ وَدَاوُدَ بْنَ حَسَنٍ وَعَبْدَ الله بْنَ دَاوُدَ قَالَ فَظَهَرَ مُحَمَّدُ بْنُ عَبْدِ الله عِنْدَ ذَلِكَ وَدَعَا النَّاسَ لِبَيْعَتِهِ قَالَ فَكُنْتُ ثَالِثَ ثَلاثَةٍ بَايَعُوهُ وَاسْتَوْسَقَ النَّاسَ لِبَيْعَتِهِ وَلَمْ يَخْتَلِفْ عَلَيْهِ قُرَشِيٌّ وَلا أَنْصَارِيٌّ وَلا عَرَبِيٌّ قَالَ وَشَاوَرَ عِيسَى بْنَ زَيْدٍ وَكَانَ مِنْ ثِقَاتِهِ وَكَانَ عَلَى شُرَطِهِ فَشَاوَرَهُ فِي الْبِعْثَةِ إِلَى وُجُوهِ قَوْمِهِ فَقَالَ لَهُ عِيسَى بْنُ زَيْدٍ إِنْ دَعَوْتَهُمْ دُعَاءً يَسِيراً لَمْ يُجِيبُوكَ أَوْ تَغْلُظَ عَلَيْهِمْ فَخَلِّنِي وَإِيَّاهُمْ فَقَالَ لَهُ مُحَمَّدٌ امْضِ إِلَى مَنْ أَرَدْتَ مِنْهُمْ فَقَالَ ابْعَثْ إِلَى رَئِيسِهِمْ وَكَبِيرِهِمْ يَعْنِي أَبَا عَبْدِ الله جَعْفَرَ بْنَ مُحَمَّدٍ (عَلَيْهما السَّلام) فَإِنَّكَ إِذَا أَغْلَظْتَ عَلَيْهِ عَلِمُوا جَمِيعاً أَنَّكَ سَتُمِرُّهُمْ عَلَى الطَّرِيقِ الَّتِي أَمْرَرْتَ عَلَيْهَا أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ فَوَ الله مَا لَبِثْنَا أَنْ أُتِيَ بِأَبِي عَبْدِ الله (عَلَيْهِ السَّلام) حَتَّى أُوقِفَ بَيْنَ يَدَيْهِ فَقَالَ لَهُ عِيسَى بْنُ زَيْدٍ أَسْلِمْ تَسْلَمْ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) أَ حَدَثَتْ نُبُوَّةٌ بَعْدَ مُحَمَّدٍ (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَقَالَ لَهُ مُحَمَّدٌ لا وَلَكِنْ بَايِعْ تَأْمَنْ عَلَى نَفْسِكَ وَمَالِكَ وَوُلْدِكَ وَلا تُكَلَّفَنَّ حَرْباً فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) مَا فِيَّ حَرْبٌ وَلا قِتَالٌ وَلَقَدْ تَقَدَّمْتُ إِلَى أَبِيكَ وَحَذَّرْتُهُ الَّذِي حَاقَ بِهِ وَلَكِنْ لا يَنْفَعُ حَذَرٌ مِنْ قَدَرٍ يَا ابْنَ أَخِي عَلَيْكَ بِالشَّبَابِ وَدَعْ عَنْكَ الشُّيُوخَ فَقَالَ لَهُ مُحَمَّدٌ مَإ؛ججّّ أَقْرَبَ مَا بَيْنِي وَبَيْنَكَ فِي السِّنِّ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) إِنِّي لَمْ أُعَازَّكَ وَلَمْ أَجِئْ لاتَقَدَّمَ عَلَيْكَ فِي الَّذِي أَنْتَ فِيهِ فَقَالَ لَهُ مُحَمَّدٌ لا وَالله لا بُدَّ مِنْ أَنْ تُبَايِعَ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) مَا فِيَّ يَا ابْنَ أَخِي طَلَبٌ وَلا حَرْبٌ وَإِنِّي لارِيدُ الْخُرُوجَ إِلَى الْبَادِيَةِ فَيَصُدُّنِي ذَلِكَ وَيَثْقُلُ عَلَيَّ حَتَّى تُكَلِّمَنِي فِي ذَلِكَ الاهْلُ غَيْرَ مَرَّةٍ وَلا يَمْنَعُنِي مِنْهُ إِلا الضَّعْفُ وَالله وَالرَّحِمِ أَنْ تُدْبِرَ عَنَّا وَنَشْقَى بِكَ فَقَالَ لَهُ يَا أَبَا عَبْدِ الله قَدْ وَالله مَاتَ أَبُو الدَّوَانِيقِ يَعْنِي أَبَا جَعْفَرٍ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) وَمَا تَصْنَعُ بِي وَقَدْ مَاتَ قَالَ أُرِيدُ الْجَمَالَ بِكَ قَالَ مَا إِلَى مَا تُرِيدُ سَبِيلٌ لا وَالله مَا مَاتَ أَبُو الدَّوَانِيقِ إِلا أَنْ يَكُونَ مَاتَ مَوْتَ النَّوْمِ قَالَ وَالله لَتُبَايِعُنِي طَائِعاً أَوْ مُكْرَهاً وَلا تُحْمَدُ فِي بَيْعَتِكَ فَأَبَى عَلَيْهِ إِبَاءً شَدِيداً وَأَمَرَ بِهِ إِلَى الْحَبْسِ فَقَالَ لَهُ عِيسَى بْنُ زَيْدٍ أَمَا إِنْ طَرَحْنَاهُ فِي السِّجْنِ وَقَدْ خَرِبَ السِّجْنُ وَلَيْسَ عَلَيْهِ الْيَوْمَ غَلَقٌ خِفْنَا أَنْ يَهْرُبَ مِنْهُ فَضَحِكَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) ثُمَّ قَالَ لا حَوْلَ وَلا قُوَّةَ إِلا بِالله الْعَلِيِّ الْعَظِيمِ أَ وَتُرَاكَ تُسْجِنُنِي قَالَ نَعَمْ وَالَّذِي أَكْرَمَ مُحَمَّداً (صَلَّى اللهُ عَلَيْهِ وَآلِه) بِالنُّبُوَّةِ لاسْجِنَنَّكَ وَلاشَدِّدَنَّ عَلَيْكَ فَقَالَ عِيسَى بْنُ زَيْدٍ احْبِسُوهُ فِي الْمَخْبَإِ وَذَلِكَ دَارُ رَيْطَةَ الْيَوْمَ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) أَمَا وَالله إِنِّي سَأَقُولُ ثُمَّ أُصَدَّقُ فَقَالَ لَهُ عِيسَى بْنُ زَيْدٍ لَوْ تَكَلَّمْتَ لَكَسَرْتُ فَمَكَ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) أَمَا وَالله يَا أَكْشَفُ يَا أَزْرَقُ لَكَأَنِّي بِكَ تَطْلُبُ لِنَفْسِكَ جُحْراً تَدْخُلُ فِيهِ وَمَا أَنْتَ فِي الْمَذْكُورِينَ عِنْدَ اللِّقَاءِ وَإِنِّي لاظُنُّكَ إِذَا صُفِّقَ خَلْفَكَ طِرْتَ مِثْلَ الْهَيْقِ النَّافِرِ فَنَفَرَ عَلَيْهِ مُحَمَّدٌ بِانْتِهَارٍ احْبِسْهُ وَشَدِّدْ عَلَيْهِ وَاغْلُظْ عَلَيْهِ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) أَمَا وَالله لَكَأَنِّي بِكَ خَارِجاً مِنْ سُدَّةِ أَشْجَعَ إِلَى بَطْنِ الْوَادِي وَقَدْ حَمَلَ عَلَيْكَ فَارِسٌ مُعْلَمٌ فِي يَدِهِ طِرَادَةٌ نِصْفُهَا أَبْيَضُ وَنِصْفُهَا أَسْوَدُ عَلَى فَرَسٍ كُمَيْتٍ أَقْرَحَ فَطَعَنَكَ فَلَمْ يَصْنَعْ فِيكَ شَيْئاً وَضَرَبْتَ خَيْشُومَ فَرَسِهِ فَطَرَحْتَهُ وَحَمَلَ عَلَيْكَ آخَرُ خَارِجٌ مِنْ زُقَاقِ آلِ أَبِي عَمَّارٍ الدُّؤَلِيِّينَ عَلَيْهِ غَدِيرَتَانِ مَضْفُورَتَانِ وَقَدْ خَرَجَتَا مِنْ تَحْتِ بَيْضَةٍ كَثِيرُ شَعْرِ الشَّارِبَيْنِ فَهُوَ وَالله صَاحِبُكَ فَلا رَحِمَ الله رِمَّتَهُ فَقَالَ لَهُ مُحَمَّدٌ يَا أَبَا عَبْدِ الله حَسِبْتَ فَأَخْطَأْتَ وَقَامَ إِلَيْهِ السُّرَاقِيُّ بْنُ سَلْخِ الْحُوتِ فَدَفَعَ فِي ظَهْرِهِ حَتَّى أُدْخِلَ السِّجْنَ وَاصْطُفِيَ مَا كَانَ لَهُ مِنْ مَالٍ وَمَا كَانَ لِقَوْمِهِ مِمَّنْ لَمْ يَخْرُجْ مَعَ مُحَمَّدٍ قَالَ فَطُلِعَ بِإِسْمَاعِيلَ بْنِ عَبْدِ الله بْنِ جَعْفَرِ بْنِ أَبِي طَالِبٍ وَهُوَ شَيْخٌ كَبِيرٌ ضَعِيفٌ قَدْ ذَهَبَتْ إِحْدَى عَيْنَيْهِ وَذَهَبَتْ رِجْلاهُ وَهُوَ. يُحْمَلُ حَمْلاً فَدَعَاهُ إِلَى الْبَيْعَةِ فَقَالَ لَهُ يَا ابْنَ أَخِي إِنِّي شَيْخٌ كَبِيرٌ ضَعِيفٌ وَأَنَا إِلَى بِرِّكَ وَعَوْنِكَ أَحْوَجُ فَقَالَ لَهُ لا بُدَّ مِنْ أَنْ تُبَايِعَ فَقَالَ لَهُ وَأَيَّ شَيْ‏ءٍ تَنْتَفِعُ بِبَيْعَتِي وَالله إِنِّي لاضَيِّقُ عَلَيْكَ مَكَانَ اسْمِ رَجُلٍ إِنْ كَتَبْتَهُ قَالَ لا بُدَّ لَكَ أَنْ تَفْعَلَ وَأَغْلَظَ لَهُ فِي الْقَوْلِ فَقَالَ لَهُ إِسْمَاعِيلُ ادْعُ لِي جَعْفَرَ بْنَ مُحَمَّدٍ فَلَعَلَّنَا نُبَايِعُ جَمِيعاً قَالَ فَدَعَا جَعْفَراً (عَلَيْهِ السَّلام) فَقَالَ لَهُ إِسْمَاعِيلُ جُعِلْتُ فِدَاكَ إِنْ رَأَيْتَ أَنْ تُبَيِّنَ لَهُ فَافْعَلْ لَعَلَّ الله يَكُفُّهُ عَنَّا قَالَ قَدْ أَجْمَعْتُ أَلا أُكَلِّمَهُ أَ فَلْيَرَ فِيَّ بِرَأْيِهِ فَقَالَ إِسْمَاعِيلُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) أَنْشُدُكَ الله هَلْ تَذْكُرُ يَوْماً أَتَيْتُ أَبَاكَ مُحَمَّدَ بن علي (عَلَيْهما السَّلام) وَعَلَيَّ حُلَّتَانِ صَفْرَاوَانِ فَدَامَ النَّظَرَ إِلَيَّ فَبَكَى فَقُلْتُ لَهُ مَا يُبْكِيكَ فَقَالَ لِي يُبْكِينِي أَنَّكَ تُقْتَلُ عِنْدَ كِبَرِ سِنِّكَ ضَيَاعاً لا يَنْتَطِحُ فِي دَمِكَ عَنْزَانِ قَالَ قُلْتُ فَمَتَى ذَاكَ قَالَ إِذَا دُعِيتَ إِلَى الْبَاطِلِ فَأَبَيْتَهُ وَإِذَا نَظَرْتَ إِلَى الاحْوَلِ مَشُومِ قَوْمِهِ يَنْتَمِي مِنْ آلِ الْحَسَنِ عَلَى مِنْبَرِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) يَدْعُو إِلَى نَفْسِهِ قَدْ تَسَمَّى بِغَيْرِ اسْمِهِ فَأَحْدِثْ عَهْدَكَ وَاكْتُبْ وَصِيَّتَكَ فَإِنَّكَ مَقْتُولٌ فِي يَوْمِكَ أَوْ مِنْ غَدٍ فَقَالَ لَهُ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) نَعَمْ وَهَذَا وَرَبِّ الْكَعْبَةِ لا يَصُومُ مِنْ شَهْرِ رَمَضَانَ إِلا أَقَلَّهُ فَأَسْتَوْدِعُكَ الله يَا أَبَا الْحَسَنِ وَأَعْظَمَ الله أَجْرَنَا فِيكَ وَأَحْسَنَ الْخِلافَةَ عَلَى مَنْ خَلَّفْتَ وَإِنَّا لله وَإِنَّا إِلَيْهِ رَاجِعُونَ قَالَ ثُمَّ احْتُمِلَ إِسْمَاعِيلُ وَرُدَّ جَعْفَرٌ إِلَى الْحَبْسِ قَالَ فَوَ الله مَا أَمْسَيْنَا حَتَّى دَخَلَ عَلَيْهِ بَنُو أَخِيهِ بَنُو مُعَاوِيَةَ بْنِ عَبْدِ الله بْنِ جَعْفَرٍ فَتَوَطَّئُوهُ حَتَّى قَتَلُوهُ وَبَعَثَ مُحَمَّدُ بْنُ عَبْدِ الله إِلَى جَعْفَرٍ فَخَلَّى سَبِيلَهُ قَالَ وَأَقَمْنَا بَعْدَ ذَلِكَ حَتَّى اسْتَهْلَلْنَا شَهْرَ رَمَضَانَ فَبَلَغَنَا خُرُوجُ عِيسَى بْنِ مُوسَى يُرِيدُ الْمَدِينَةَ قَالَ فَتَقَدَّمَ مُحَمَّدُ بْنُ عَبْدِ الله عَلَى مُقَدِّمَتِهِ يَزِيدُ بْنُ مُعَاوِيَةَ بْنِ عَبْدِ الله بْنِ جَعْفَرٍ وَكَانَ عَلَى مُقَدِّمَةِ عِيسَى بْنِ مُوسَى وُلْدُ الْحَسَنِ بْنِ زَيْدِ بْنِ الْحَسَنِ بْنِ الْحَسَنِ وَقَاسِمٌ وَمُحَمَّدُ بْنُ زَيْدٍ وَعَلِيٌّ وَإِبْرَاهِيمُ بَنُو الْحَسَنِ بْنِ زَيْدٍ فَهُزِمَ يَزِيدُ بْنُ مُعَاوِيَةَ وَقَدِمَ عِيسَى بْنُ مُوسَى الْمَدِينَةَ وَصَارَ الْقِتَالُ بِالْمَدِينَةِ فَنَزَلَ بِذُبَابٍ وَدَخَلَتْ عَلَيْنَا الْمُسَوِّدَةُ مِنْ خَلْفِنَا وَخَرَجَ مُحَمَّدٌ فِي أَصْحَابِهِ حَتَّى بَلَغَ السُّوقَ. فَأَوْصَلَهُمْ وَمَضَى ثُمَّ تَبِعَهُمْ حَتَّى انْتَهَى إِلَى مَسْجِدِ الْخَوَّامِينَ فَنَظَرَ إِلَى مَا هُنَاكَ فَضَاءٍ لَيْسَ فِيهِ مُسَوِّدٌ وَلا مُبَيِّضٌ فَاسْتَقْدَمَ حَتَّى انْتَهَى إِلَى شِعْبِ فَزَارَةَ ثُمَّ دَخَلَ هُذَيْلَ ثُمَّ مَضَى إِلَى أَشْجَعَ فَخَرَجَ إِلَيْهِ الْفَارِسُ الَّذِي قَالَ أَبُو عَبْدِ الله مِنْ خَلْفِهِ مِنْ سِكَّةِ هُذَيْلَ فَطَعَنَهُ فَلَمْ يَصْنَعْ فِيهِ شَيْئاً وَحَمَلَ عَلَى الْفَارِسِ فَضَرَبَ خَيْشُومَ فَرَسِهِ بِالسَّيْفِ فَطَعَنَهُ الْفَارِسُ فَأَنْفَذَهُ فِي الدِّرْعِ وَانْثَنَى عَلَيْهِ مُحَمَّدٌ فَضَرَبَهُ فَأَثْخَنَهُ وَخَرَجَ عَلَيْهِ حُمَيْدُ بْنُ قَحْطَبَةَ وَهُوَ مُدْبِرٌ عَلَى الْفَارِسِ يَضْرِبُهُ مِنْ زُقَاقِ الْعَمَّارِيِّينَ فَطَعَنَهُ طَعْنَةً أَنْفَذَ السِّنَانَ فِيهِ فَكُسِرَ الرُّمْحُ وَحَمَلَ عَلَى حُمَيْدٍ فَطَعَنَهُ حُمَيْدٌ بِزُجِّ الرُّمْحِ فَصَرَعَهُ ثُمَّ نَزَلَ إِلَيْهِ فَضَرَبَهُ حَتَّى أَثْخَنَهُ وَقَتَلَهُ وَأَخَذَ رَأْسَهُ وَدَخَلَ الْجُنْدُ مِنْ كُلِّ جَانِبٍ وَأُخِذَتِ الْمَدِينَةُ وَأُجْلِينَا هَرَباً فِي الْبِلادِ قَالَ مُوسَى بْنُ عَبْدِ الله فَانْطَلَقْتُ حَتَّى لَحِقْتُ بِإِبْرَاهِيمَ بْنِ عَبْدِ الله فَوَجَدْتُ عِيسَى بْنَ زَيْدٍ مُكْمَناً عِنْدَهُ فَأَخْبَرْتُهُ بِسُوءِ تَدْبِيرِهِ وَخَرَجْنَا مَعَهُ حَتَّى أُصِيبَ رَحِمَهُ الله ثُمَّ مَضَيْتُ مَعَ ابْنِ أَخِي الاشْتَرِ عَبْدِ الله بْنِ مُحَمَّدِ بْنِ عَبْدِ الله بْنِ حَسَنٍ حَتَّى أُصِيبَ بِالسِّنْدِ ثُمَّ رَجَعْتُ شَرِيداً طَرِيداً تُضَيَّقُ عَلَيَّ الْبِلادُ فَلَمَّا ضَاقَتْ عَلَيَّ الارْضُ وَاشْتَدَّ بِيَ الْخَوْفُ ذَكَرْتُ مَا قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) فَجِئْتُ إِلَى الْمَهْدِيِّ وَقَدْ حَجَّ وَهُوَ يَخْطُبُ النَّاسَ فِي ظِلِّ الْكَعْبَةِ فَمَا شَعَرَ إِلا وَأَنِّي قَدْ قُمْتُ مِنْ تَحْتِ الْمِنْبَرِ فَقُلْتُ لِيَ الامَانُ يَا أَمِيرَ الْمُؤْمِنِينَ وَأَدُلُّكَ عَلَى نَصِيحَةٍ لَكَ عِنْدِي فَقَالَ نَعَمْ مَا هِيَ قُلْتُ أَدُلُّكَ عَلَى مُوسَى بْنِ عَبْدِ الله بْنِ حَسَنٍ فَقَالَ لِي نَعَمْ لَكَ الامَانُ فَقُلْتُ لَهُ أَعْطِنِي مَا أَثِقُ بِهِ فَأَخَذْتُ مِنْهُ عُهُوداً وَمَوَاثِيقَ وَوَثَّقْتُ لِنَفْسِي ثُمَّ قُلْتُ أَنَا مُوسَى بْنُ عَبْدِ الله فَقَالَ لِي إِذاً تُكْرَمَ وَتُحْبَى فَقُلْتُ لَهُ أَقْطِعْنِي إِلَى بَعْضِ أَهْلِ بَيْتِكَ يَقُومُ بِأَمْرِي عِنْدَكَ فَقَالَ لِيَ انْظُرْ إِلَى مَنْ أَرَدْتَ فَقُلْتُ عَمَّكَ الْعَبَّاسَ بْنَ مُحَمَّدٍ فَقَالَ الْعَبَّاسُ لا حَاجَةَ لِي فِيكَ فَقُلْتُ وَلَكِنْ لِي فِيكَ الْحَاجَةُ أَسْأَلُكَ بِحَقِّ أَمِيرِ الْمُؤْمِنِينَ إِلا قَبِلْتَنِي فَقَبِلَنِي شَاءَ أَوْ أَبَى وَقَالَ لِيَ الْمَهْدِيُّ مَنْ يَعْرِفُكَ وَحَوْلَهُ أَصْحَابُنَا أَوْ أَكْثَرُهُمْ فَقُلْتُ هَذَا الْحَسَنُ بْنُ زَيْدٍ يَعْرِفُنِي وَهَذَا مُوسَى بْنُ جَعْفَرٍ يَعْرِفُنِي وَهَذَا الْحَسَنُ بْنُ عَبْدِ الله بْنِ الْعَبَّاسِ يَعْرِفُنِي فَقَالُوا نَعَمْ يَا أَمِيرَ الْمُؤْمِنِينَ كَأَنَّهُ لَمْ يَغِبْ عَنَّا ثُمَّ قُلْتُ لِلْمَهْدِيِّ يَا أَمِيرَ الْمُؤْمِنِينَ لَقَدْ أَخْبَرَنِي بِهَذَا الْمَقَامِ أَبُو هَذَا الرَّجُلِ وَأَشَرْتُ إِلَى مُوسَى بْنِ جَعْفَرٍ قَالَ مُوسَى بْنُ عَبْدِ الله وَكَذَبْتُ عَلَى جَعْفَرٍ كَذِبَةً فَقُلْتُ لَهُ وَأَمَرَنِي أَنْ أُقْرِئَكَ السَّلامَ وَقَالَ إِنَّهُ إِمَامُ عَدْلٍ وَسَخَاءٍ قَالَ فَأَمَرَ لِمُوسَى بْنِ جَعْفَرٍ بِخَمْسَةِ آلافِ دِينَارٍ فَأَمَرَ لِي مِنْهَا مُوسَى بِأَلْفَيْ دِينَارٍ وَوَصَلَ عَامَّةَ أَصْحَابِهِ وَوَصَلَنِي فَأَحْسَنَ صِلَتِي فَحَيْثُ مَا ذُكِرَ وُلْدُ مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ فَقُولُوا صَلَّى الله عَلَيْهِمْ وَمَلائِكَتُهُ وَحَمَلَةُ عَرْشِهِ وَالْكِرَامُ الْكَاتِبُونَ وَخُصُّوا أَبَا عَبْدِ الله بِأَطْيَبِ ذَلِكَ وَجَزَى مُوسَى بْنَ جَعْفَرٍ عَنِّي خَيْراً فَأَنَا وَالله مَوْلاهُمْ بَعْدَ الله.","1/4/81/17","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[18,7,"وَبِهَذَا الاسْنَادِ عَنْ عَبْدِ الله بْنِ جَعْفَرِ بْنِ إِبْرَاهِيمَ الْجَعْفَرِيِّ قَالَ حَدَّثَنَا عَبْدُ الله بْنُ الْمُفَضَّلِ مَوْلَى عَبْدِ الله بْنِ جَعْفَرِ بْنِ أَبِي طَالِبٍ قَالَ لَمَّا خَرَجَ الْحُسَيْنُ بْنُ عَلِيٍّ الْمَقْتُولُ بِفَخٍّ وَاحْتَوَى عَلَى الْمَدِينَةِ دَعَا مُوسَى بْنَ جَعْفَرٍ إِلَى الْبَيْعَةِ فَأَتَاهُ فَقَالَ لَهُ يَا ابْنَ عَمِّ لا تُكَلِّفْنِي مَا كَلَّفَ ابْنُ عَمِّكَ عَمَّكَ أَبَا عَبْدِ الله فَيَخْرُجَ مِنِّي مَا لا أُرِيدُ كَمَا خَرَجَ مِنْ أَبِي عَبْدِ الله مَا لَمْ يَكُنْ يُرِيدُ فَقَالَ لَهُ الْحُسَيْنُ إِنَّمَا عَرَضْتُ عَلَيْكَ أَمْراً فَإِنْ أَرَدْتَهُ دَخَلْتَ فِيهِ وَإِنْ كَرِهْتَهُ لَمْ أَحْمِلْكَ عَلَيْهِ وَالله الْمُسْتَعَانُ ثُمَّ وَدَّعَهُ فَقَالَ لَهُ أَبُو الْحَسَنِ مُوسَى بْنُ جَعْفَرٍ حِينَ وَدَّعَهُ يَا ابْنَ عَمِّ إِنَّكَ مَقْتُولٌ فَأَجِدَّ الضِّرَابَ فَإِنَّ الْقَوْمَ فُسَّاقٌ يُظْهِرُونَ إِيمَاناً وَيَسْتُرُونَ شِرْكاً وَإِنَّا لله وَإِنَّا إِلَيْهِ رَاجِعُونَ أَحْتَسِبُكُمْ عِنْدَ الله مِنْ عُصْبَةٍ ثُمَّ خَرَجَ الْحُسَيْنُ وَكَانَ مِنْ أَمْرِهِ مَا كَانَ قُتِلُوا كُلُّهُمْ كَمَا قَالَ (عَلَيْهِ السَّلام )","1/4/81/18","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[19,7,"وَبِهَذَا الاسْنَادِ عَنْ عَبْدِ الله بْنِ إِبْرَاهِيمَ الْجَعْفَرِيِّ قَالَ كَتَبَ يَحْيَى بْنُ عَبْدِ الله بْنِ الْحَسَنِ إِلَى مُوسَى بْنِ جَعْفَرٍ (عَلَيْهما السَّلام) أَمَّا بَعْدُ فَإِنِّي أُوصِي نَفْسِي بِتَقْوَى الله وَبِهَا أُوصِيكَ فَإِنَّهَا وَصِيَّةُ الله فِي الاوَّلِينَ وَوَصِيَّتُهُ فِي الاخِرِينَ خَبَّرَنِي مَنْ وَرَدَ عَلَيَّ مِنْ أَعْوَانِ الله عَلَى دِينِهِ وَنَشْرِ طَاعَتِهِ بِمَا كَانَ مِنْ تَحَنُّنِكَ مَعَ خِذْلانِكَ وَقَدْ شَاوَرْتُ فِي الدَّعْوَةِ لِلرِّضَا مِنْ آلِ مُحَمَّدٍ (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَقَدِ احْتَجَبْتَهَا وَاحْتَجَبَهَا أَبُوكَ مِنْ قَبْلِكَ وَقَدِيماً ادَّعَيْتُمْ مَا لَيْسَ لَكُمْ وَبَسَطْتُمْ آمَالَكُمْ إِلَى مَا لَمْ يُعْطِكُمُ الله فَاسْتَهْوَيْتُمْ وَأَضْلَلْتُمْ وَأَنَا مُحَذِّرُكَ مَا حَذَّرَكَ الله مِنْ نَفْسِهِ فَكَتَبَ إِلَيْهِ أَبُو الْحَسَنِ مُوسَى بْنُ جَعْفَرٍ (عَلَيْهِ السَّلام) مِنْ مُوسَى بْنِ أَبِي عَبْدِ الله جَعْفَرٍ وَعَلِيٍّ مُشْتَرِكَيْنِ فِي التَّذَلُّلِ لله وَطَاعَتِهِ إِلَى يَحْيَى بْنِ عَبْدِ الله بْنِ حَسَنٍ أَمَّا بَعْدُ فَإِنِّي أُحَذِّرُكَ الله وَنَفْسِي وَأُعْلِمُكَ أَلِيمَ عَذَابِهِ وَشَدِيدَ عِقَابِهِ وَتَكَامُلَ نَقِمَاتِهِ وَأُوصِيكَ وَنَفْسِي بِتَقْوَى الله فَإِنَّهَا زَيْنُ الْكَلامِ وَتَثْبِيتُ النِّعَمِ أَتَانِي كِتَابُكَ تَذْكُرُ فِيهِ أَنِّي مُدَّعٍ وَأَبِي مِنْ قَبْلُ وَمَا سَمِعْتَ ذَلِكَ مِنِّي وَسَتُكْتَبُ شَهَادَتُهُمْ وَيُسْأَلُونَ وَلَمْ يَدَعْ حِرْصُ الدُّنْيَا وَمَطَالِبُهَا لاهْلِهَا مَطْلَباً لآِخِرَتِهِمْ حَتَّى يُفْسِدَ عَلَيْهِمْ مَطْلَبَ آخِرَتِهِمْ فِي دُنْيَاهُمْ وَذَكَرْتَ أَنِّي ثَبَّطْتُ النَّاسَ عَنْكَ لِرَغْبَتِي فِيمَا فِي يَدَيْكَ وَمَا مَنَعَنِي مِنْ مَدْخَلِكَ الَّذِي أَنْتَ فِيهِ لَوْ كُنْتُ رَاغِباً ضَعْفٌ عَنْ سُنَّةٍ وَلا قِلَّةُ بَصِيرَةٍ بِحُجَّةٍ وَلَكِنَّ الله تَبَارَكَ وَتَعَالَى خَلَقَ النَّاسَ أَمْشَاجاً وَغَرَائِبَ وَغَرَائِزَ فَأَخْبِرْنِي عَنْ حَرْفَيْنِ أَسْأَلُكَ عَنْهُمَا مَا الْعَتْرَفُ فِي بَدَنِكَ وَمَا الصَّهْلَجُ فِي الانْسَانِ ثُمَّ اكْتُبْ إِلَيَّ بِخَبَرِ ذَلِكَ وَأَنَا مُتَقَدِّمٌ إِلَيْكَ أُحَذِّرُكَ مَعْصِيَةَ الْخَلِيفَةِ وَأَحُثُّكَ عَلَى بِرِّهِ وَطَاعَتِهِ وَأَنْ تَطْلُبَ لِنَفْسِكَ أَمَاناً قَبْلَ أَنْ تَأْخُذَكَ الاظْفَارُ وَيَلْزَمَكَ الْخِنَاقُ مِنْ كُلِّ مَكَانٍ فَتَرَوَّحَ إِلَى النَّفَسِ مِنْ كُلِّ مَكَانٍ وَلا تَجِدُهُ حَتَّى يَمُنَّ الله عَلَيْكَ بِمَنِّهِ وَفَضْلِهِ وَرِقَّةِ الْخَلِيفَةِ أَبْقَاهُ الله فَيُؤْمِنَكَ وَيَرْحَمَكَ وَيَحْفَظَ فِيكَ أَرْحَامَ رَسُولِ الله وَالسَّلامُ عَلَى مَنِ اتَّبَعَ الْهُدَى إِنَّا قَدْ أُوحِيَ إِلَيْنَا أَنَّ الْعَذَابَ عَلَى مَنْ كَذَّبَ وَتَوَلَّى قَالَ الْجَعْفَرِيُّ فَبَلَغَنِي أَنَّ كِتَابَ مُوسَى بْنِ جَعْفَرٍ (عَلَيْهما السَّلام) وَقَعَ فِي يَدَيْ هَارُونَ فَلَمَّا قَرَأَهُ قَالَ النَّاسُ يَحْمِلُونِّي عَلَى مُوسَى بْنِ جَعْفَرٍ وَهُوَ بَرِي‏ءٌ مِمَّا يُرْمَى بِهِ.","1/4/81/19","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[1,8,"عَلِيُّ بْنُ مُحَمَّدٍ وَمُحَمَّدُ بْنُ الْحَسَنِ عَنْ سَهْلِ بْنِ زِيَادٍ وَمُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى جَمِيعاً عَنِ الْحَسَنِ بْنِ مَحْبُوبٍ عَنْ أَبِي حَمْزَةَ الثُّمَالِيِّ قَالَ سَمِعْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) يَقُولُ يَا ثَابِتُ إِنَّ الله تَبَارَكَ وَتَعَالَى قَدْ كَانَ وَقَّتَ هَذَا الامْرَ فِي السَّبْعِينَ فَلَمَّا أَنْ قُتِلَ الْحُسَيْنُ صَلَوَاتُ الله عَلَيْهِ اشْتَدَّ غَضَبُ الله تَعَالَى عَلَى أَهْلِ الارْضِ فَأَخَّرَهُ إِلَى أَرْبَعِينَ وَمِائَةٍ فَحَدَّثْنَاكُمْ فَأَذَعْتُمُ الْحَدِيثَ فَكَشَفْتُمْ قِنَاعَ السَّتْرِ وَلَمْ يَجْعَلِ الله لَهُ بَعْدَ ذَلِكَ وَقْتاً عِنْدَنَا وَيَمْحُو الله مَا يَشَاءُ وَيُثْبِتُ وَعِنْدَهُ أُمُّ الْكِتَابِ قَالَ أَبُو حَمْزَةَ فَحَدَّثْتُ بِذَلِكَ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) فَقَالَ قَدْ كَانَ كَذَلِكَ.","1/4/82/1","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[2,8,"مُحَمَّدُ بْنُ يَحْيَى عَنْ سَلَمَةَ بْنِ الْخَطَّابِ عَنْ عَلِيِّ بْنِ حَسَّانَ عَنْ عَبْدِ الرَّحْمَنِ بْنِ كَثِيرٍ قَالَ كُنْتُ عِنْدَ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) إِذْ دَخَلَ عَلَيْهِ مِهْزَمٌ فَقَالَ لَهُ جُعِلْتُ فِدَاكَ أَخْبِرْنِي عَنْ هَذَا الامْرِ الَّذِي نَنْتَظِرُ مَتَى هُوَ فَقَالَ يَا مِهْزَمُ كَذَبَ الْوَقَّاتُونَ وَهَلَكَ الْمُسْتَعْجِلُونَ وَنَجَا الْمُسَلِّمُونَ.","1/4/82/2","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[3,8,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ خَالِدٍ عَنْ أَبِيهِ عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ أَبِي حَمْزَةَ عَنْ أَبِي بَصِيرٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ سَأَلْتُهُ عَنِ الْقَائِمِ (عَلَيْهِ السَّلام) فَقَالَ كَذَبَ الْوَقَّاتُونَ إِنَّا أَهْلُ بَيْتٍ لا نُوَقِّتُ.","1/4/82/3","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[4,8,"أَحْمَدُ بِإِسْنَادِهِ قَالَ قَالَ أَبَى الله إِلا أَنْ يُخَالِفَ وَقْتَ الْمُوَقِّتِينَ.","1/4/82/4","مرآة العقول: مرسل · البهبودي: لم يخرجه"],[5,8,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنِ الْحَسَنِ بْنِ عَلِيٍّ الْخَزَّازِ عَنْ عَبْدِ الْكَرِيمِ بْنِ عَمْرٍو الْخَثْعَمِيِّ عَنِ الْفُضَيْلِ بْنِ يَسَارٍ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ قُلْتُ لِهَذَا الامْرِ وَقْتٌ فَقَالَ كَذَبَ الْوَقَّاتُونَ كَذَبَ الْوَقَّاتُونَ كَذَبَ الْوَقَّاتُونَ إِنَّ مُوسَى (عَلَيْهِ السَّلام) لَمَّا خَرَجَ وَافِداً إِلَى رَبِّهِ وَاعَدَهُمْ ثَلاثِينَ يَوْماً فَلَمَّا زَادَهُ الله عَلَى الثَّلاثِينَ عَشْراً قَالَ قَوْمُهُ قَدْ أَخْلَفَنَا مُوسَى فَصَنَعُوا مَا صَنَعُوا فَإِذَا حَدَّثْنَاكُمُ الْحَدِيثَ فَجَاءَ عَلَى مَا حَدَّثْنَاكُمْ بِهِ فَقُولُوا صَدَقَ الله وَإِذَا حَدَّثْنَاكُمُ الْحَدِيثَ فَجَاءَ عَلَى خِلافِ مَا حَدَّثْنَاكُمْ بِهِ فَقُولُوا صَدَقَ الله تُؤْجَرُوا مَرَّتَيْنِ.","1/4/82/5","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[6,8,"مُحَمَّدُ بْنُ يَحْيَى وَأَحْمَدُ بْنُ إِدْرِيسَ عَنْ مُحَمَّدِ بْنِ أَحْمَدَ عَنِ السَّيَّارِيِّ عَنِ الْحَسَنِ بْنِ عَلِيِّ بْنِ يَقْطِينٍ عَنْ أَخِيهِ الْحُسَيْنِ عَنْ أَبِيهِ عَلِيِّ بْنِ يَقْطِينٍ قَالَ قَالَ لِي أَبُو الْحَسَنِ (عَلَيْهِ السَّلام) الشِّيعَةُ تُرَبَّى بِالامَانِيِّ مُنْذُ مِائَتَيْ سَنَةٍ قَالَ وَقَالَ يَقْطِينٌ لابْنِهِ عَلِيِّ بْنِ يَقْطِينٍ مَا بَالُنَا قِيلَ لَنَا فَكَانَ وَقِيلَ لَكُمْ فَلَمْ يَكُنْ قَالَ فَقَالَ لَهُ عَلِيٌّ إِنَّ الَّذِي قِيلَ لَنَا وَلَكُمْ كَانَ مِنْ مَخْرَجٍ وَاحِدٍ غَيْرَ أَنَّ أَمْرَكُمْ حَضَرَ فَأُعْطِيتُمْ مَحْضَهُ فَكَانَ كَمَا قِيلَ لَكُمْ وَإِنَّ أَمْرَنَا لَمْ يَحْضُرْ فَعُلِّلْنَا بِالامَانِيِّ فَلَوْ قِيلَ لَنَا إِنَّ هَذَا الامْرَ لا يَكُونُ إِلا إِلَى مِائَتَيْ سَنَةٍ أَوْ ثَلاثِمِائَةِ سَنَةٍ لَقَسَتِ الْقُلُوبُ وَلَرَجَعَ عَامَّةُ النَّاسِ عَنِ الاسْلامِ وَلَكِنْ قَالُوا مَا أَسْرَعَهُ وَمَا أَقْرَبَهُ تَأَلُّفاً لِقُلُوبِ النَّاسِ وَتَقْرِيباً لِلْفَرَجِ.","1/4/82/6","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[7,8,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ الْقَاسِمِ بْنِ إِسْمَاعِيلَ الانْبَارِيِّ عَنِ الْحَسَنِ بْنِ عَلِيٍّ عَنْ إِبْرَاهِيمَ بْنِ مِهْزَمٍ عَنْ أَبِيهِ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ ذَكَرْنَا عِنْدَهُ مُلُوكَ آلِ فُلانٍ فَقَالَ إِنَّمَا هَلَكَ النَّاسُ مِنِ اسْتِعْجَالِهِمْ لِهَذَا الامْرِ إِنَّ الله لا يَعْجَلُ لِعَجَلَةِ الْعِبَادِ إِنَّ لِهَذَا الامْرِ غَايَةً يَنْتَهِي إِلَيْهَا فَلَوْ قَدْ بَلَغُوهَا لَمْ يَسْتَقْدِمُوا سَاعَةً وَلَمْ يَسْتَأْخِرُوا.","1/4/82/7","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[1,9,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنِ الْحَسَنِ بْنِ مَحْبُوبٍ عَنْ يَعْقُوبَ السَّرَّاجِ وَعَلِيِّ بْنِ رِئَابٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) أَنَّ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) لَمَّا بُويِعَ بَعْدَ مَقْتَلِ عُثْمَانَ صَعِدَ الْمِنْبَرَ وَخَطَبَ بِخُطْبَةٍ ذَكَرَهَا يَقُولُ فِيهَا أَلا إِنَّ بَلِيَّتَكُمْ قَدْ عَادَتْ كَهَيْئَتِهَا يَوْمَ بَعَثَ الله نَبِيَّهُ (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَالَّذِي بَعَثَهُ بِالْحَقِّ لَتُبَلْبَلُنَّ بَلْبَلَةً وَلَتُغَرْبَلُنَّ غَرْبَلَةً حَتَّى يَعُودَ أَسْفَلُكُمْ أَعْلاكُمْ وَأَعْلاكُمْ أَسْفَلَكُمْ وَلَيَسْبِقَنَّ سَبَّاقُونَ كَانُوا قَصَّرُوا وَلَيُقَصِّرَنَّ سَبَّاقُونَ كَانُوا سَبَقُوا وَالله مَا كَتَمْتُ وَسْمَةً وَلا كَذَبْتُ كَذِبَةً وَلَقَدْ نُبِّئْتُ بِهَذَا الْمَقَامِ وَهَذَا الْيَوْمِ.","1/4/83/1","مرآة العقول: حسن · البهبودي: لم يخرجه"],[2,9,"مُحَمَّدُ بْنُ يَحْيَى وَالْحَسَنُ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ الْقَاسِمِ بْنِ إِسْمَاعِيلَ الانْبَارِيِّ عَنِ الْحُسَيْنِ بْنِ عَلِيٍّ عَنْ أَبِي الْمَغْرَاءِ عَنِ ابْنِ أَبِي يَعْفُورٍ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ وَيْلٌ لِطُغَاةِ الْعَرَبِ مِنْ أَمْرٍ قَدِ اقْتَرَبَ قُلْتُ جُعِلْتُ فِدَاكَ كَمْ مَعَ الْقَائِمِ مِنَ الْعَرَبِ قَالَ نَفَرٌ يَسِيرٌ قُلْتُ وَالله إِنَّ مَنْ يَصِفُ هَذَا الامْرَ مِنْهُمْ لَكَثِيرٌ قَالَ لا بُدَّ لِلنَّاسِ مِنْ أَنْ يُمَحَّصُوا وَيُمَيَّزُوا وَيُغَرْبَلُوا وَيُسْتَخْرَجُ فِي الْغِرْبَالِ خَلْقٌ كَثِيرٌ.","1/4/83/2","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[3,9,"مُحَمَّدُ بْنُ يَحْيَى وَالْحَسَنُ بْنُ مُحَمَّدٍ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ عَنِ الْحَسَنِ بْنِ مُحَمَّدٍ الصَّيْرَفِيِّ عَنْ جَعْفَرِ بْنِ مُحَمَّدٍ الصَّيْقَلِ عَنْ أَبِيهِ عَنْ مَنْصُورٍ قَالَ قَالَ لِي أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) يَا مَنْصُورُ إِنَّ هَذَا الامْرَ لا يَأْتِيكُمْ إِلا بَعْدَ إِيَاسٍ وَلا وَالله حَتَّى تُمَيَّزُوا وَلا وَالله حَتَّى تُمَحَّصُوا وَلا وَالله حَتَّى يَشْقَى مَنْ يَشْقَى وَيَسْعَدَ مَنْ يَسْعَدُ.","1/4/83/3","مرآة العقول: ضعيف أيضا · البهبودي: لم يخرجه"],[4,9,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ مُعَمَّرِ بْنِ خَلادٍ قَالَ سَمِعْتُ أَبَا الْحَسَنِ (عَلَيْهِ السَّلام) يَقُولُ الٓمٓ أَ حَسِبَ النَّاسُ أَنْ يُتْرَكُوا أَنْ يَقُولُوا آمَنَّا وَهُمْ لا يُفْتَنُونَ ثُمَّ قَالَ لِي مَا الْفِتْنَةُ قُلْتُ جُعِلْتُ فِدَاكَ الَّذِي عِنْدَنَا الْفِتْنَةُ فِي الدِّينِ فَقَالَ يُفْتَنُونَ كَمَا يُفْتَنُ الذَّهَبُ ثُمَّ قَالَ يُخْلَصُونَ كَمَا يُخْلَصُ الذَّهَبُ.","1/4/83/4","مرآة العقول: صحيح · البهبودي: صحيح"],[5,9,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عِيسَى عَنْ يُونُسَ عَنْ سُلَيْمَانَ بْنِ صَالِحٍ رَفَعَهُ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ قَالَ إِنَّ حَدِيثَكُمْ هَذَا لَتَشْمَئِزُّ مِنْهُ قُلُوبُ الرِّجَالِ فَمَنْ أَقَرَّ بِهِ فَزِيدُوهُ وَمَنْ أَنْكَرَهُ فَذَرُوهُ إِنَّهُ لا بُدَّ مِنْ أَنْ يَكُونَ فِتْنَةٌ يَسْقُطُ فِيهَا كُلُّ بِطَانَةٍ وَوَلِيجَةٍ حَتَّى يَسْقُطَ فِيهَا مَنْ يَشُقُّ الشَّعْرَ بِشَعْرَتَيْنِ حَتَّى لا يَبْقَى إِلا نَحْنُ وَشِيعَتُنَا.","1/4/83/5","مرآة العقول: مرفوع · البهبودي: لم يخرجه"],[6,9,"مُحَمَّدُ بْنُ الْحَسَنِ وَعَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ عَنْ مُحَمَّدِ بْنِ سِنَانٍ عَنْ مُحَمَّدِ بْنِ مَنْصُورٍ الصَّيْقَلِ عَنْ أَبِيهِ قَالَ كُنْتُ أَنَا وَالْحَارِثُ بْنُ الْمُغِيرَةِ وَجَمَاعَةٌ مِنْ أَصْحَابِنَا جُلُوساً وَأَبُو عَبْدِ الله (عَلَيْهِ السَّلام) يَسْمَعُ كَلامَنَا فَقَالَ لَنَا فِي أَيِّ شَيْ‏ءٍ أَنْتُمْ هَيْهَاتَ هَيْهَاتَ لا وَالله لا يَكُونُ مَا تَمُدُّونَ إِلَيْهِ أَعْيُنَكُمْ حَتَّى تُغَرْبَلُوا لا وَالله لا يَكُونُ مَا تَمُدُّونَ إِلَيْهِ أَعْيُنَكُمْ حَتَّى تُمَحَّصُوا لا وَالله لا يَكُونُ مَا تَمُدُّونَ إِلَيْهِ أَعْيُنَكُمْ حَتَّى تُمَيَّزُوا لا وَالله مَا يَكُونُ مَا تَمُدُّونَ إِلَيْهِ أَعْيُنَكُمْ إِلا بَعْدَ إِيَاسٍ لا وَالله لا يَكُونُ مَا تَمُدُّونَ إِلَيْهِ أَعْيُنَكُمْ حَتَّى يَشْقَى مَنْ يَشْقَى وَيَسْعَدَ مَنْ يَسْعَدُ.","1/4/83/6","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[1,10,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ حَمَّادِ بْنِ عِيسَى عَنْ حَرِيزٍ عَنْ زُرَارَةَ قَالَ قَالَ أَبُو عَبْدِ الله (عَلَيْهِ السَّلام) اعْرِفْ إِمَامَكَ فَإِنَّكَ إِذَا عَرَفْتَ لَمْ يَضُرَّكَ تَقَدَّمَ هَذَا الامْرُ أَوْ تَأَخَّرَ.","1/4/84/1","مرآة العقول: صحيح · البهبودي: صحيح"],[2,10,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ جُمْهُورٍ عَنْ صَفْوَانَ بْنِ يَحْيَى عَنْ مُحَمَّدِ بْنِ مَرْوَانَ عَنِ الْفُضَيْلِ بْنِ يَسَارٍ قَالَ سَأَلْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) عَنْ قَوْلِ الله تَبَارَكَ وَتَعَالَى يَوْمَ نَدْعُوا كُلَّ أُناسٍ بِإِمامِهِمْ فَقَالَ يَا فُضَيْلُ اعْرِفْ إِمَامَكَ فَإِنَّكَ إِذَا عَرَفْتَ إِمَامَكَ لَمْ يَضُرَّكَ تَقَدَّمَ هَذَا الامْرُ أَوْ تَأَخَّرَ وَمَنْ عَرَفَ إِمَامَهُ ثُمَّ مَاتَ قَبْلَ أَنْ يَقُومَ صَاحِبُ هَذَا الامْرِ كَانَ بِمَنْزِلَةِ مَنْ كَانَ قَاعِداً فِي عَسْكَرِهِ لا بَلْ بِمَنْزِلَةِ مَنْ قَعَدَ تَحْتَ لِوَائِهِ قَالَ وَقَالَ بَعْضُ أَصْحَابِهِ بِمَنْزِلَةِ مَنِ اسْتُشْهِدَ مَعَ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه )","1/4/84/2","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[3,10,"عَلِيُّ بْنُ مُحَمَّدٍ رَفَعَهُ عَنْ عَلِيِّ بْنِ أَبِي حَمْزَةَ عَنْ أَبِي بَصِيرٍ قَالَ قُلْتُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) جُعِلْتُ فِدَاكَ مَتَى الْفَرَجُ فَقَالَ يَا أَبَا بَصِيرٍ وَأَنْتَ مِمَّنْ يُرِيدُ الدُّنْيَا مَنْ عَرَفَ هَذَا الامْرَ فَقَدْ فُرِّجَ عَنْهُ لانْتِظَارِهِ.","1/4/84/3","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[4,10,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ صَالِحِ بْنِ السِّنْدِيِّ عَنْ جَعْفَرِ بْنِ بَشِيرٍ عَنْ إِسْمَاعِيلَ بْنِ مُحَمَّدٍ الْخُزَاعِيِّ قَالَ سَأَلَ أَبُو بَصِيرٍ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) وَأَنَا أَسْمَعُ فَقَالَ تَرَانِي أُدْرِكُ الْقَائِمَ (عَلَيْهِ السَّلام) فَقَالَ يَا أَبَا بَصِيرٍ أَ لَسْتَ تَعْرِفُ إِمَامَكَ فَقَالَ إِي وَالله وَأَنْتَ هُوَ وَتَنَاوَلَ يَدَهُ فَقَالَ وَالله مَا تُبَالِي يَا أَبَا بَصِيرٍ أَلا تَكُونَ مُحْتَبِياً بِسَيْفِكَ فِي ظِلِّ رِوَاقِ الْقَائِمِ صَلَوَاتُ الله عَلَيْهِ.","1/4/84/4","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[5,10,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ عَلِيِّ بْنِ النُّعْمَانِ عَنْ مُحَمَّدِ بْنِ مَرْوَانَ عَنْ فُضَيْلِ بْنِ يَسَارٍ قَالَ سَمِعْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) يَقُولُ مَنْ مَاتَ وَلَيْسَ لَهُ إِمَامٌ فَمِيتَتُهُ مِيتَةُ جَاهِلِيَّةٍ وَمَنْ مَاتَ وَهُوَ عَارِفٌ لامَامِهِ لَمْ يَضُرَّهُ تَقَدَّمَ هَذَا الامْرُ أَوْ تَأَخَّرَ وَمَنْ مَاتَ وَهُوَ عَارِفٌ لامَامِهِ كَانَ كَمَنْ هُوَ مَعَ الْقَائِمِ فِي فُسْطَاطِهِ.","1/4/84/5","مرآة العقول: مجهول · البهبودي: صحيح"],[6,10,"الْحُسَيْنُ بْنُ عَلِيٍّ الْعَلَوِيُّ عَنْ سَهْلِ بْنِ جُمْهُورٍ عَنْ عَبْدِ الْعَظِيمِ بْنِ عَبْدِ الله الْحَسَنِيِّ عَنِ الْحَسَنِ بْنِ الْحُسَيْنِ الْعُرَنِيِّ عَنْ عَلِيِّ بْنِ هَاشِمٍ عَنْ أَبِيهِ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ مَا ضَرَّ مَنْ مَاتَ مُنْتَظِراً لامْرِنَا أَلا يَمُوتَ فِي وَسَطِ فُسْطَاطِ الْمَهْدِيِّ وَعَسْكَرِهِ.","1/4/84/6","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[7,10,"عَلِيُّ بْنُ مُحَمَّدٍ عَنْ سَهْلِ بْنِ زِيَادٍ عَنِ الْحُسَيْنِ بْنِ سَعِيدٍ عَنْ فَضَالَةَ بْنِ أَيُّوبَ عَنْ عُمَرَ بْنِ أَبَانٍ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ اعْرِفِ الْعَلامَةَ فَإِذَا عَرَفْتَهُ لَمْ يَضُرَّكَ تَقَدَّمَ هَذَا الامْرُ أَوْ تَأَخَّرَ إِنَّ الله عَزَّ وَجَلَّ يَقُولُ يَوْمَ نَدْعُوا كُلَّ أُناسٍ بِإِمامِهِمْ فَمَنْ عَرَفَ إِمَامَهُ كَانَ كَمَنْ كَانَ فِي فُسْطَاطِ الْمُنْتَظَرِ (عَلَيْهِ السَّلام )","1/4/84/7","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[1,11,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ سِنَانٍ عَنْ أَبِي سَلامٍ عَنْ سَوْرَةَ بْنِ كُلَيْبٍ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ قُلْتُ لَهُ قَوْلُ الله عَزَّ وَجَلَّ وَيَوْمَ الْقِيامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى الله وُجُوهُهُمْ مُسْوَدَّةٌ قَالَ مَنْ قَالَ إِنِّي إِمَامٌ وَلَيْسَ بِإِمَامٍ قَالَ قُلْتُ وَإِنْ كَانَ عَلَوِيّاً قَالَ وَإِنْ كَانَ عَلَوِيّاً قُلْتُ وَإِنْ كَانَ مِنْ وُلْدِ عَلِيِّ ابْنِ أَبِي طَالِبٍ (عَلَيْهِ السَّلام) قَالَ وَإِنْ كَانَ.","1/4/85/1","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[2,11,"مُحَمَّدُ بْنُ يَحْيَى عَنْ عَبْدِ الله بْنِ مُحَمَّدِ بْنِ عِيسَى عَنْ عَلِيِّ بْنِ الْحَكَمِ عَنْ أَبَانٍ عَنِ الْفُضَيْلِ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ مَنِ ادَّعَى الامَامَةَ وَلَيْسَ مِنْ أَهْلِهَا فَهُوَ كَافِرٌ.","1/4/85/2","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[3,11,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ جُمْهُورٍ عَنْ عَبْدِ الله بْنِ عَبْدِ الرَّحْمَنِ عَنِ الْحُسَيْنِ بْنِ الْمُخْتَارِ قَالَ قُلْتُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) جُعِلْتُ فِدَاكَ وَيَوْمَ الْقِيامَةِ تَرَى الَّذِينَ كَذَبُوا عَلَى الله قَالَ كُلُّ مَنْ زَعَمَ أَنَّهُ إِمَامٌ وَلَيْسَ بِإِمَامٍ قُلْتُ وَإِنْ كَانَ فَاطِمِيّاً عَلَوِيّاً قَالَ وَإِنْ كَانَ فَاطِمِيّاً عَلَوِيّاً.","1/4/85/3","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[4,11,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْوَشَّاءِ عَنْ دَاوُدَ الْحَمَّارِ عَنِ ابْنِ أَبِي يَعْفُورٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ سَمِعْتُهُ يَقُولُ ثَلاثَةٌ لا يُكَلِّمُهُمُ الله يَوْمَ الْقِيَامَةِ وَلا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ مَنِ ادَّعَى إِمَامَةً مِنَ الله لَيْسَتْ لَهُ وَمَنْ جَحَدَ إِمَاماً مِنَ الله وَمَنْ زَعَمَ أَنَّ لَهُمَا فِي الاسْلامِ نَصِيباً.","1/4/85/4","مرآة العقول: مجهول · البهبودي: صحيح"],[5,11,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ سِنَانٍ عَنْ يَحْيَى أَخِي أُدَيْمٍ عَنِ الْوَلِيدِ بْنِ صَبِيحٍ قَالَ سَمِعْتُ أَبَا عَبْدِ الله يَقُولُ إِنَّ هَذَا الامْرَ لا يَدَّعِيهِ غَيْرُ صَاحِبِهِ إِلا بَتَرَ الله عُمُرَهُ.","1/4/85/5","مرآة العقول: ضعيف على المشهور معتب ر · البهبودي: لم يخرجه"],[6,11,"مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنْ مُحَمَّدِ بْنِ سِنَانٍ عَنْ طَلْحَةَ بْنِ زَيْدٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ مَنْ أَشْرَكَ مَعَ إِمَامٍ إِمَامَتُهُ مِنْ عِنْدِ الله مَنْ لَيْسَتْ إِمَامَتُهُ مِنَ الله كَانَ مُشْرِكاً بِالله.","1/4/85/6","البهبودي: لم يخرجه"],[7,11,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ إِسْمَاعِيلَ عَنْ مَنْصُورِ بْنِ يُونُسَ عَنْ مُحَمَّدِ بْنِ مُسْلِمٍ قَالَ قُلْتُ لابِي عَبْدِ الله (عَلَيْهِ السَّلام) رَجُلٌ قَالَ لِيَ اعْرِفِ الاخِرَ مِنَ الائِمَّةِ وَلا يَضُرُّكَ أَنْ لا تَعْرِفَ الاوَّلَ قَالَ فَقَالَ لَعَنَ الله هَذَا فَإِنِّي أُبْغِضُهُ وَلا أَعْرِفُهُ وَهَلْ عُرِفَ الاخِرُ إِلا بِالاوَّلِ.","1/4/85/7","مرآة العقول: موثق · البهبودي: صحيح"],[8,11,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ جُمْهُورٍ عَنْ صَفْوَانَ عَنِ ابْنِ مُسْكَانَ قَالَ سَأَلْتُ الشَّيْخَ عَنِ الائِمَّةِ (عَلَيْهِ السَّلام) قَالَ مَنْ أَنْكَرَ وَاحِداً مِنَ الاحْيَاءِ فَقَدْ أَنْكَرَ الامْوَاتَ.","1/4/85/8","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[9,11,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْحُسَيْنِ بْنِ سَعِيدٍ عَنْ أَبِي وَهْبٍ عَنْ مُحَمَّدِ بْنِ مَنْصُورٍ قَالَ سَأَلْتُهُ عَنْ قَوْلِ الله عَزَّ وَجَلَّ وَإِذا فَعَلُوا فاحِشَةً قالُوا وَجَدْنا عَلَيْها آباءَنا وَالله أَمَرَنا بِها قُلْ إِنَّ الله لا يَأْمُرُ بِالْفَحْشاءِ أَ تَقُولُونَ عَلَى الله ما لا تَعْلَمُونَ قَالَ فَقَالَ هَلْ رَأَيْتَ أَحَداً زَعَمَ أَنَّ الله أَمَرَ بِالزِّنَا وَشُرْبِ الْخَمْرِ أَوْ شَيْ‏ءٍ مِنْ هَذِهِ الْمَحَارِمِ فَقُلْتُ لا فَقَالَ مَا هَذِهِ الْفَاحِشَةُ الَّتِي يَدَّعُونَ أَنَّ الله أَمَرَهُمْ بِهَا قُلْتُ الله أَعْلَمُ وَوَلِيُّهُ قَالَ فَإِنَّ هَذَا فِي أَئِمَّةِ الْجَوْرِ ادَّعَوْا أَنَّ الله أَمَرَهُمْ بِالائْتِمَامِ بِقَوْمٍ لَمْ يَأْمُرْهُمُ الله بِالائْتِمَامِ بِهِمْ فَرَدَّ الله ذَلِكَ عَلَيْهِمْ فَأَخْبَرَ أَنَّهُمْ قَدْ قَالُوا عَلَيْهِ الْكَذِبَ وَسَمَّى ذَلِكَ مِنْهُمْ فَاحِشَةً.","1/4/85/9","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[10,11,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ الْحُسَيْنِ بْنِ سَعِيدٍ عَنْ أَبِي وَهْبِ عَنْ مُحَمَّدِ بْنِ مَنْصُورٍ قَالَ سَأَلْتُ عَبْداً صَالِحاً عَنْ قَوْلِ الله عَزَّ وَجَلَّ قُلْ إِنَّما حَرَّمَ رَبِّيَ الْفَواحِشَ ما ظَهَرَ مِنْها وَما بَطَنَ قَالَ فَقَالَ إِنَّ الْقُرْآنَ لَهُ ظَهْرٌ وَبَطْنٌ فَجَمِيعُ مَا حَرَّمَ الله فِي الْقُرْآنِ هُوَ الظَّاهِرُ وَالْبَاطِنُ مِنْ ذَلِكَ أَئِمَّةُ الْجَوْرِ وَجَمِيعُ مَا أَحَلَّ الله تَعَالَى فِي الْكِتَابِ هُوَ الظَّاهِرُ وَالْبَاطِنُ مِنْ ذَلِكَ أَئِمَّةُ الْحَقِّ.","1/4/85/10","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[11,11,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى عَنِ الْحَسَنِ بْنِ مَحْبُوبٍ عَنْ عَمْرِو بْنِ ثَابِتٍ عَنْ جَابِرٍ قَالَ سَأَلْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) عَنْ قَوْلِ الله عَزَّ وَجَلَّ وَمِنَ النَّاسِ مَنْ يَتَّخِذُ مِنْ دُونِ الله أَنْداداً يُحِبُّونَهُمْ كَحُبِّ الله قَالَ هُمْ وَالله أَوْلِيَاءُ فُلانٍ وَفُلانٍ اتَّخَذُوهُمْ أَئِمَّةً دُونَ الامَامِ الَّذِي جَعَلَهُ الله لِلنَّاسِ إِمَاماً فَلِذَلِكَ قَالَ وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذابَ أَنَّ الْقُوَّةَ لله جَمِيعاً وَأَنَّ الله شَدِيدُ الْعَذابِ. إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا وَرَأَوُا الْعَذابَ وَتَقَطَّعَتْ بِهِمُ الاسْبابُ. وَقالَ الَّذِينَ اتَّبَعُوا لَوْ أَنَّ لَنا كَرَّةً فَنَتَبَرَّأَ مِنْهُمْ كَما تَبَرَّؤُا مِنَّا كَذلِكَ يُرِيهِمُ الله أَعْمالَهُمْ حَسَراتٍ عَلَيْهِمْ وَما هُمْ بِخارِجِينَ مِنَ النَّارِ ثُمَّ قَالَ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) هُمْ وَالله يَا جَابِرُ أَئِمَّةُ الظَّلَمَةِ وَأَشْيَاعُهُمْ.","1/4/85/11","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[12,11,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنْ أَبِي دَاوُدَ الْمُسْتَرِقِّ عَنْ عَلِيِّ بْنِ مَيْمُونٍ عَنِ ابْنِ أَبِي يَعْفُورٍ قَالَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ ثَلاثَةٌ لا يَنْظُرُ الله إِلَيْهِمْ يَوْمَ الْقِيَامَةِ وَلا يُزَكِّيهِمْ وَلَهُمْ عَذَابٌ أَلِيمٌ مَنِ ادَّعَى إِمَامَةً مِنَ الله لَيْسَتْ لَهُ وَمَنْ جَحَدَ إِمَاماً مِنَ الله وَمَنْ زَعَمَ أَنَّ لَهُمَا فِي الاسْلامِ نَصِيباً.","1/4/85/12","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[1,12,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ الْبَرْقِيِّ عَنْ أَبِي هَاشِمٍ دَاوُدَ بْنِ الْقَاسِمِ الْجَعْفَرِيِّ عَنْ أَبِي جَعْفَرٍ الثَّانِي (عَلَيْهِ السَّلام) قَالَ أَقْبَلَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) وَمَعَهُ الْحَسَنُ بن علي (عَلَيْهما السَّلام) وَهُوَ مُتَّكِىٌ عَلَى يَدِ سَلْمَانَ فَدَخَلَ الْمَسْجِدَ الْحَرَامَ فَجَلَسَ إِذْ أَقْبَلَ رَجُلٌ حَسَنُ الْهَيْئَةِ وَاللِّبَاسِ فَسَلَّمَ عَلَى أَمِيرِ الْمُؤْمِنِينَ فَرَدَّ عَلَيْهِ السَّلامَ فَجَلَسَ ثُمَّ قَالَ يَا أَمِيرَ الْمُؤْمِنِينَ أَسْأَلُكَ عَنْ ثَلاثِ مَسَائِلَ إِنْ أَخْبَرْتَنِي بِهِنَّ عَلِمْتُ أَنَّ الْقَوْمَ رَكِبُوا مِنْ أَمْرِكَ مَا قُضِيَ عَلَيْهِمْ وَأَنْ لَيْسُوا بِمَأْمُونِينَ فِي دُنْيَاهُمْ وَآخِرَتِهِمْ وَإِنْ تَكُنِ الاخْرَى عَلِمْتُ أَنَّكَ وَهُمْ شَرَعٌ سَوَاءٌ فَقَالَ لَهُ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) سَلْنِي عَمَّا بَدَا لَكَ قَالَ أَخْبِرْنِي عَنِ الرَّجُلِ إِذَا نَامَ أَيْنَ تَذْهَبُ رُوحُهُ وَعَنِ الرَّجُلِ كَيْفَ يَذْكُرُ وَيَنْسَى وَعَنِ الرَّجُلِ كَيْفَ يُشْبِهُ وَلَدُهُ الاعْمَامَ وَالاخْوَالَ فَالْتَفَتَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) إِلَى الْحَسَنِ فَقَالَ يَا أَبَا مُحَمَّدٍ أَجِبْهُ قَالَ فَأَجَابَهُ الْحَسَنُ (عَلَيْهِ السَّلام) فَقَالَ الرَّجُلُ أَشْهَدُ أَنْ لا إِلَهَ إِلا الله وَلَمْ أَزَلْ أَشْهَدُ بِهَا وَأَشْهَدُ أَنَّ مُحَمَّداً رَسُولُ الله وَلَمْ أَزَلْ أَشْهَدُ بِذَلِكَ وَأَشْهَدُ أَنَّكَ وَصِيُّ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَالْقَائِمُ بِحُجَّتِهِ وَأَشَارَ إِلَى أَمِيرِ الْمُؤْمِنِينَ وَلَمْ أَزَلْ أَشْهَدُ بِهَا وَأَشْهَدُ أَنَّكَ وَصِيُّهُ وَالْقَائِمُ بِحُجَّتِهِ وَأَشَارَ إِلَى الْحَسَنِ (عَلَيْهِ السَّلام) وَأَشْهَدُ أَنَّ الْحُسَيْنَ بْنَ عَلِيٍّ وَصِيُّ أَخِيهِ وَالْقَائِمُ بِحُجَّتِهِ بَعْدَهُ وَأَشْهَدُ عَلَى عَلِيِّ بْنِ الْحُسَيْنِ أَنَّهُ الْقَائِمُ بِأَمْرِ الْحُسَيْنِ بَعْدَهُ وَأَشْهَدُ عَلَى مُحَمَّدِ بْنِ عَلِيٍّ أَنَّهُ الْقَائِمُ بِأَمْرِ عَلِيِّ بْنِ الْحُسَيْنِ وَأَشْهَدُ عَلَى جَعْفَرِ بْنِ مُحَمَّدٍ بِأَنَّهُ الْقَائِمُ بِأَمْرِ مُحَمَّدٍ وَأَشْهَدُ عَلَى مُوسَى أَنَّهُ الْقَائِمُ بِأَمْرِ جَعْفَرِ بْنِ مُحَمَّدٍ وَأَشْهَدُ عَلَى عَلِيِّ بْنِ مُوسَى أَنَّهُ الْقَائِمُ بِأَمْرِ مُوسَى بْنِ جَعْفَرٍ وَأَشْهَدُ عَلَى مُحَمَّدِ بْنِ عَلِيٍّ أَنَّهُ الْقَائِمُ بِأَمْرِ عَلِيِّ بْنِ مُوسَى وَأَشْهَدُ عَلَى عَلِيِّ بْنِ مُحَمَّدٍ بِأَنَّهُ الْقَائِمُ بِأَمْرِ مُحَمَّدِ بْنِ عَلِيٍّ وَأَشْهَدُ عَلَى الْحَسَنِ بْنِ عَلِيٍّ بِأَنَّهُ الْقَائِمُ بِأَمْرِ عَلِيِّ بْنِ مُحَمَّدٍ وَأَشْهَدُ عَلَى رَجُلٍ مِنْ وُلْدِ الْحَسَنِ لا يُكَنَّى وَلا يُسَمَّى حَتَّى يَظْهَرَ أَمْرُهُ فَيَمْلاهَا عَدْلاً كَمَا مُلِئَتْ جَوْراً وَالسَّلامُ عَلَيْكَ يَا أَمِيرَ الْمُؤْمِنِينَ وَرَحْمَةُ الله وَبَرَكَاتُهُ ثُمَّ قَامَ فَمَضَى فَقَالَ أَمِيرُ الْمُؤْمِنِينَ يَا أَبَا مُحَمَّدٍ اتْبَعْهُ فَانْظُرْ أَيْنَ يَقْصِدُ فَخَرَجَ الْحَسَنُ بن علي (عَلَيْهما السَّلام) فَقَالَ مَا كَانَ إِلا أَنْ وَضَعَ رِجْلَهُ خَارِجاً مِنَ الْمَسْجِدِ فَمَا دَرَيْتُ أَيْنَ أَخَذَ مِنْ أَرْضِ الله فَرَجَعْتُ إِلَى أَمِيرِ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) فَأَعْلَمْتُهُ فَقَالَ يَا أَبَا مُحَمَّدٍ أَ تَعْرِفُهُ قُلْتُ الله وَرَسُولُهُ وَأَمِيرُ الْمُؤْمِنِينَ أَعْلَمُ قَالَ هُوَ الْخَضِرُ (عَلَيْهِ السَّلام )","1/4/126/1","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[2,12,"وَحَدَّثَنِي مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ الْحَسَنِ الصَّفَّارِ عَنْ أَحْمَدَ بْنِ أَبِي عَبْدِ الله عَنْ أَبِي هَاشِمٍ مِثْلَهُ سَوَاءً قَالَ مُحَمَّدُ بْنُ يَحْيَى فَقُلْتُ لِمُحَمَّدِ بْنِ الْحَسَنِ يَا أَبَا جَعْفَرٍ وَدِدْتُ أَنَّ هَذَا الْخَبَرَ جَاءَ مِنْ غَيْرِ جِهَةِ أَحْمَدَ بْنِ أَبِي عَبْدِ الله قَالَ فَقَالَ لَقَدْ حَدَّثَنِي قَبْلَ الْحَيْرَةِ بِعَشْرِ سِنِينَ.","1/4/126/2","مرآة العقول: صحيح · البهبودي: لم يخرجه"],[3,12,"مُحَمَّدُ بْنُ يَحْيَى وَمُحَمَّدُ بْنُ عَبْدِ الله عَنْ عَبْدِ الله بْنِ جَعْفَرٍ عَنِ الْحَسَنِ بْنِ ظَرِيفٍ وَعَلِيُّ بْنُ مُحَمَّدٍ عَنْ صَالِحِ بْنِ أَبِي حَمَّادٍ عَنْ بَكْرِ بْنِ صَالِحٍ عَنْ عَبْدِ الرَّحْمَنِ بْنِ سَالِمٍ عَنْ أَبِي بَصِيرٍ عَنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ قَالَ أَبِي لِجَابِرِ بْنِ عَبْدِ الله الانْصَارِيِّ إِنَّ لِي إِلَيْكَ حَاجَةً فَمَتَى يَخِفُّ عَلَيْكَ أَنْ أَخْلُوَ بِكَ فَأَسْأَلَكَ عَنْهَا فَقَالَ لَهُ جَابِرٌ أَيَّ الاوْقَاتِ أَحْبَبْتَهُ فَخَلا بِهِ فِي بَعْضِ الايَّامِ فَقَالَ لَهُ يَا جَابِرُ أَخْبِرْنِي عَنِ اللَّوْحِ الَّذِي رَأَيْتَهُ فِي يَدِ أُمِّي فَاطِمَةَ (عليها السلام) بِنْتِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَمَا أَخْبَرَتْكَ بِهِ أُمِّي أَنَّهُ فِي ذَلِكَ اللَّوْحِ مَكْتُوبٌ فَقَالَ جَابِرٌ أَشْهَدُ بِالله أَنِّي دَخَلْتُ عَلَى أُمِّكَ فَاطِمَةَ (عليها السلام) فِي حَيَاةِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَهَنَّيْتُهَا بِوِلادَةِ الْحُسَيْنِ وَرَأَيْتُ فِي يَدَيْهَا لَوْحاً أَخْضَرَ ظَنَنْتُ أَنَّهُ مِنْ زُمُرُّدٍ وَرَأَيْتُ فِيهِ كِتَاباً أَبْيَضَ شِبْهَ لَوْنِ الشَّمْسِ فَقُلْتُ لَهَا بِأَبِي وَأُمِّي يَا بِنْتَ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) مَا هَذَا اللَّوْحُ فَقَالَتْ هَذَا لَوْحٌ أَهْدَاهُ الله إِلَى رَسُولِهِ (صَلَّى اللهُ عَلَيْهِ وَآلِه) فِيهِ اسْمُ أَبِي وَاسْمُ بَعْلِي وَاسْمُ ابْنَيَّ وَاسْمُ الاوْصِيَاءِ مِنْ وُلْدِي وَأَعْطَانِيهِ أَبِي لِيُبَشِّرَنِي بِذَلِكَ قَالَ جَابِرٌ فَأَعْطَتْنِيهِ أُمُّكَ فَاطِمَةُ (عليها السلام) فَقَرَأْتُهُ وَاسْتَنْسَخْتُهُ فَقَالَ لَهُ أَبِي فَهَلْ لَكَ يَا جَابِرُ أَنْ تَعْرِضَهُ عَلَيَّ قَالَ نَعَمْ فَمَشَى مَعَهُ أَبِي إِلَى مَنْزِلِ جَابِرٍ فَأَخْرَجَ صَحِيفَةً مِنْ رَقٍّ فَقَالَ يَا جَابِرُ انْظُرْ فِي كِتَابِكَ لاقْرَأَ أَنَا عَلَيْكَ فَنَظَرَ جَابِرٌ فِي نُسْخَةٍ فَقَرَأَهُ أَبِي فَمَا خَالَفَ حَرْفٌ حَرْفاً فَقَالَ جَابِرٌ فَأَشْهَدُ بِالله أَنِّي هَكَذَا رَأَيْتُهُ فِي اللَّوْحِ مَكْتُوباً بِسْمِ الله الرَّحْمَنِ الرَّحِيمِ هَذَا كِتَابٌ مِنَ الله الْعَزِيزِ الْحَكِيمِ لِمُحَمَّدٍ نَبِيِّهِ وَنُورِهِ وَسَفِيرِهِ وَحِجَابِهِ وَدَلِيلِهِ نَزَلَ بِهِ الرُّوحُ الامِينُ مِنْ عِنْدِ رَبِّ الْعَالَمِينَ عَظِّمْ يَا مُحَمَّدُ أَسْمَائِي وَاشْكُرْ نَعْمَائِي وَلا تَجْحَدْ آلائِي إِنِّي أَنَا الله لا إِلَهَ إِلا أَنَا قَاصِمُ الْجَبَّارِينَ وَمُدِيلُ الْمَظْلُومِينَ وَدَيَّانُ الدِّينِ إِنِّي أَنَا الله لا إِلَهَ إِلا أَنَا فَمَنْ رَجَا غَيْرَ فَضْلِي أَوْ خَافَ غَيْرَ عَدْلِي عَذَّبْتُهُ عَذَاباً لا أُعَذِّبُهُ أَحَداً مِنَ الْعَالَمِينَ فَإِيَّايَ فَاعْبُدْ وَعَلَيَّ فَتَوَكَّلْ إِنِّي لَمْ أَبْعَثْ نَبِيّاً فَأُكْمِلَتْ أَيَّامُهُ وَانْقَضَتْ مُدَّتُهُ إِلا جَعَلْتُ لَهُ وَصِيّاً وَإِنِّي فَضَّلْتُكَ عَلَى الانْبِيَاءِ وَفَضَّلْتُ وَصِيَّكَ عَلَى الاوْصِيَاءِ وَأَكْرَمْتُكَ بِشِبْلَيْكَ وَسِبْطَيْكَ حَسَنٍ وَحُسَيْنٍ فَجَعَلْتُ حَسَناً مَعْدِنَ عِلْمِي بَعْدَ انْقِضَاءِ مُدَّةِ أَبِيهِ وَجَعَلْتُ حُسَيْناً خَازِنَ وَحْيِي وَأَكْرَمْتُهُ بِالشَّهَادَةِ وَخَتَمْتُ لَهُ بِالسَّعَادَةِ فَهُوَ أَفْضَلُ مَنِ اسْتُشْهِدَ وَأَرْفَعُ الشُّهَدَاءِ دَرَجَةً جَعَلْتُ كَلِمَتِيَ التَّامَّةَ مَعَهُ وَحُجَّتِيَ الْبَالِغَةَ عِنْدَهُ بِعِتْرَتِهِ أُثِيبُ وَأُعَاقِبُ أَوَّلُهُمْ عَلِيٌّ سَيِّدُ الْعَابِدِينَ وَزَيْنُ أَوْلِيَائِيَ الْمَاضِينَ وَابْنُهُ شِبْهُ جَدِّهِ الْمَحْمُودِ مُحَمَّدٌ الْبَاقِرُ عِلْمِي وَالْمَعْدِنُ لِحِكْمَتِي سَيَهْلِكُ الْمُرْتَابُونَ فِي جَعْفَرٍ الرَّادُّ عَلَيْهِ كَالرَّادِّ عَلَيَّ حَقَّ الْقَوْلُ مِنِّي لاكْرِمَنَّ مَثْوَى جَعْفَرٍ وَلاسُرَّنَّهُ فِي أَشْيَاعِهِ وَأَنْصَارِهِ وَأَوْلِيَائِهِ أُتِيحَتْ بَعْدَهُ مُوسَى فِتْنَةٌ عَمْيَاءُ حِنْدِسٌ لانَّ خَيْطَ فَرْضِي لا يَنْقَطِعُ وَحُجَّتِي لا تَخْفَى وَأَنَّ أَوْلِيَائِي يُسْقَوْنَ بِالْكَأْسِ الاوْفَى مَنْ جَحَدَ وَاحِداً مِنْهُمْ فَقَدْ جَحَدَ نِعْمَتِي وَمَنْ غَيَّرَ آيَةً مِنْ كِتَابِي فَقَدِ افْتَرَى عَلَيَّ وَيْلٌ لِلْمُفْتَرِينَ الْجَاحِدِينَ عِنْدَ انْقِضَاءِ مُدَّةِ مُوسَى عَبْدِي وَحَبِيبِي وَخِيَرَتِي فِي عَلِيٍّ وَلِيِّي وَنَاصِرِي وَمَنْ أَضَعُ عَلَيْهِ أَعْبَاءَ النُّبُوَّةِ وَأَمْتَحِنُهُ بِالاضْطِلاعِ بِهَا يَقْتُلُهُ عِفْرِيتٌ مُسْتَكْبِرٌ يُدْفَنُ فِي الْمَدِينَةِ الَّتِي بَنَاهَا الْعَبْدُ الصَّالِحُ إِلَى جَنْبِ شَرِّ خَلْقِي حَقَّ الْقَوْلُ مِنِّي لاسُرَّنَّهُ بِمُحَمَّدٍ ابْنِهِ وَخَلِيفَتِهِ مِنْ بَعْدِهِ وَوَارِثِ عِلْمِهِ فَهُوَ مَعْدِنُ عِلْمِي وَمَوْضِعُ سِرِّي وَحُجَّتِي عَلَى خَلْقِي لا يُؤْمِنُ عَبْدٌ بِهِ إِلا جَعَلْتُ الْجَنَّةَ مَثْوَاهُ وَشَفَّعْتُهُ فِي سَبْعِينَ مِنْ أَهْلِ بَيْتِهِ كُلُّهُمْ قَدِ اسْتَوْجَبُوا النَّارَ وَأَخْتِمُ بِالسَّعَادَةِ لابْنِهِ عَلِيٍّ وَلِيِّي وَنَاصِرِي وَالشَّاهِدِ فِي خَلْقِي وَأَمِينِي عَلَى وَحْيِي أُخْرِجُ مِنْهُ الدَّاعِيَ إِلَى سَبِيلِي وَالْخَازِنَ لِعِلْمِيَ الْحَسَنَ وَأُكْمِلُ ذَلِكَ بِابْنِهِ م‏ح‏م‏د رَحْمَةً لِلْعَالَمِينَ عَلَيْهِ كَمَالُ مُوسَى وَبَهَاءُ عِيسَى وَصَبْرُ أَيُّوبَ فَيُذَلُّ أَوْلِيَائِي فِي زَمَانِهِ وَتُتَهَادَى رُءُوسُهُمْ كَمَا تُتَهَادَى رُءُوسُ التُّرْكِ وَالدَّيْلَمِ فَيُقْتَلُونَ وَيُحْرَقُونَ وَيَكُونُونَ خَائِفِينَ مَرْعُوبِينَ وَجِلِينَ تُصْبَغُ الارْضُ بِدِمَائِهِمْ وَيَفْشُو الْوَيْلُ وَالرَّنَّةُ فِي نِسَائِهِمْ أُولَئِكَ أَوْلِيَائِي حَقّاً بِهِمْ أَدْفَعُ كُلَّ فِتْنَةٍ عَمْيَاءَ حِنْدِسٍ وَبِهِمْ أَكْشِفُ الزَّلازِلَ وَأَدْفَعُ الاصَارَ وَالاغْلالَ أُولَئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ وَأُولَئِكَ هُمُ الْمُهْتَدُونَ قَالَ عَبْدُ الرَّحْمَنِ بْنُ سَالِمٍ قَالَ أَبُو بَصِيرٍ لَوْ لَمْ تَسْمَعْ فِي دَهْرِكَ إِلا هَذَا الْحَدِيثَ لَكَفَاكَ فَصُنْهُ إِلا عَنْ أَهْلِهِ.","1/4/126/3","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[4,12,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنْ حَمَّادِ بْنِ عِيسَى عَنْ إِبْرَاهِيمَ بْنِ عُمَرَ الْيَمَانِيِّ عَنْ أَبَانِ بْنِ أَبِي عَيَّاشٍ عَنْ سُلَيْمِ بْنِ قَيْسٍ وَمُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ أَبِي عُمَيْرٍ عَنْ عُمَرَ بْنِ أُذَيْنَةَ وَعَلِيُّ بْنُ مُحَمَّدٍ عَنْ أَحْمَدَ بْنِ هِلالٍ عَنِ ابْنِ أَبِي عُمَيْرٍ عَنْ عُمَرَ بْنِ أُذَيْنَةَ عَنْ أَبَانِ بْنِ أَبِي عَيَّاشٍ عَنْ سُلَيْمِ بْنِ قَيْسٍ قَالَ سَمِعْتُ عَبْدَ الله بْنَ جَعْفَرٍ الطَّيَّارِ يَقُولُ كُنَّا عِنْدَ مُعَاوِيَةَ أَنَا وَالْحَسَنُ وَالْحُسَيْنُ وَعَبْدُ الله بْنُ عَبَّاسٍ وَعُمَرُ ابْنُ أُمِّ سَلَمَةَ وَأُسَامَةُ بْنُ زَيْدٍ فَجَرَى بَيْنِي وَبَيْنَ مُعَاوِيَةَ كَلامٌ فَقُلْتُ لِمُعَاوِيَةَ سَمِعْتُ رَسُولَ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) يَقُولُ أَنَا أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ ثُمَّ أَخِي عَلِيُّ بْنُ أَبِي طَالِبٍ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ فَإِذَا اسْتُشْهِدَ عَلِيٌّ فَالْحَسَنُ بْنُ عَلِيٍّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ ثُمَّ ابْنِيَ الْحُسَيْنُ مِنْ بَعْدِهِ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ فَإِذَا اسْتُشْهِدَ فَابْنُهُ عَلِيُّ بْنُ الْحُسَيْنِ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ وَسَتُدْرِكُهُ يَا عَلِيُّ ثُمَّ ابْنُهُ مُحَمَّدُ بْنُ عَلِيٍّ أَوْلَى بِالْمُؤْمِنِينَ مِنْ أَنْفُسِهِمْ وَسَتُدْرِكُهُ يَا حُسَيْنُ ثُمَّ يُكَمِّلُهُ اثْنَيْ عَشَرَ إِمَاماً تِسْعَةً مِنْ وُلْدِ الْحُسَيْنِ قَالَ عَبْدُ الله بْنُ جَعْفَرٍ وَاسْتَشْهَدْتُ الْحَسَنَ وَالْحُسَيْنَ وَعَبْدَ الله بْنَ عَبَّاسٍ وَعُمَرَ ابْنَ أُمِّ سَلَمَةَ وَأُسَامَةَ بْنَ زَيْدٍ فَشَهِدُوا لِي عِنْدَ مُعَاوِيَةَ قَالَ سُلَيْمٌ وَقَدْ سَمِعْتُ ذَلِكَ مِنْ سَلْمَانَ وَأَبِي ذَرٍّ وَالْمِقْدَادِ وَذَكَرُوا أَنَّهُمْ سَمِعُوا ذَلِكَ مِنْ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه )","1/4/126/4","مرآة العقول: مختلف في ه · البهبودي: لم يخرجه"],[5,12,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ خَالِدٍ عَنْ أَبِيهِ عَنْ عَبْدِ الله بْنِ الْقَاسِمِ عَنْ حَنَانِ بْنِ السَّرَّاجِ عَنْ دَاوُدَ بْنِ سُلَيْمَانَ الْكِسَائِيِّ عَنْ أَبِي الطُّفَيْلِ قَالَ شَهِدْتُ جِنَازَةَ أَبِي بَكْرٍ يَوْمَ مَاتَ وَشَهِدْتُ عُمَرَ حِينَ بُويِعَ وَعلي (عَلَيْهِ السَّلام) جَالِسٌ نَاحِيَةً فَأَقْبَلَ غُلامٌ يَهُودِيٌّ جَمِيلُ الْوَجْهِ بَهِيٌّ عَلَيْهِ ثِيَابُ حِسَانٌ وَهُوَ مِنْ وُلْدِ هَارُونَ حَتَّى قَامَ عَلَى رَأْسِ عُمَرَ فَقَالَ يَا أَمِيرَ الْمُؤْمِنِينَ أَنْتَ أَعْلَمُ هَذِهِ الامَّةِ بِكِتَابِهِمْ وَأَمْرِ نَبِيِّهِمْ قَالَ فَطَأْطَأَ عُمَرُ رَأْسَهُ فَقَالَ إِيَّاكَ أَعْنِي وَأَعَادَ عَلَيْهِ الْقَوْلَ فَقَالَ لَهُ عُمَرُ لِمَ ذَاكَ قَالَ إِنِّي جِئْتُكَ مُرْتَاداً لِنَفْسِي شَاكّاً فِي دِينِي فَقَالَ دُونَكَ هَذَا الشَّابَّ قَالَ وَمَنْ هَذَا الشَّابُّ قَالَ هَذَا عَلِيُّ بْنُ أَبِي طَالِبٍ ابْنُ عَمِّ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَهَذَا أَبُو الْحَسَنِ وَالْحُسَيْنِ ابْنَيْ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَهَذَا زَوْجُ فَاطِمَةَ بِنْتِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَأَقْبَلَ الْيَهُودِيُّ عَلَى علي (عَلَيْهِ السَّلام) فَقَالَ أَ كَذَاكَ أَنْتَ قَالَ نَعَمْ قَالَ إِنِّي أُرِيدُ أَنْ أَسْأَلَكَ عَنْ ثَلاثٍ وَثَلاثٍ وَوَاحِدَةٍ قَالَ فَتَبَسَّمَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) مِنْ غَيْرِ تَبَسُّمٍ وَقَالَ يَا هَارُونِيُّ مَا مَنَعَكَ أَنْ تَقُولَ سَبْعاً قَالَ أَسْأَلُكَ عَنْ ثَلاثٍ فَإِنْ أَجَبْتَنِي سَأَلْتُ عَمَّا بَعْدَهُنَّ وَإِنْ لَمْ تَعْلَمْهُنَّ عَلِمْتُ أَنَّهُ لَيْسَ فِيكُمْ عَالِمٌ قَالَ علي (عَلَيْهِ السَّلام) فَإِنِّي أَسْأَلُكَ بِالالَهِ الَّذِي تَعْبُدُهُ لَئِنْ أَنَا أَجَبْتُكَ فِي كُلِّ مَا تُرِيدُ لَتَدَعَنَّ دِينَكَ وَلَتَدْخُلَنَّ فِي دِينِي قَالَ مَا جِئْتُ إِلا لِذَاكَ قَالَ فَسَلْ قَالَ أَخْبِرْنِي عَنْ أَوَّلِ قَطْرَةِ دَمٍ قَطَرَتْ عَلَى وَجْهِ الارْضِ أَيُّ قَطْرَةٍ هِيَ وَأَوَّلِ عَيْنٍ فَاضَتْ عَلَى وَجْهِ الارْضِ أَيُّ عَيْنٍ هِيَ وَأَوَّلِ شَيْ‏ءٍ اهْتَزَّ عَلَى وَجْهِ الارْضِ أَيُّ شَيْ‏ءٍ هُوَ فَأَجَابَهُ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) فَقَالَ لَهُ أَخْبِرْنِي عَنِ الثَّلاثِ الاخَرِ أَخْبِرْنِي عَنْ مُحَمَّدٍ كَمْ لَهُ مِنْ إِمَامٍ عَدْلٍ وَفِي أَيِّ جَنَّةٍ يَكُونُ وَمَنْ سَاكَنَهُ مَعَهُ فِي جَنَّتِهِ فَقَالَ يَا هَارُونِيُّ إِنَّ لِمُحَمَّدٍ اثْنَيْ عَشَرَ إِمَامَ عَدْلٍ لا يَضُرُّهُمْ خِذْلانُ مَنْ خَذَلَهُمْ وَلا يَسْتَوْحِشُونَ بِخِلافِ مَنْ خَالَفَهُمْ وَإِنَّهُمْ فِي الدِّينِ أَرْسَبُ مِنَ الْجِبَالِ الرَّوَاسِي فِي الارْضِ وَمَسْكَنُ مُحَمَّدٍ فِي جَنَّتِهِ مَعَهُ أُولَئِكَ الاثْنَيْ عَشَرَ الامَامَ الْعَدْلَ فَقَالَ صَدَقْتَ وَالله الَّذِي لا إِلَهَ إِلا هُوَ إِنِّي لاجِدُهَا فِي كُتُبِ أَبِي هَارُونَ كَتَبَهُ بِيَدِهِ وَأَمْلاهُ مُوسَى عَمِّي (عَلَيْهِ السَّلام) قَالَ فَأَخْبِرْنِي عَنِ الْوَاحِدَةِ أَخْبِرْنِي عَنْ وَصِيِّ مُحَمَّدٍ كَمْ يَعِيشُ مِنْ بَعْدِهِ وَهَلْ يَمُوتُ أَوْ يُقْتَلُ قَالَ يَا هَارُونِيُّ يَعِيشُ بَعْدَهُ ثَلاثِينَ سَنَةً لا يَزِيدُ يَوْماً وَلا يَنْقُصُ يَوْماً ثُمَّ يُضْرَبُ ضَرْبَةً هَاهُنَا يَعْنِي عَلَى قَرْنِهِ فَتُخْضَبُ هَذِهِ مِنْ هَذَا قَالَ فَصَاحَ الْهَارُونِيُّ وَقَطَعَ كُسْتِيجَهُ وَهُوَ يَقُولُ أَشْهَدُ أَنْ لا إِلَهَ إِلا الله وَحْدَهُ لا شَرِيكَ لَهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ وَأَنَّكَ وَصِيُّهُ يَنْبَغِي أَنْ تَفُوقَ وَلا تُفَاقَ وَأَنْ تُعَظَّمَ وَلا تُسْتَضْعَفَ قَالَ ثُمَّ مَضَى بِهِ علي (عَلَيْهِ السَّلام) إِلَى مَنْزِلِهِ فَعَلَّمَهُ مَعَالِمَ الدِّينِ.","1/4/126/5","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[6,12,"مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ أَحْمَدَ عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنْ أَبِي سَعِيدٍ الْعُصْفُورِيِّ عَنْ عَمْرِو بْنِ ثَابِتٍ عَنْ أَبِي حَمْزَةَ قَالَ سَمِعْتُ عَلِيَّ بن الحسين (عَلَيْهما السَّلام) يَقُولُ إِنَّ الله خَلَقَ مُحَمَّداً وَعَلِيّاً وَأَحَدَ عَشَرَ مِنْ وُلْدِهِ مِنْ نُورِ عَظَمَتِهِ فَأَقَامَهُمْ أَشْبَاحاً فِي ضِيَاءِ نُورِهِ يَعْبُدُونَهُ قَبْلَ خَلْقِ الْخَلْقِ يُسَبِّحُونَ الله وَيُقَدِّسُونَهُ وَهُمُ الائِمَّةُ مِنْ وُلْدِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه )","1/4/126/6","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[7,12,"مُحَمَّدُ بْنُ يَحْيَى عَنْ عَبْدِ الله بْنِ مُحَمَّدٍ الْخَشَّابِ عَنِ ابْنِ سَمَاعَةَ عَنْ عَلِيِّ بْنِ الْحَسَنِ بْنِ رِبَاطٍ عَنِ ابْنِ أُذَيْنَةَ عَنْ زُرَارَةَ قَالَ سَمِعْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) يَقُولُ الاثْنَا عَشَرَ الامَامَ مِنْ آلِ مُحَمَّدٍ (عَلَيْهم السَّلام) كُلُّهُمْ مُحَدَّثٌ مِنْ وُلْدِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَمِنْ وُلْدِ عَلِيٍّ وَرَسُولُ الله وَعلي (عَلَيْهِ السَّلام) هُمَا الْوَالِدَانِ فَقَالَ عَلِيُّ بْنُ رَاشِدٍ كَانَ أَخَا عَلِيِّ بْنِ الْحُسَيْنِ لامِّهِ وَأَنْكَرَ ذَلِكَ فَصَرَّرَ أَبُو جَعْفَرٍ (عَلَيْهِ السَّلام) وَقَالَ أَمَا إِنَّ ابْنَ أُمِّكَ كَانَ أَحَدَهُمْ.","1/4/126/7","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[8,12,"مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنْ مَسْعَدَةَ بْنِ زِيَادٍ عَنْ أَبِي عَبْدِ الله وَمُحَمَّدِ بْنِ الْحُسَيْنِ عَنْ إِبْرَاهِيمَ عَنْ أَبِي يَحْيَى الْمَدَائِنِيِّ عَنْ أَبِي هَارُونَ الْعَبْدِيِّ عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ كُنْتُ حَاضِراً لَمَّا هَلَكَ أَبُو بَكْرٍ وَاسْتَخْلَفَ عُمَرَ أَقْبَلَ يَهُودِيٌّ مِنْ عُظَمَاءِ يَهُودِ يَثْرِبَ وَتَزْعُمُ يَهُودُ الْمَدِينَةِ أَنَّهُ أَعْلَمُ أَهْلِ زَمَانِهِ حَتَّى رُفِعَ إِلَى عُمَرَ فَقَالَ لَهُ يَا عُمَرُ إِنِّي جِئْتُكَ أُرِيدُ الاسْلامَ فَإِنْ أَخْبَرْتَنِي عَمَّا أَسْأَلُكَ عَنْهُ فَأَنْتَ أَعْلَمُ أَصْحَابِ مُحَمَّدٍ بِالْكِتَابِ وَالسُّنَّةِ وَجَمِيعِ مَا أُرِيدُ أَنْ أَسْأَلَ عَنْهُ قَالَ فَقَالَ لَهُ عُمَرُ إِنِّي لَسْتُ هُنَاكَ لَكِنِّي أُرْشِدُكَ إِلَى مَنْ هُوَ أَعْلَمُ أُمَّتِنَا بِالْكِتَابِ وَالسُّنَّةِ وَجَمِيعِ مَا قَدْ تَسْأَلُ عَنْهُ وَهُوَ ذَاكَ فَأَوْمَأَ إِلَى علي (عَلَيْهِ السَّلام) فَقَالَ لَهُ الْيَهُودِيُّ يَا عُمَرُ إِنْ كَانَ هَذَا كَمَا تَقُولُ فَمَا لَكَ وَلِبَيْعَةِ النَّاسِ وَإِنَّمَا ذَاكَ أَعْلَمُكُمْ فَزَبَرَهُ عُمَرُ ثُمَّ إِنَّ الْيَهُودِيَّ قَامَ إِلَى علي (عَلَيْهِ السَّلام) فَقَالَ لَهُ أَنْتَ كَمَا ذَكَرَ عُمَرُ فَقَالَ وَمَا قَالَ عُمَرُ فَأَخْبَرَهُ قَالَ فَإِنْ كُنْتَ كَمَا قَالَ سَأَلْتُكَ عَنْ أَشْيَاءَ أُرِيدُ أَنْ أَعْلَمَ هَلْ يَعْلَمُهُ أَحَدٌ مِنْكُمْ فَأَعْلَمَ أَنَّكُمْ فِي دَعْوَاكُمْ خَيْرُ الامَمِ وَأَعْلَمُهَا صَادِقِينَ وَمَعَ ذَلِكَ أَدْخُلُ فِي دِينِكُمُ الاسْلامِ فَقَالَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) نَعَمْ أَنَا كَمَا ذَكَرَ لَكَ عُمَرُ سَلْ عَمَّا بَدَا لَكَ أُخْبِرْكَ بِهِ إِنْ شَاءَ الله قَالَ أَخْبِرْنِي عَنْ ثَلاثٍ وَثَلاثٍ وَوَاحِدَةٍ فَقَالَ لَهُ علي (عَلَيْهِ السَّلام) يَا يَهُودِيُّ وَلِمَ لَمْ تَقُلْ أَخْبِرْنِي عَنْ سَبْعٍ فَقَالَ لَهُ الْيَهُودِيُّ إِنَّكَ إِنْ أَخْبَرْتَنِي بِالثَّلاثِ سَأَلْتُكَ عَنِ الْبَقِيَّةِ وَإِلا كَفَفْتُ فَإِنْ أَنْتَ أَجَبْتَنِي فِي هَذِهِ السَّبْعِ فَأَنْتَ أَعْلَمُ أَهْلِ الارْضِ وَأَفْضَلُهُمْ وَأَوْلَى النَّاسِ بِالنَّاسِ فَقَالَ لَهُ سَلْ عَمَّا بَدَا لَكَ يَا يَهُودِيُّ قَالَ أَخْبِرْنِي عَنْ أَوَّلِ حَجَرٍ وُضِعَ عَلَى وَجْهِ الارْضِ وَأَوَّلِ شَجَرَةٍ غُرِسَتْ عَلَى وَجْهِ الارْضِ وَأَوَّلِ عَيْنٍ نَبَعَتْ عَلَى وَجْهِ الارْضِ فَأَخْبَرَهُ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) ثُمَّ قَالَ لَهُ الْيَهُودِيُّ أَخْبِرْنِي عَنْ هَذِهِ الامَّةِ كَمْ لَهَا مِنْ إِمَامٍ هُدًى وَأَخْبِرْنِي عَنْ نَبِيِّكُمْ مُحَمَّدٍ أَيْنَ مَنْزِلُهُ فِي الْجَنَّةِ وَأَخْبِرْنِي مَنْ مَعَهُ فِي الْجَنَّةِ فَقَالَ لَهُ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) إِنَّ لِهَذِهِ الامَّةِ اثْنَيْ عَشَرَ إِمَاماً هُدًى مِنْ ذُرِّيَّةِ نَبِيِّهَا وَهُمْ مِنِّي وَأَمَّا مَنْزِلُ نَبِيِّنَا فِي الْجَنَّةِ فَفِي أَفْضَلِهَا وَأَشْرَفِهَا جَنَّةِ عَدْنٍ وَأَمَّا مَنْ مَعَهُ فِي مَنْزِلِهِ فِيهَا فَهَؤُلاءِ الاثْنَا عَشَرَ مِنْ ذُرِّيَّتِهِ وَأُمُّهُمْ وَجَدَّتُهُمْ وَأُمُّ أُمِّهِمْ وَذَرَارِيُّهُمْ لا يَشْرَكُهُمْ فِيهَا أَحَدٌ.","1/4/126/8",""],[9,12,"مُحَمَّدُ بْنُ يَحْيَى عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنِ ابْنِ مَحْبُوبٍ عَنْ أَبِي الْجَارُودِ عَنْ ابي جعفر (عَلَيْهِ السَّلام) عَنْ جَابِرِ بْنِ عَبْدِ الله الانْصَارِيِّ قَالَ دَخَلْتُ عَلَى فَاطِمَةَ (عليها السلام) وَبَيْنَ يَدَيْهَا لَوْحٌ فِيهِ أَسْمَاءُ الاوْصِيَاءِ مِنْ وُلْدِهَا فَعَدَدْتُ اثْنَيْ عَشَرَ آخِرُهُمُ الْقَائِمُ (عجل الله تعالى فرجه الشريف) ثَلاثَةٌ مِنْهُمْ مُحَمَّدٌ وَثَلاثَةٌ مِنْهُمْ عَلِيٌّ.","1/4/126/9","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[10,12,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ مُحَمَّدِ بْنِ عِيسَى بْنِ عُبَيْدٍ عَنْ مُحَمَّدِ بْنِ الْفُضَيْلِ عَنْ أَبِي حَمْزَةَ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ إِنَّ الله أَرْسَلَ مُحَمَّداً (صَلَّى اللهُ عَلَيْهِ وَآلِه) إِلَى الْجِنِّ وَالانْسِ وَجَعَلَ مِنْ بَعْدِهِ اثْنَيْ عَشَرَ وَصِيّاً مِنْهُمْ مَنْ سَبَقَ وَمِنْهُمْ مَنْ بَقِيَ وَكُلُّ وَصِيٍّ جَرَتْ بِهِ سُنَّةٌ وَالاوْصِيَاءُ الَّذِينَ مِنْ بَعْدِ مُحَمَّدٍ (صَلَّى اللهُ عَلَيْهِ وَآلِه) عَلَى سُنَّةِ أَوْصِيَاءِ عِيسَى وَكَانُوا اثْنَيْ عَشَرَ وَكَانَ أَمِيرُ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) عَلَى سُنَّةِ الْمَسِيحِ.","1/4/126/10","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[11,12,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى وَمُحَمَّدُ بْنُ أَبِي عَبْدِ الله وَمُحَمَّدُ بْنُ الْحَسَنِ عَنْ سَهْلِ بْنِ زِيَادٍ جَمِيعاً عَنِ الْحَسَنِ بْنِ الْعَبَّاسِ بْنِ الْحَرِيشِ عَنْ أَبِي جَعْفَرٍ الثَّانِي (عَلَيْهِ السَّلام) أَنَّ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) قَالَ لابْنِ عَبَّاسٍ إِنَّ لَيْلَةَ الْقَدْرِ فِي كُلِّ سَنَةٍ وَإِنَّهُ يَنْزِلُ فِي تِلْكَ اللَّيْلَةِ أَمْرُ السَّنَةِ وَلِذَلِكَ الامْرِ وُلاةٌ بَعْدَ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَقَالَ ابْنُ عَبَّاسٍ مَنْ هُمْ قَالَ أَنَا وَأَحَدَ عَشَرَ مِنْ صُلْبِي أَئِمَّةٌ مُحَدَّثُونَ.","1/4/126/11","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[12,12,"وَبِهَذَا الاسْنَادِ قَالَ قَالَ رَسُولُ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) لاصْحَابِهِ آمِنُوا بِلَيْلَةِ الْقَدْرِ إِنَّهَا تَكُونُ لِعَلِيِّ بْنِ أَبِي طَالِبٍ وَلِوُلْدِهِ الاحَدَ عَشَرَ مِنْ بَعْدِي.","1/4/126/12","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[13,12,"وَبِهَذَا الاسْنَادِ أَنَّ أَمِيرَ الْمُؤْمِنِينَ (عَلَيْهِ السَّلام) قَالَ لابِي بَكْرٍ يَوْماً لا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ الله أَمْواتاً بَلْ أَحْياءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ وَأَشْهَدُ أَنَّ مُحَمَّداً (صَلَّى اللهُ عَلَيْهِ وَآلِه) رَسُولُ الله مَاتَ شَهِيداً وَالله لَيَأْتِيَنَّكَ فَأَيْقِنْ إِذَا جَاءَكَ فَإِنَّ الشَّيْطَانَ غَيْرُ مُتَخَيِّلٍ بِهِ فَأَخَذَ عَلِيٌّ بِيَدِ أَبِي بَكْرٍ فَأَرَاهُ النَّبِيَّ (صَلَّى اللهُ عَلَيْهِ وَآلِه) فَقَالَ لَهُ يَا أَبَا بَكْرٍ آمِنْ بِعَلِيٍّ وَبِأَحَدَ عَشَرَ مِنْ وُلْدِهِ إِنَّهُمْ مِثْلِي إِلا النُّبُوَّةَ وَتُبْ إِلَى الله مِمَّا فِي يَدِكَ فَإِنَّهُ لا حَقَّ لَكَ فِيهِ قَالَ ثُمَّ ذَهَبَ فَلَمْ يُرَ.","1/4/126/13","البهبودي: لم يخرجه"],[14,12,"أَبُو عَلِيٍّ الاشْعَرِيُّ عَنِ الْحَسَنِ بْنِ عُبَيْدِ الله عَنِ الْحَسَنِ بْنِ مُوسَى الْخَشَّابِ عَنْ عَلِيِّ بْنِ سَمَاعَةَ عَنْ عَلِيِّ بْنِ الْحَسَنِ بْنِ رِبَاطٍ عَنِ ابْنِ أُذَيْنَةَ عَنْ زُرَارَةَ قَالَ سَمِعْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) يَقُولُ الاثْنَا عَشَرَ الامَامَ مِنْ آلِ مُحَمَّدٍ كُلُّهُمْ مُحَدَّثٌ مِنْ وُلْدِ رَسُولِ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَوُلْدِ عَلِيِّ بْنِ أَبِي طَالِبٍ (عَلَيْهِ السَّلام) فَرَسُولُ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَعلي (عَلَيْهِ السَّلام) هُمَا الْوَالِدَانِ.","1/4/126/14","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[15,12,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنِ ابْنِ أَبِي عُمَيْرٍ عَنْ سَعِيدِ بْنِ غَزْوَانَ عَنْ أَبِي بَصِيرٍ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ يَكُونُ تِسْعَةُ أَئِمَّةٍ بَعْدَ الْحُسَيْنِ بْنِ عَلِيٍّ تَاسِعُهُمْ قَائِمُهُمْ.","1/4/126/15","مرآة العقول: حسن كالصحيح · البهبودي: لم يخرجه"],[16,12,"الْحُسَيْنُ بْنُ مُحَمَّدٍ عَنْ مُعَلَّى بْنِ مُحَمَّدٍ عَنِ الْوَشَّاءِ عَنْ أَبَانٍ عَنْ زُرَارَةَ قَالَ سَمِعْتُ أَبَا جَعْفَرٍ (عَلَيْهِ السَّلام) يَقُولُ نَحْنُ اثْنَا عَشَرَ إِمَاماً مِنْهُمْ حَسَنٌ وَحُسَيْنٌ ثُمَّ الائِمَّةُ مِنْ وُلْدِ الْحُسَيْنِ (عَلَيْهِ السَّلام )","1/4/126/16","مرآة العقول: ضعيف على المشهور · البهبودي: لم يخرجه"],[17,12,"17. مُحَمَّدُ بْنُ يَحْيى ، عَنْ مُحَمَّدِ بْنِ أَحْمَدَ ، عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ ، عَنْ‌ أَبِي سَعِيدٍ الْعُصْفُرِيِّ ، عَنْ عَمْرِو بْنِ ثَابِتٍ ، عَنْ أَبِي الْجَارُودِ : عَنْ أَبِي جَعْفَرٍ عليه‌السلام ، قَالَ : « قَالَ رَسُولُ اللهِ صلى‌الله‌عليه‌وآله‌وسلم : إِنِّي واثْنَيْ عَشَرَ مِنْ وُلْدِي وأَنْتَ يَا عَلِيُّ زِرُّ الْأَرْضِ ـ يَعْنِي أَوْتَادَهَا وجِبَالَهَا ـ بِنَا أَوْتَدَ اللهُ الْأَرْضَ أَنْ تَسِيخَ بِأَهْلِهَا ، فَإِذَا ذَهَبَ الِاثْنَا عَشَرَ مِنْ ولْدِي ، سَاخَتِ الْأَرْضُ بِأَهْلِهَا ، ولَمْ يُنْظَرُوا ».”","1/4/126/17","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[18,12,"وَبِهَذَا الاسْنَادِ عَنْ أَبِي سَعِيدٍ رَفَعَهُ عَنْ ابي جعفر (عَلَيْهِ السَّلام) قَالَ قَالَ رَسُولُ الله (صَلَّى اللهُ عَلَيْهِ وَآلِه) مِنْ وُلْدِيَ اثْنَا عَشَرَ نَقِيباً نُجَبَاءُ مُحَدَّثُونَ مُفَهَّمُونَ آخِرُهُمُ الْقَائِمُ بِالْحَقِّ يَمْلاهَا عَدْلاً كَمَا مُلِئَتْ جَوْراً.","1/4/126/18","مرآة العقول: مرفوع · البهبودي: لم يخرجه"],[19,12,"عَلِيُّ بْنُ مُحَمَّدٍ وَمُحَمَّدُ بْنُ الْحَسَنِ عَنْ سَهْلِ بْنِ زِيَادٍ عَنْ مُحَمَّدِ بْنِ الْحَسَنِ بْنِ شَمُّونٍ عَنْ عَبْدِ الله بْنِ عَبْدِ الرَّحْمَنِ الاصَمِّ عَنْ كَرَّامٍ قَالَ حَلَفْتُ فِيمَا بَيْنِي وَبَيْنَ نَفْسِي أَلا آكُلَ طَعَاماً بِنَهَارٍ أَبَداً حَتَّى يَقُومَ قَائِمُ آلِ مُحَمَّدٍ فَدَخَلْتُ عَلَى أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) قَالَ فَقُلْتُ لَهُ رَجُلٌ مِنْ شِيعَتِكُمْ جَعَلَ لله عَلَيْهِ أَلا يَأْكُلَ طَعَاماً بِنَهَارٍ أَبَداً حَتَّى يَقُومَ قَائِمُ آلِ مُحَمَّدٍ قَالَ فَصُمْ إِذاً يَا كَرَّامُ وَلا تَصُمِ الْعِيدَيْنِ وَلا ثَلاثَةَ التَّشْرِيقِ وَلا إِذَا كُنْتَ مُسَافِراً وَلا مَرِيضاً فَإِنَّ الْحُسَيْنَ (عَلَيْهِ السَّلام) لَمَّا قُتِلَ عَجَّتِ السَّمَاوَاتُ وَالارْضُ وَمَنْ عَلَيْهِمَا وَالْمَلائِكَةُ فَقَالُوا يَا رَبَّنَا ائْذَنْ لَنَا فِي هَلاكِ الْخَلْقِ حَتَّى نَجُدَّهُمْ عَنْ جَدِيدِ الارْضِ بِمَا اسْتَحَلُّوا حُرْمَتَكَ وَقَتَلُوا صَفْوَتَكَ فَأَوْحَى الله إِلَيْهِمْ يَا مَلائِكَتِي وَيَا سَمَاوَاتِي وَيَا أَرْضِيَ اسْكُنُوا ثُمَّ كَشَفَ حِجَاباً مِنَ الْحُجُبِ فَإِذَا خَلْفَهُ مُحَمَّدٌ (صَلَّى اللهُ عَلَيْهِ وَآلِه) وَاثْنَا عَشَرَ وَصِيّاً لَهُ (عَلَيْهِ السَّلام) وَأَخَذَ بِيَدِ فُلانٍ الْقَائِمِ مِنْ بَيْنِهِمْ فَقَالَ يَا مَلائِكَتِي وَيَا سَمَاوَاتِي وَيَا أَرْضِي بِهَذَا أَنْتَصِرُ لِهَذَا قَالَهَا ثَلاثَ مَرَّاتٍ.","1/4/126/19","مرآة العقول: ضعيف · البهبودي: لم يخرجه"],[20,12,"مُحَمَّدُ بْنُ يَحْيَى وَأَحْمَدُ بْنُ مُحَمَّدٍ عَنْ مُحَمَّدِ بْنِ الْحُسَيْنِ عَنْ أَبِي طَالِبٍ عَنْ عُثْمَانَ بْنِ عِيسَى عَنْ سَمَاعَةَ بْنِ مِهْرَانَ قَالَ كُنْتُ أَنَا وَأَبُو بَصِيرٍ وَمُحَمَّدُ بْنُ عِمْرَانَ مَوْلَى ابي جعفر (عَلَيْهِ السَّلام) فِي مَنْزِلِهِ بِمَكَّةَ فَقَالَ مُحَمَّدُ بْنُ عِمْرَانَ سَمِعْتُ أَبَا عَبْدِ الله (عَلَيْهِ السَّلام) يَقُولُ نَحْنُ اثْنَا عَشَرَ مُحَدَّثاً فَقَالَ لَهُ أَبُو بَصِيرٍ سَمِعْتَ مِنْ أَبِي عَبْدِ الله (عَلَيْهِ السَّلام) فَحَلَّفَهُ مَرَّةً أَوْ مَرَّتَيْنِ أَنَّهُ سَمِعَهُ فَقَالَ أَبُو بَصِيرٍ لَكِنِّي سَمِعْتُهُ مِنْ أَبِي جَعْفَرٍ (عَلَيْهِ السَّلام )","1/4/126/20","مرآة العقول: مجهول · البهبودي: لم يخرجه"],[1,13,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ سَهْلِ بْنِ زِيَادٍ عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ أَبِي نَصْرٍ عَنْ ثَعْلَبَةَ بْنِ مَيْمُونٍ عَنْ بَدْرِ بْنِ الْخَلِيلِ الْأَزْدِيِّ قَالَ كُنْتُ جَالِساً عِنْدَ أَبِي جَعْفَرٍ (عليه السلام) فَقَالَ آيَتَانِ تَكُونَانِ قَبْلَ قِيَامِ الْقَائِمِ (عليه السلام) لَمْ تَكُونَا مُنْذُ هَبَطَ آدَمُ إِلَى الْأَرْضِ تَنْكَسِفُ الشَّمْسُ فِي النِّصْفِ مِنْ شَهْرِ رَمَضَانَ وَ الْقَمَرُ فِي آخِرِهِ فَقَالَ رَجُلٌ يَا ابْنَ رَسُولِ اللَّهِ تَنْكَسِفُ الشَّمْسُ فِي آخِرِ الشَّهْرِ وَ الْقَمَرُ فِي النِّصْفِ فَقَالَ أَبُو جَعْفَرٍ (عليه السلام) إِنِّي أَعْلَمُ مَا تَقُولُ وَ لَكِنَّهُمَا آيَتَانِ لَمْ تَكُونَا مُنْذُ هَبَطَ آدَمُ (عليه السلام).","1/1/258/1","مرآة العقول: ضعيف · البهبودي: لم يخرجه","علامتان قبل قيام القائم (ع)"],[1,13,"عَنْهُ عَنْ مُعَلًّى عَنِ الْوَشَّاءِ عَنْ عَبْدِ الْكَرِيمِ بْنِ عَمْرٍو عَنْ عَمَّارِ بْنِ مَرْوَانَ عَنِ الْفُضَيْلِ بْنِ يَسَارٍ قَالَ قَالَ أَبُو جَعْفَرٍ (عليه السلام) إِذَا رَأَيْتَ الْفَاقَةَ وَ الْحَاجَةَ قَدْ كَثُرَتْ وَ أَنْكَرَ النَّاسُ بَعْضُهُمْ بَعْضاً فَعِنْدَ ذَلِكَ فَانْتَظِرْ أَمْرَ اللَّهِ عَزَّ وَ جَلَّ قُلْتُ جُعِلْتُ فِدَاكَ هَذِهِ الْفَاقَةُ وَ الْحَاجَةُ قَدْ عَرَفْتُهُمَا فَمَا إِنْكَارُ النَّاسِ بَعْضُهُمْ بَعْضاً قَالَ يَأْتِي الرَّجُلُ مِنْكُمْ أَخَاهُ فَيَسْأَلُهُ الْحَاجَةَ فَيَنْظُرُ إِلَيْهِ بِغَيْرِ الْوَجْهِ الَّذِي كَانَ يَنْظُرُ إِلَيْهِ وَ يُكَلِّمُهُ بِغَيْرِ اللِّسَانِ الَّذِي كَانَ يُكَلِّمُهُ بِهِ.","1/1/276/1","مرآة العقول: ضعيف · البهبودي: لم يخرجه","علامات الفرج"],[1,13,"عَنْهُ عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ مَحْبُوبٍ عَنِ الْأَحْوَلِ عَنْ سَلَّامِ بْنِ الْمُسْتَنِيرِ قَالَ سَمِعْتُ أَبَا جَعْفَرٍ (عليه السلام) يُحَدِّثُ إِذَا قَامَ الْقَائِمُ عَرَضَ الْإِيمَانَ عَلَى كُلِّ نَاصِبٍ فَإِنْ دَخَلَ فِيهِ بِحَقِيقَةٍ وَ إِلَّا ضَرَبَ عُنُقَهُ أَوْ يُؤَدِّيَ الْجِزْيَةَ كَمَا يُؤَدِّيهَا الْيَوْمَ أَهْلُ الذِّمَّةِ وَ يَشُدُّ عَلَى وَسَطِهِ الْهِمْيَانَ وَ يُخْرِجُهُمْ مِنَ الْأَمْصَارِ إِلَى السَّوَادِ.","1/1/288/1","البهبودي: لم يخرجه","القائم (ع) وأعداء الأئمة (ع)"],[1,13,"عِدَّةٌ مِنْ أَصْحَابِنَا عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ أَبِي نَجْرَانَ عَنْ مُحَمَّدِ بْنِ سِنَانٍ عَنْ أَبِي الْجَارُودِ عَنْ أَبِي جَعْفَرٍ (عليه السلام) قَالَ لَا تَرَوْنَ الَّذِي تَنْتَظِرُونَ حَتَّى تَكُونُوا كَالْمِعْزَى الْمُوَاتِ الَّتِي لَا يُبَالِي الْخَابِسُ أَيْنَ يَضَعُ يَدَهُ فِيهَا لَيْسَ لَكُمْ شَرَفٌ تَرْقَوْنَهُ وَ لَا سِنَادٌ تُسْنِدُونَ إِلَيْهِ أَمْرَكُمْ.","1/1/379/1","مرآة العقول: ضعيف · البهبودي: لم يخرجه","حال الشيعة في غيبة الإمام (ع)"],[1,13,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى عَنْ عَلِيِّ بْنِ الْحَكَمِ عَنْ أَبِي أَيُّوبَ الْخَزَّازِ عَنْ عُمَرَ بْنِ حَنْظَلَةَ قَالَ سَمِعْتُ أَبَا عَبْدِ اللَّهِ (عليه السلام) يَقُولُ خَمْسُ عَلَامَاتٍ قَبْلَ قِيَامِ الْقَائِمِ الصَّيْحَةُ وَ السُّفْيَانِيُّ وَ الْخَسْفُ وَ قَتْلُ النَّفْسِ الزَّكِيَّةِ وَ الْيَمَانِيُّ فَقُلْتُ جُعِلْتُ فِدَاكَ إِنْ خَرَجَ أَحَدٌ مِنْ أَهْلِ بَيْتِكَ قَبْلَ هَذِهِ الْعَلَامَاتِ أَ نَخْرُجُ مَعَهُ قَالَ لَا فَلَمَّا كَانَ مِنَ الْغَدِ تَلَوْتُ هَذِهِ الْآيَةَ إِنْ نَشَأْ نُنَزِّلْ عَلَيْهِمْ مِنَ السَّماءِ آيَةً فَظَلَّتْ أَعْناقُهُمْ لَها خاضِعِينَ فَقُلْتُ لَهُ أَ هِيَ الصَّيْحَةُ فَقَالَ أَمَا لَوْ كَانَتْ خَضَعَتْ أَعْنَاقُ أَعْدَاءِ اللَّهِ عَزَّ وَ جَلَّ.","1/1/483/1","مرآة العقول: حسن كالصحيح · البهبودي: صحيح","خمس علامات قبل قيام القائم (ع)"],[1,13,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدٍ عَنِ ابْنِ فَضَّالٍ عَنْ أَبِي جَمِيلَةَ عَنْ مُحَمَّدِ بْنِ عَلِيٍّ الْحَلَبِيِّ قَالَ سَمِعْتُ أَبَا عَبْدِ اللَّهِ (عليه السلام) يَقُولُ اخْتِلَافُ بَنِي الْعَبَّاسِ مِنَ الْمَحْتُومِ وَ النِّدَاءُ مِنَ الْمَحْتُومِ وَ خُرُوجُ الْقَائِمِ مِنَ الْمَحْتُومِ قُلْتُ وَ كَيْفَ النِّدَاءُ قَالَ يُنَادِي مُنَادٍ مِنَ السَّمَاءِ أَوَّلَ النَّهَارِ أَلَا إِنَّ عَلِيّاً وَ شِيعَتَهُ هُمُ الْفَائِزُونَ قَالَ وَ يُنَادِي مُنَادٍ فِي آخِرِ النَّهَارِ أَلَا إِنَّ عُثْمَانَ وَ شِيعَتَهُ هُمُ الْفَائِزُونَ.","1/1/484/1","مرآة العقول: ضعيف · البهبودي: لم يخرجه","علامات قيام القائم (ع)"],[1,13,"عَلِيُّ بْنُ إِبْرَاهِيمَ عَنْ أَبِيهِ عَنِ ابْنِ أَبِي عُمَيْرٍ عَنْ مَنْصُورِ بْنِ يُونُسَ عَنْ إِسْمَاعِيلَ بْنِ جَابِرٍ عَنْ أَبِي خَالِدٍ عَنْ أَبِي جَعْفَرٍ (عليه السلام) فِي قَوْلِ اللَّهِ عَزَّ وَ جَلَّ فَاسْتَبِقُوا الْخَيْراتِ أَيْنَ ما تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعاً قَالَ الْخَيْرَاتُ الْوَلَايَةُ وَ قَوْلُهُ تَبَارَكَ وَ تَعَالَى أَيْنَ ما تَكُونُوا يَأْتِ بِكُمُ اللَّهُ جَمِيعاً يَعْنِي أَصْحَابَ الْقَائِمِ الثَّلَاثَمِائَةِ وَ الْبِضْعَةَ عَشَرَ رَجُلًا قَالَ وَ هُمْ وَ اللَّهِ الْأُمَّةُ الْمَعْدُودَةُ قَالَ يَجْتَمِعُونَ وَ اللَّهِ فِي سَاعَةٍ وَاحِدَةٍ قَزَعٌ كَقَزَعِ الْخَرِيفِ.","1/1/487/1","مرآة العقول: حسن أو موثوق · البهبودي: لم يخرجه","أصحاب القائم (ع) ثلاثمائة وبضعة عشر"],[1,13,"مُحَمَّدُ بْنُ يَحْيَى عَنْ أَحْمَدَ بْنِ مُحَمَّدِ بْنِ عِيسَى وَ أَبُو عَلِيٍّ الْأَشْعَرِيُّ عَنْ مُحَمَّدِ بْنِ عَبْدِ الْجَبَّارِ جَمِيعاً عَنْ عَلِيِّ بْنِ حَدِيدٍ عَنْ جَمِيلٍ عَنْ زُرَارَةَ عَنْ أَبِي جَعْفَرٍ (عليه السلام) قَالَ سَأَلَهُ حُمْرَانُ فَقَالَ جَعَلَنِيَ اللَّهُ فِدَاكَ لَوْ حَدَّثْتَنَا مَتَى يَكُونُ هَذَا الْأَمْرُ فَسُرِرْنَا بِهِ فَقَالَ يَا حُمْرَانُ إِنَّ لَكَ أَصْدِقَاءَ وَ إِخْوَاناً وَ مَعَارِفَ إِنَّ رَجُلًا كَانَ فِيمَا مَضَى مِنَ الْعُلَمَاءِ وَ كَانَ لَهُ ابْنٌ لَمْ يَكُنْ يَرْغَبُ فِي عِلْمِ أَبِيهِ وَ لَا يَسْأَلُهُ عَنْ شَيْ‏ءٍ وَ كَانَ لَهُ جَارٌ يَأْتِيهِ وَ يَسْأَلُهُ وَ يَأْخُذُ عَنْهُ فَحَضَرَ الرَّجُلَ الْمَوْتُ فَدَعَا ابْنَهُ فَقَالَ يَا بُنَيَّ إِنَّكَ قَدْ كُنْتَ تَزْهَدُ فِيمَا عِنْدِي وَ تَقِلُّ رَغْبَتُكَ فِيهِ وَ لَمْ تَكُنْ تَسْأَلُنِي عَنْ شَيْ‏ءٍ وَ لِي جَارٌ قَدْ كَانَ يَأْتِينِي وَ يَسْأَلُنِي وَ يَأْخُذُ مِنِّي وَ يَحْفَظُ عَنِّي فَإِنِ احْتَجْتَ إِلَى شَيْ‏ءٍ فَأْتِهِ وَ عَرَّفَهُ جَارَهُ فَهَلَكَ الرَّجُلُ وَ بَقِيَ ابْنُهُ فَرَأَى مَلِكُ ذَلِكَ الزَّمَانِ رُؤْيَا فَسَأَلَ عَنِ الرَّجُلِ فَقِيلَ لَهُ قَدْ هَلَكَ فَقَالَ الْمَلِكُ هَلْ تَرَكَ وَلَداً فَقِيلَ لَهُ نَعَمْ تَرَكَ ابْناً فَقَالَ ائْتُونِي بِهِ فَبُعِثَ إِلَيْهِ لِيَأْتِيَ الْمَلِكَ فَقَالَ الْغُلَامُ وَ اللَّهِ مَا أَدْرِي لِمَا يَدْعُونِي الْمَلِكُ وَ مَا عِنْدِي عِلْمٌ وَ لَئِنْ سَأَلَنِي عَنْ شَيْ‏ءٍ لَأَفْتَضِحَنَّ فَذَكَرَ مَا كَانَ أَوْصَاهُ أَبُوهُ بِهِ فَأَتَى الرَّجُلَ الَّذِي كَانَ يَأْخُذُ الْعِلْمَ مِنْ أَبِيهِ فَقَالَ لَهُ إِنَّ الْمَلِكَ قَدْ بَعَثَ إِلَيَّ يَسْأَلُنِي وَ لَسْتُ أَدْرِي فِيمَ بَعَثَ إِلَيَّ وَ قَدْ كَانَ أَبِي أَمَرَنِي أَنْ آتِيَكَ إِنِ احْتَجْتُ إِلَى شَيْ‏ءٍ فَقَالَ الرَّجُلُ وَ لَكِنِّي أَدْرِي فِيمَا بَعَثَ إِلَيْكَ فَإِنْ أَخْبَرْتُكَ فَمَا أَخْرَجَ اللَّهُ لَكَ مِنْ شَيْ‏ءٍ فَهُوَ بَيْنِي وَ بَيْنَكَ فَقَالَ نَعَمْ فَاسْتَحْلَفَهُ وَ اسْتَوْثَقَ مِنْهُ أَنْ يَفِيَ لَهُ فَأَوْثَقَ لَهُ الْغُلَامُ فَقَالَ إِنَّهُ يُرِيدُ أَنْ يَسْأَلَكَ عَنْ رُؤْيَا رَآهَا أَيُّ زَمَانٍ هَذَا فَقُلْ لَهُ هَذَا زَمَانُ الذِّئْبِ فَأَتَاهُ الْغُلَامُ فَقَالَ لَهُ الْمَلِكُ هَلْ تَدْرِي لِمَ أَرْسَلْتُ إِلَيْكَ فَقَالَ أَرْسَلْتَ إِلَيَّ تُرِيدُ أَنْ تَسْأَلَنِي عَنْ رُؤْيَا رَأَيْتَهَا أَيُّ زَمَانٍ هَذَا فَقَالَ لَهُ الْمَلِكُ صَدَقْتَ فَأَخْبِرْنِي أَيُّ زَمَانٍ هَذَا فَقَالَ لَهُ زَمَانُ الذِّئْبِ فَأَمَرَ لَهُ بِجَائِزَةٍ فَقَبَضَهَا الْغُلَامُ وَ انْصَرَفَ إِلَى مَنْزِلِهِ وَ أَبَى أَنْ يَفِيَ لِصَاحِبِهِ وَ قَالَ لَعَلِّي لَا أُنْفِدُ هَذَا الْمَالَ وَ لَا آكُلُهُ حَتَّى أَهْلِكَ وَ لَعَلِّي لَا أَحْتَاجُ وَ لَا أُسْأَلُ عَنْ مِثْلِ هَذَا الَّذِي سُئِلْتُ عَنْهُ فَمَكَثَ مَا شَاءَ اللَّهُ ثُمَّ إِنَّ الْمَلِكَ رَأَى رُؤْيَا فَبَعَثَ إِلَيْهِ يَدْعُوهُ فَنَدِمَ عَلَى مَا صَنَعَ وَ قَالَ وَ اللَّهِ مَا عِنْدِي عِلْمٌ آتِيهِ بِهِ وَ مَا أَدْرِي كَيْفَ أَصْنَعُ بِصَاحِبِي وَ قَدْ غَدَرْتُ بِهِ وَ لَمْ أَفِ لَهُ ثُمَّ قَالَ لآَتِيَنَّهُ عَلَى كُلِّ حَالٍ وَ لَأَعْتَذِرَنَّ إِلَيْهِ وَ لَأَحْلِفَنَّ لَهُ فَلَعَلَّهُ يُخْبِرُنِي فَأَتَاهُ فَقَالَ لَهُ إِنِّي قَدْ صَنَعْتُ الَّذِي صَنَعْتُ وَ لَمْ أَفِ لَكَ بِمَا كَانَ بَيْنِي وَ بَيْنَكَ وَ تَفَرَّقَ مَا كَانَ فِي يَدِي وَ قَدِ احْتَجْتُ إِلَيْكَ فَأَنْشُدُكَ اللَّهَ أَنْ لَا تَخْذُلَنِي وَ أَنَا أُوثِقُ لَكَ أَنْ لَا يَخْرُجَ لِي شَيْ‏ءٌ إِلَّا كَانَ بَيْنِي وَ بَيْنَكَ وَ قَدْ بَعَثَ إِلَيَّ الْمَلِكُ وَ لَسْتُ أَدْرِي عَمَّا يَسْأَلُنِي فَقَالَ إِنَّهُ يُرِيدُ أَنْ يَسْأَلَكَ عَنْ رُؤْيَا رَآهَا أَيُّ زَمَانٍ هَذَا فَقُلْ لَهُ إِنَّ هَذَا زَمَانُ الْكَبْشِ فَأَتَى الْمَلِكَ فَدَخَلَ عَلَيْهِ فَقَالَ لِمَا بَعَثْتُ إِلَيْكَ فَقَالَ إِنَّكَ رَأَيْتَ رُؤْيَا وَ إِنَّكَ تُرِيدُ أَنْ تَسْأَلَنِي أَيُّ زَمَانٍ هَذَا فَقَالَ لَهُ صَدَقْتَ فَأَخْبِرْنِي أَيُّ زَمَانٍ هَذَا فَقَالَ هَذَا زَمَانُ الْكَبْشِ فَأَمَرَ لَهُ بِصِلَةٍ فَقَبَضَهَا وَ انْصَرَفَ إِلَى مَنْزِلِهِ وَ تَدَبَّرَ فِي رَأْيِهِ فِي أَنْ يَفِيَ لِصَاحِبِهِ أَوْ لَا يَفِيَ لَهُ فَهَمَّ مَرَّةً أَنْ يَفْعَلَ وَ مَرَّةً أَنْ لَا يَفْعَلَ ثُمَّ قَالَ لَعَلِّي أَنْ لَا أَحْتَاجَ إِلَيْهِ بَعْدَ هَذِهِ الْمَرَّةِ أَبَداً وَ أَجْمَعَ رَأْيَهُ عَلَى الْغَدْرِ وَ تَرْكِ الْوَفَاءِ فَمَكَثَ مَا شَاءَ اللَّهُ ثُمَّ إِنَّ الْمَلِكَ رَأَى رُؤْيَا فَبَعَثَ إِلَيْهِ فَنَدِمَ عَلَى مَا صَنَعَ فِيمَا بَيْنَهُ وَ بَيْنَ صَاحِبِهِ وَ قَالَ بَعْدَ غَدْرٍ مَرَّتَيْنِ كَيْفَ أَصْنَعُ وَ لَيْسَ عِنْدِي عِلْمٌ ثُمَّ أَجْمَعَ رَأْيَهُ عَلَى إِتْيَانِ الرَّجُلِ فَأَتَاهُ فَنَاشَدَهُ اللَّهَ تَبَارَكَ وَ تَعَالَى وَ سَأَلَهُ أَنْ يُعَلِّمَهُ وَ أَخْبَرَهُ أَنَّ هَذِهِ الْمَرَّةَ يَفِي مِنْهُ وَ أَوْثَقَ لَهُ وَ قَالَ لَا تَدَعْنِي عَلَى هَذِهِ الْحَالِ فَإِنِّي لَا أَعُودُ إِلَى الْغَدْرِ وَ سَأَفِي لَكَ فَاسْتَوْثَقَ مِنْهُ فَقَالَ إِنَّهُ يَدْعُوكَ يَسْأَلُكَ عَنْ رُؤْيَا رَآهَا أَيُّ زَمَانٍ هَذَا فَإِذَا سَأَلَكَ فَأَخْبِرْهُ أَنَّهُ زَمَانُ الْمِيزَانِ قَالَ فَأَتَى الْمَلِكَ فَدَخَلَ عَلَيْهِ فَقَالَ لَهُ لِمَ بَعَثْتُ إِلَيْكَ فَقَالَ إِنَّكَ رَأَيْتَ رُؤْيَا وَ تُرِيدُ أَنْ تَسْأَلَنِي أَيُّ زَمَانٍ هَذَا فَقَالَ صَدَقْتَ فَأَخْبِرْنِي أَيُّ زَمَانٍ هَذَا فَقَالَ هَذَا زَمَانُ الْمِيزَانِ فَأَمَرَ لَهُ بِصِلَةٍ فَقَبَضَهَا وَ انْطَلَقَ بِهَا إِلَى الرَّجُلِ فَوَضَعَهَا بَيْنَ يَدَيْهِ وَ قَالَ قَدْ جِئْتُكَ بِمَا خَرَجَ لِي فَقَاسِمْنِيهِ فَقَالَ لَهُ الْعَالِمُ إِنَّ الزَّمَانَ الْأَوَّلَ كَانَ زَمَانَ الذِّئْبِ وَ إِنَّكَ كُنْتَ مِنَ الذِّئَابِ وَ إِنَّ الزَّمَانَ الثَّانِيَ كَانَ زَمَانَ الْكَبْشِ يَهُمُّ وَ لَا يَفْعَلُ وَ كَذَلِكَ كُنْتَ أَنْتَ تَهُمُّ وَ لَا تَفِي وَ كَانَ هَذَا زَمَانَ الْمِيزَانِ وَ كُنْتَ فِيهِ عَلَى الْوَفَاءِ فَاقْبِضْ مَالَكَ لَا حَاجَةَ لِي فِيهِ وَ رَدَّهُ عَلَيْهِ.","1/1/552/1","مرآة العقول: ضعيف · البهبودي: لم يخرجه","متى يظهر القائم (ع)"]],"name":"الكافي — أبواب الحجة والغيبة","author":"ثقة الإسلام الكليني (ت 329 هـ)","blurb":"أبواب مختارة من كتاب الحجة في أصول الكافي (الأرض لا تخلو من حجة، النص على الاثني عشر، صاحب الدار، الغيبة، التوقيت، التمحيص) مع أحاديث من الروضة، ومعها تقييم المجلسي في مرآة العقول حيث ورد.","book":"https://thaqalayn.net/book/Al-Kafi-Volume-1-Kulayni"};